// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":8,"question":"سائلٌ عنده سؤالان: يقول في سؤاله الأول: ما حكم الصيام بالنسبة للمُجاهد في ميدان المعركة في شهر رمضان؟ هل يجب على مَن يُجاهد في سبيل الله في رمضان الصيام أم لا؟","title":"حكم الصوم والفطر للمجاهد في المعركة","answer":"الجواب: هذا أفتى به جماعةٌ من أهل العلم، ونصر ذلك أبو العباس ابن تيمية شيخ الإسلام، وأنَّ المُجاهد له أن يُفطر، فإذا جاز للمُسافر والمريض أن يُفطر فالمجاهد أولى بذلك؛ لأنه في حالةٍ لا تسمح له بالصوم، واستدلُّوا على هذا بقوله ﷺ لأصحابه لما دنوا من مكة: أفطروا؛ فإنَّ الفطر أقوى لكم في قتال عدوكم، فأمرهم بالفطر، وعلله بأنَّ الفطر أقوى لهم، قالوا: هذه علَّة تدل على وجوب الإفطار في حال الحرب، ولو كان في الحضر، ولو كان المُعتدى عليه في الحضر؛ لأنَّهم -ولا سيَّما في أيام الصيف- لا يستطيعون أن يُجاهدوا مع الصوم.\nفالمقصود أنهم إذا احتاجوا للفطر أفطروا، ثم يقضون بعد ذلك؛ من جهة العلَّة، مراعاةً للعلة، كما أن الإنسان لو وجد إنسانًا غريقًا أو حريقًا لا يستطيع إنقاذه إلا بالفطر أفطر، ولو في الحضر، حتى يُنقذ أخاه الذي وقع في الحريق أو في الغرق أو ما أشبه ذلك، فالمقصود أنَّ هذه علَّة وجيهة وشرعية، وهي قوتهم على قتال عدوهم.","link":"https://binbaz.org.sa/fatwas/2785/حكم-الصوم-والفطر-للمجاهد-في-المعركة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0259.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":335,"question":"ما الحكم الشرعي لصيام المُسافر؟","title":"ما الأفضل للمسافر: الصوم أم الفِطر؟","answer":"الجواب: حكم المسافر أنه مُخَيَّر: إن شاء صام، وإن شاء أفطر، والفطر أفضل؛ لقول النبي ﷺ: ليس من البِرِّ الصومُ في السفر، فإن أفطر فهو أفضل، وإن صام لأنَّ الصوم أرفق به فلا بأس، وقد صام النبيُّ ﷺ والصَّحابة وأفطروا.","link":"https://binbaz.org.sa/fatwas/4423/ما-الافضل-للمسافر-الصوم-ام-الفطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0388.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":339,"question":"هل يجوز للصائم أن يُفطر إذا كان مُسافرًا وهو صائم واشتدَّ عليه الصومُ؟ وماذا عليه إذا أفطر؟","title":"حكم صوم المسافر والرخصة في الفطر","answer":"الجواب: المسافر ولو ما اشتدَّ عليه عذر شرعي، الله يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، إذا غادر البلد وخرج من البلد للسفر فله الفطر، كالذي يخرج من الرياض للعمرة أو لبلدٍ أخرى فله الفطر.","link":"https://binbaz.org.sa/fatwas/4427/حكم-صوم-المسافر-والرخصة-في-الفطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0392.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":418,"question":"امرأة أنجبت مولودًا في شهر رمضان قبل عشرين سنة، ولم تقضه حتى الآن، فما العمل؟ علمًا بأنها أفطرت الشهر جميعه؛ لأنها نُفساء، وهي جاهلة.","title":"حكم من أفطرت برمضان منذ سنين ولم تقض","answer":"الجواب: عليها التوبة إلى الله؛ لأنها قصرت في عدم السؤال، وهذا أمرٌ معلومٌ بين المسلمين، ليس بمجهولٍ -صيام رمضان- فالواجب عليها التوبة إلى الله، والندم، وصوم هذه الأيام، صوم الشهر الذي أفطرته، تصومه وتُطعم عن كل يومٍ مسكينًا إذا كانت تستطيع، فإن كانت فقيرةً عاجزةً تصوم وليس عليها شيء، وإن كانت تستطيع تصوم وتُطعم عن كل يوم نصفَ صاعٍ من التمر أو الرز، عن جميع الأيام، يُعطاها بعض الفقراء.","link":"https://binbaz.org.sa/fatwas/4842/حكم-من-افطرت-برمضان-منذ-سنين-ولم-تقض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0476.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام","الرقائق"]},{"id":712,"question":"امرأة تعمل غسيل كُلَوي، ولخروج الدم من جسدها لا تصوم معظم أيام رمضان، هل لها أن تقضي؟ وإذا كانت لا تستطيع فما رأي سماحتكم؟","title":"حكم الصوم للمريض بالفشل الكُلَوي","answer":"السؤال: إذا قرر الأطباء أنها لا تستطيع فلا تصوم، بل يؤجل الصوم حتى تستطيع فتقضي، فإن قرر الأطباء الثِّقات أنها يضرُّها الصومُ مطلقًا، وأنَّ بدنها لا يتحمَّل لأجل حاجتها إلى الغسيل، وعدم وجود كلية تقوم بحالها، حتى ولو كان فيها كلية فهي في حاجةٍ إلى عدم  الصوم، فإنها لا تصوم، تُطْعِم عن كل يومٍ مسكينًا كالشيخ الكبير والعجوز الكبيرة اللذين لا يستطيعان، وكصاحب المرض الذي لا يُرجى برؤه، فإنه يُطعم ولا يصوم، عن كل يومٍ نصف صاعٍ من رمضان، يُجمع ويُعطى بعض الفقراء، أما ما دامت ترجو العافية والأطباء يقولون: يُرجى لها العافية، وأنها تستطيع في المستقبل؛ فيبقى عليها في ذمَّتها حتى تستطيع، ثم تصوم.\nأما إذا قرر الأطباء أنها لا تستطيع، وأن المشروع لها أن تستمر في الأكل والشرب؛ لأنَّ عدم الشرب يضرُّها، فإنها تُفطر دائمًا وتُطْعِم عن كل يومٍ مسكينًا، كالشيخ الكبير والعجوز الكبيرة اللذين لا يستطيعان الصيام لكبر سنِّهما.","link":"https://binbaz.org.sa/fatwas/20573/حكم-الصوم-للمريض-بالفشل-الكلوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0527فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":741,"question":"سماحة الشيخ، إنَّ والدي رحمه الله تُوفي وهو مريضٌ وكبير السن، وإنه لم يصم قبل وفاته ثلاث سنوات، والسبب أنه كان مريضًا وكبير السن ومريضًا بالسكري أيضًا؛ لا يستغني عن الماء لحظات، أرجو الإجابة وفَّقكم الله.","title":"حكم صيام كبير السن المريض بالسكر","answer":"الجواب: ما دام بهذه الحال ليس عليه صومٌ، ولكن عليه الإطعام، أن تُطعموا عنه عن كلِّ يومٍ مسكينًا؛ لأنَّ كبير السن إذا شقَّ عليه الصومُ يُطعم عنه عن كلِّ يوم مسكين، ولا قضاء عليه، ولا قضاء عليكم أيضًا، إنما الإطعام، إذا كنتم ما أطعمتم أطعموا عنه عن كل يومٍ نصف صاعٍ من قوت البلد: من تمر، أو أرز، أو حنطة، تُعطى بعض الفقراء، تُجمع وتُعطى لبعض الفقراء، ولو فقيرًا واحدًا، ولو أهل بيتٍ من الفقراء، إذا جُمعت تُسلّم لفقيرٍ أو فقيرين أو أكثر والحمد لله، والمقدار: نصف الصاع، كيلو ونصف تقريبًا.","link":"https://binbaz.org.sa/fatwas/20633/حكم-صيام-كبير-السن-المريض-بالسكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0560حكم صيام الكبيرالسن المريض بالسكر الذي لا يستغني عن الماء لحظات ابن باز فتاوى المحاضرات.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":1076,"question":"سماحة الشيخ عبدالعزيز بن باز -وفَّقه الله- لقد قدر الله عليَّ بفشل كلوي، وزرعت كلية، ونصحني الأطباء بعدم صيام رمضان، فأرجو من الله ثم من سماحتكم التوجيه والسّداد، وهل عليَّ كفَّارة أم لا؟ ولكم جزيل الشكر.","title":"حكم الصوم لمريض الفشل الكلوي","answer":"الجواب:\nهذا يرجع إليك: إذا كنتَ تحسّ بما قال الأطباء من أنه يضرّك الصوم لا بأس، حتى يزول الضَّرر؛ لأن الله يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، وأنت مريضٌ بالكُلْيَة - الصواب الكُلْيَة -  إذا نصحك الأطباء العارفون ألا تصوم لا تصم، لكن إذا وجدتَ من نفسك ما يدلك على أنها لا تضرّك وجربتَ هذا الأمر ولا يضرّك؛ فصُمْ والحمد لله؛ لأنك إذا علمتَ أنَّ هذا لا يضرّك فأنت لستَ بمريضٍ، فعليك أن تصوم، وما دمت تحسّ بالمرض إذا صمتَ كما قال الأطباء فلا تصم حتى تُشْفَى. وإذا قرر الأطباء أنه يضرّك دائمًا فإنَّ عليك إطعام مسكينٍ عن كل يومٍ، مثل: الشيخ الكبير الهَرِم والعجوز الكبيرة العاجزين عن الصوم، يُطعمان عن كل يوم مسكينًا، ولا صوم عليهما. إذا قرر الطبيبُ المختص، والأحسن طبيبان أو أكثر، تحتاط لنفسك، إذا قرروا أنه لا يمكن الصوم، وأنه يضرُّك مطلقًا؛ فإنك تُطْعِم، إذا قالوا: إنَّ هذا المرض بالكلية يستمر -إذا كنتَ ركبت كُلية- وأما إذا كان عندهم ترددٌ أو اختلفوا، فعليك أن تصوم، فإذا أحسستَ بمرضٍ أفطر، وإذا أحسستَ بالصحة فاستمر على الصوم، وأنت طبيب نفسك، تعرف ما يضرُّك وما ينفعك.","link":"https://binbaz.org.sa/fatwas/21141/حكم-الصوم-لمريض-الفشل-الكلوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0937يقول السائل أنا مريض بالفشل الكلوي ونصحني الأطباء بعدم الصوم فهل أصوم.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":1287,"question":"زوجتي لم تتمكن من صيام رمضان لشهرٍ كاملٍ، بناءً على نصيحة الطبيب، نتيجة الحمل، وقد مرَّ على هذا حوالي أربع سنوات ولم تتمكن من صيامه حتى الآن، فماذا يجب عليها في ذلك، جزاكم الله خيرًا؟","title":"حكم الحامل التي تعجز عن صيام رمضان","answer":"الجواب:\nعليها أن تصوم متى قدرت، ولو بعد عشر سنين، متى قدرت تصوم، ما دام ما عندها المرض الذي لا يُرجى برؤه، بل إنما هو الحمل ونحوه وهو الرضاع، متى استطاعت تصوم، ولو مُفرَّقًا: يوم تصوم، ويوم تُفطر، حتى تنتهي، ولو بعد سنوات كثيرة؛ لأنَّ الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].","link":"https://binbaz.org.sa/fatwas/21348/حكم-الحامل-التي-تعجز-عن-صيام-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1091زوجتي لم تتمكن من صيام رمضان لشهر كامل بسبب الحمل فما يجب عليها؟.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":1318,"question":"في واحد فيه فشل كُلَوِي وسنه فوق السبعين وبعدين ركّبوا له كلية واحدة مزروعة، وواحدة فاشلة، وعلى أنه... العام عشرة أيام والدكاترة منعوا عنه الصيام؟","title":"حكم مَن عجز عن صوم رمضان للمرض","answer":"الجواب:\nيطعم مسكينًا عن كل يوم، يطعم مسكينًا نصف الصاع كل يوم\nس: ورمضان؟\nج: وهو كذلك، إذا كان يعجز إذا قرروا أنه لا يصوم أبدًا؛ يطعم عن كل يوم مسكينًا نصف صاع.\n س: كم؟\nج: كيلو ونصف، نصف الصاع من التمر أو الأرز أو الحنطة.\nس: يوميًّا؟\nج: لا هو ما هو بلازم، يجمعها جميعًا ويعطيها بعض الفقراء عن الشهر كله.","link":"https://binbaz.org.sa/fatwas/21409/حكم-من-عجز-عن-صوم-رمضان-للمرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من أفطر في رمضان لمرض أصابه.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":1532,"question":"أصبتُ بمرضٍ في أول رمضان العام، وفقدتُ شعوري، وما شعرتُ بالدنيا إلا بعد رمضان؟","title":"حكم القضاء على مَن أصيب بغيبوبة كل رمضان","answer":"الجواب:\nيعني: غيبوبة؟\nس: نعم تقريبًا حول الغيبوبة.\nج: إذا ذهب عقلُك فلا شيءَ عليك، وإن كان عقلك معك تقضي، هل لم تكن تعقل شيئًا؟\nس: نعم.\nج: ما عليك شيء.\nس: لا إطعام ولا صيام؟\nج: لا إطعام ولا صيام؛ لأنه كالمجنون وكالمعتوه، وقد رُفِعَ القلمُ عن ثلاثةٍ.","link":"https://binbaz.org.sa/fatwas/21632/حكم-القضاء-على-من-اصيب-بغيبوبة-كل-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصيام على من زال عقله.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام","قضايا المرأة"]},{"id":2672,"question":"الرسول ﷺ أفطر في السفر؟","title":"هل صح أن الرسول ﷺ أفطر في السفر؟","answer":"الجواب: صام وأفطر، تارة يصوم وتارة يفطر، الأمر واسع في السفر، والأفضل الفطر، الأفضل في السفر الفطر.\nس: يؤخذ من هذا جواز الصيام والفطر؟\nالشيخ: نعم؛ يجوز يصوم، ويجوز يفطر.\nس: الآن فيه سيارات ما في مشقة كما كانت؟\nالشيخ: ولَوْ، الفِطْر أفضل، قال النبي ﷺ: ليس من البر الصوم في السفر.","link":"https://binbaz.org.sa/fatwas/22810/هل-صح-ان-الرسول-ﷺ-افطر-في-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفطر في السفر.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":2689,"question":"الصيام الآن.. لمن ذهب في سفر...؟","title":"هل الأفضل في السفر الفِطْر أم الصوم؟","answer":"الجواب: الأفضل في السفر الفِطْر، وإن صام فلا بأس إن كان ما عليه مشقة، إذا صام في السفر رمضان أو غيره فلا بأس، إذا فارق البلد صام، إذا فارق البلد أفطر، وإن استمر بالصيام في السفر فلا حرج، النبي ﷺ صام وأفطر، والصحابة صاموا وأفطروا.\nس:  عند المطار يبدأ الإفطار...؟\nالشيخ: الإفطار إذا فارق البلد، إذا فارق عمل البلد في أي بلد.\nس: يكون الاستحباب على الأصل؟\nالشيخ: الفطر أفضل في السفر مطلقًا، وإذا اشتد الحرُّ يكون أشد تأكُّدًا، يعني ليس من البر الصوم في السفر.\nس: لا يفطر أيام البيض، في حَضَر مداوم عليها؟\nالشيخ: إذا صامها جزاه الله خيرًا، إذا استطاع طَيِّب، جاء فيها عدة أحاديث، ما هو حديث واحد.","link":"https://binbaz.org.sa/fatwas/22828/هل-الافضل-في-السفر-الفطر-ام-الصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما الأفضل في السفر الفطر أم الصوم.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":3669,"question":"رجل أراد السفر في نهار رمضان، وأراد أن يأتي أهله...؟","title":"هل يجوز الوطء لو أراد السفر نهار رمضان؟","answer":"الجواب: ليس له ذلك، ليس له أن يطأها وهي صائمة وهو صائم، وليس له أن يفطر حتى يغادر بلده.","link":"https://binbaz.org.sa/fatwas/23857/هل-يجوز-الوطء-لو-اراد-السفر-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في السفر في نهار رمضان.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":5851,"question":"امرأة مرضت في شهر رمضان، وأفطرت أيامًا منه، والآن شفيت من المرض، لكن [لا] تستطيع صيام الأيام التي فطرتها؟","title":"من أفطرت في رمضان لمرض ولم تستطع القضاء","answer":"الجواب: لعلها لا تستطيع، على كل حال من أفطرت في رمضان، أو أفطر غيرها من الرجال، ثم عافاه الله، أو عافاها الله؛ عليهما القضاء، الله يقول -جل وعلا-: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فعلى المريضة، والمريض إذا شفي أن يقضي ما أفطره من رمضان، ولا يلزمهما أن يكون متتابعًا، ولو مفرقًا يصوم، ويفطر حتى يكمل، لا بأس بأن يقضي مفرقًا.  فإن كان لا يستطيع؛ لأن المرض باقٍ؛ فيبقى عليه الدين في ذمته حتى يستطيع، وحتى يشفى، ولو بعد أعوام، ما دام المرض يرجى زواله، وليس بميئوس منه، فالصوم يبقى في الذمة حتى يشفى، ثم يقضي بعد ذلك، ولو بعد رمضانات، ما دام المرض معه، حتى إذا عرف الأطباء أن هذا المرض لا يزول، وأنه مستمر، وأن مثله يستمر؛ فحينئذ يطعم عن كل يوم مسكينًا، ولا قضاء عليه، يطعم عن كل يوم مسكينًا، نصف صاع من قوت البلد إذا كان قادرًا، ولا شيء عليه بعد ذلك، هذا إذا قرر الأطباء أن هذا المرض مثله، لا يرجى برؤه مثله يستمر، أما ما دام المرض يرجى برؤه، ويرجى زواله؛ فإن الصوم يبقى في الذمة، فإذا شفي الإنسان من رجل، أو امرأة، إذا شفي؛ قضى قضاء غير متتابع، ما هو بلازم متتابع، إن تتابع؛ فهو أفضل، وإلا فلا يلزمه التتابع، إذا قضى مفرقًا، يصوم، ويفطر حتى ينهي ما عليه؛ فلا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/1189/من-افطرت-في-رمضان-لمرض-ولم-تستطع-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_185.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام","قضايا المرأة"]},{"id":5856,"question":"امرأة مرضت في شهر رمضان، وأفطرت أيامًا منه، والآن شفيت من المرض، لكن [لا] تستطيع صيام الأيام التي فطرتها؟","title":"من أفطرت في رمضان لمرض ولم تستطع القضاء","answer":"الجواب: لعلها لا تستطيع، على كل حال من أفطرت في رمضان، أو أفطر غيرها من الرجال، ثم عافاه الله، أو عافاها الله؛ عليهما القضاء، الله يقول -جل وعلا-: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فعلى المريضة، والمريض إذا شفي أن يقضي ما أفطره من رمضان، ولا يلزمهما أن يكون متتابعًا، ولو مفرقًا يصوم، ويفطر حتى يكمل، لا بأس بأن يقضي مفرقًا.  فإن كان لا يستطيع؛ لأن المرض باقٍ؛ فيبقى عليه الدين في ذمته حتى يستطيع، وحتى يشفى، ولو بعد أعوام، ما دام المرض يرجى زواله، وليس بميئوس منه، فالصوم يبقى في الذمة حتى يشفى، ثم يقضي بعد ذلك، ولو بعد رمضانات، ما دام المرض معه، حتى إذا عرف الأطباء أن هذا المرض لا يزول، وأنه مستمر، وأن مثله يستمر؛ فحينئذ يطعم عن كل يوم مسكينًا، ولا قضاء عليه، يطعم عن كل يوم مسكينًا، نصف صاع من قوت البلد إذا كان قادرًا، ولا شيء عليه بعد ذلك، هذا إذا قرر الأطباء أن هذا المرض مثله، لا يرجى برؤه مثله يستمر، أما ما دام المرض يرجى برؤه، ويرجى زواله؛ فإن الصوم يبقى في الذمة، فإذا شفي الإنسان من رجل، أو امرأة، إذا شفي؛ قضى قضاء غير متتابع، ما هو بلازم متتابع، إن تتابع؛ فهو أفضل، وإلا فلا يلزمه التتابع، إذا قضى مفرقًا، يصوم، ويفطر حتى ينهي ما عليه؛ فلا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/1189/من-افطرت-في-رمضان-لمرض-ولم-تستطع-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_185.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام","قضايا المرأة"]},{"id":6302,"question":"هل يجوز للمسلم أن يذهب للعمرة في رمضان، ويفطر في سفره، أم الأفضل أن يصوم، ويترك العمرة بعد الصيام؟","title":"حكم الإفطار لمن سافر في رمضان للعمرة","answer":"الجواب: الأفضل أن يعتمر في رمضان، النبي ﷺ قال: عمرة في رمضان تعدل حجة العمرة في رمضان لها شأن، عمرة في رمضان تعدل حجة وفي رواية: حجة معي مع النبي ﷺ فهذا فضل عظيم.  وإذا سافر؛ فهو بالخيار، إن شاء أفطر بالطريق، وإن شاء صام، الأمر في هذا واسع، والحمد لله، وإذا كان في مكة كذلك، إذا كانت إقامته في مكة قليلًا يومين، أو ثلاث، أو أربع له أن يفطر، وله أن يصوم. أما إذا كان يقيم أكثر من أربعة أيام؛ فإنه يصوم في مكة، ولا يفطر إذا كان أراد الإقامة في مكة أكثر من أربعة أيام، أما إذا كان يريد العمرة، ويرجع، أو يبقى يوم، أو يومين مثلًا، أو ثلاث؛ فهذا له الفطر، وله الصوم، مخير.","link":"https://binbaz.org.sa/fatwas/1815/حكم-الافطار-لمن-سافر-في-رمضان-للعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_656.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":6878,"question":"هل إذا كان الإنسان مريضًا مرضًا زمنًا طويلًا، ولا يقدر على الصيام في شهر رمضان، ما الحكم عليه؟","title":"حكم الفطر في رمضان بسبب مرض لا يرجى برؤه","answer":"الجواب:\nإذا كان وقت رمضان مريضًا فإنه يفطر، والله جعل له رخصة  فقال : وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]. فالرخصة له أن يفطر، ثم يقضي بعد ذلك إذا عافاه الله، يقضي، هذا هو المشروع له، ولا يكلف نفسه الصوم إذا كان يشق عليه، بل يفطر، ويقضي بعد ذلك كالمسافر.","link":"https://binbaz.org.sa/fatwas/2773/حكم-الفطر-في-رمضان-بسبب-مرض-لا-يرجى-بروه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1265.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":6894,"question":"هل إذا كان الإنسان مريضًا مرضًا زمنًا طويلًا، ولا يقدر على الصيام في شهر رمضان، ما الحكم عليه؟","title":"حكم الفطر في رمضان بسبب مرض لا يرجى برؤه","answer":"الجواب:\nإذا كان وقت رمضان مريضًا فإنه يفطر، والله جعل له رخصة  فقال : وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]. فالرخصة له أن يفطر، ثم يقضي بعد ذلك إذا عافاه الله، يقضي، هذا هو المشروع له، ولا يكلف نفسه الصوم إذا كان يشق عليه، بل يفطر، ويقضي بعد ذلك كالمسافر.","link":"https://binbaz.org.sa/fatwas/2773/حكم-الفطر-في-رمضان-بسبب-مرض-لا-يرجى-بروه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1265.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":6911,"question":"قرأنا في جريدة المسلمون مقالًا لفضيلة الشيخ محمد بن صالح العثيمين يقول: إن المتعاقد في بلد أجنبي غير بلده لا يجب عليه الصيام، فما صحة هذا القول، أفتونا جزاكم الله خيراً؟","title":"حكم الصيام للمتعاقد في بلد أجنبي","answer":"الجواب: هذا قول بعض أهل العلم، إن المتعاقد الذي لم يستوطن، وإنما تعاقد، أو جاء طالبًا للعلم، ثم يرجع إلى بلده أن له حكم المسافرين في الإفطار، وفي القصر، وعليه قضاء الصوم، ولكنه قول لبعض أهل العلم، والجمهور من العلماء، وهو الذي عليه الفتوى: أنه لا يفطر، ولا يقصر، بل عليه أن يصوم مع الناس، وعليه أن يتم مع الناس؛ لأنه في حكم المستوطنين. والذي ثبت في هذا عند جمهور أهل العلم: أن الإقامة عند الأكثر ما زاد على أربعة أيام، لها حكم الإقامة التامة، فعليه أن يتم، ويصوم، وقال بعض أهل العلم: خمسة عشر يومًا، والجمهور من أهل العلم على أن الإقامة المانعة ما زاد على أربعة أيام -إذا نواها وعزم عليها- أتم، ولم يقصر، وعلى المتعاقدين، والطلبة في أي مكان أن يصوموا في رمضان، وأن يتموا الصلاة، ولا يقصروها؛ لأنهم في هذه الإقامة الطويلة لا يسمون مسافرين.","link":"https://binbaz.org.sa/fatwas/2842/حكم-الصيام-للمتعاقد-في-بلد-اجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1290.mp3","categories":["الأعذار المبيحة للفطر","من يجب عليه الصوم"]},{"id":7074,"question":"شخص كان صائمًا في رمضان المبارك، وأراد السفر، ولكنه أفطر في منزله قبل أن يغادر المدينة التي يقيم فيها، فما الحكم في ذلك؟","title":"حكم إفطار المسافر قبل مغادرة المدينة التي يقيم فيها","answer":"الجواب:\n\nما ينبغي له، ينبغي له ألا يفطر إلا بعد الخروج، عليه قضاء اليوم، ولكن لا ينبغي له في المستقبل إلا إذا غادر البلد، فارق عمارتها، هذا هو الذي ينبغي.","link":"https://binbaz.org.sa/fatwas/3081/حكم-افطار-المسافر-قبل-مغادرة-المدينة-التي-يقيم-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1464.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":7084,"question":"أنا رجل مصاب بمرض أعصاب، وقد راجعت مستشفى الأمراض النفسية، وصرف لي علاجًا مستمرًا طول اليوم ثلاث مرات، وإذا تركته؛ اشتد المرض بي حتى أسقط على الأرض بدون شعور، وأريد أن أصوم، ولكني خائف إذا انقطع عني هذا العلاج الذي أتناوله في اليوم يعود لي هذا المرض؟","title":"حكم الصوم لمريض يتضرر بانقطاع الدواء عنه","answer":"الجواب:\n\nلا تصم بارك الله فيك، الله يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] ما دام الحال على ما ذكرت؛ فتناول الحبوب كل يوم، ولا تصم، واسأل الأطباء الذين أعطوك، فإن كان هذا المرض في اعتقادهم، وتجاربهم يستمر؛ فأطعم عن كل يوم مسكينًا، ويكفي مثل الشيخ الكبير، والعجوز الكبيرة، أطعم عن كل يوم مسكينًا، نصف صاع تمر، أو رز تدفعه للفقراء، فقيرًا واحدًا، أو أكثر في أول الشهر، أو في وسطه، أو في آخره، تجمعه وتعطيه بعض الفقراء، ويكفي، أما إن قال الأطباء: إن هذا يرجى زواله -إن شاء الله- بعد سنتين، أو ثلاث؛ فإنك تؤجل، فإذا عافاك الله؛ تقضي. \n\nالسؤال: فإذا قالوا: إنه لا يرجى برؤه، ثم عافاه الله؟\n\nالجواب:  على هذا يصوم من جديد. \n\nالسؤال: وإذا أطعم عن كل يوم مسكينًا؟\n\nالجواب: الذي مضى مضى، ما عليه شيء، يصوم من جديد مستقبلًا.\n\nالسؤال: رمضانات كلها؟\n\nالجواب: المستقبل.","link":"https://binbaz.org.sa/fatwas/3080/حكم-الصوم-لمريض-يتضرر-بانقطاع-الدواء-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1463.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":7107,"question":"بعض السواقين (السائقين) دائمًا مسافرون، هل يجوز لهم قصر الصلاة، والإفطار في رمضان؟","title":"حكم القصر والفطر للسائق المسافر","answer":"الجواب:\n\nالمسافر له قصر الصلاة، ولو كان دائمًا يسافر، له القصر، وله الفطر في رمضان، لكن ما دام مستمرًا في السفر، إذا صام مع الناس يكون أنشط له وأسلم؛ حتى لا يثقل عليه الصوم بعد ذلك، وإذا وصل إلى بلده؛ وجب عليه الإتمام، يصلي أربعًا، ووجب عليه الصوم إذا كان في رمضان.\n\nوهكذا إذا قام أربعة أيام أو أكثر، إذا نوى أكثر من أربعة أيام في بلد يقيمها؛ وجب عليه أن يتم أربعًا، وأن يصوم إن كان في رمضان، وإلا فالصوم رخصة، إذا أفطر في السفر مثل غيره من الناس، أو صلى ركعتين، ولو كان صاحب سيارة دائمًا مسافر، ما دام في السفر له الفطر، وله القصر، ولكن متى وصل إلى بلاده؛ أتم وصام في رمضان، وهكذا إذا نوى في أي بلد إقامة طويلة، أكثر من أربعة أيام؛ أتم وصام.","link":"https://binbaz.org.sa/fatwas/3136/حكم-القصر-والفطر-للساىق-المسافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1494.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":7496,"question":"هذه الرسالة وردت من شخص رمز لاسمه بـ (ك. ع. ك. ع) يقول في رسالته: هناك شخص معين أصيب بمرض قبل رمضان العام الماضي ولازمه المرض إلى الآن، ولا يستطيع الصيام لهذا العام لو جلس على هذا الوضع، فما الحكم لو أتى رمضان العام القادم وهو لم يصم رمضان السابق، ولم يستطع صيام رمضان الحالي؟ أفيدونا وفقكم الله.","title":"حكم المريض الذي لا يرجى برؤه ولا يستطيع الصوم","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nهذا الذي لزمه المرض ولم يستطع صوم رمضان الماضي ولا هذا الحالي، ويخشى أن يأتيه رمضان القادم وهو كذلك، لا صوم عليه والحمد لله. الله جل وعلا يقول: فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:184] هذا لطفه ، ورحمته جل وعلا. فإذا عافاه الله وشفاه قضى ما عليه من الأيام الماضية واللاحقة، ولا حرج عليه في ذلك والحمد لله.\nأما إن قرر الأطباء أن هذا المرض يستمر ولا يزول، فإنه يكون كالشيخ الكبير والعجوزة الكبيرة اللذين يشق عليهما الصيام، فإنه يطعم عن كل يوم مسكيناً ولا يلزمه صوم، إذا تقرر من جهة الأطباء أن هذا المرض ملازم، وأن مثله لا يشفى منه بل يلازمه، فإنه حينئذ يفطر ولا قضاء عليه، ويطعم عن كل يوم مسكيناً، نصف صاع من قوت البلد؛ من تمر أو رز أو نحو ذلك، هذا الواجب عليه، مثل الشيخ الكبير العاجز والشيخة الكبيرة العاجزة، الحكم فيهم سواء. نعم.","link":"https://binbaz.org.sa/fatwas/4457/حكم-المريض-الذي-لا-يرجى-بروه-ولا-يستطيع-الصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_007/00701.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":7500,"question":"هذه الرسالة من علي محمد عالي الغامدي ، بلاد غامد، قرية آل عاطف، يسأل عن الإفطار في شهر رمضان بالمرض يقول: أود أستفسر عن موضوع: هو أنني أعمل في منطقة حارة وأنا إنسان مريض، وسبق أن تنومت في مستشفى السداد، وفي رمضان هذا العام أفطرت الأيام كلها لعدم استطاعتي الصيام، فأرجو من فضيلتكم إفادتي، هل أقضي أم أطعم، أم ماذا يترتب علي؟ والله يحفظكم ويرعاكم.","title":"حكم المريض إذا أفطر في رمضان","answer":"الجواب: الواجب على المريض إذا أفطر أنه يقضي بعدما يشفيه الله يقضي ما عليه من الأيام، سواء كانت متتابعة أو مفرقة، لا حرج في ذلك، لقول الله سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] يعني: فأفطر، فعليه عدة من أيام أخر، ولم يقل سبحانه: متتابعة، فدل ذلك على أنه مخير، إن شاء تابعها وهو أفضل، وإن شاء فرقها ولا حرج، هذا كله إذا كان يستطيع، أما ما دام لا يستطيع فإنها تؤجل عليه حتى يستطيع وحتى يشفى من مرضه، فإذا شفاه الله وعافاه قضاها متتابعة أو مفرقة، فإن كان مرضه مرضاً لا يشفى مثله بل ويلازم ويبقى، فهذا لا يلزمه القضاء حينئذ لعجزه عنه ولكن يلزمه الإطعام، يطعم مسكيناً عن كل يوم، نصف صاع من التمر أو من الرز، من قوت بلده، يكفي هذا إذا كان مرضه يعني لا يشفى مثله، فهذا حكمه حكم الشيخ الكبير والعجوزة الكبيرة لا قضاء عليهما، ولكن يطعم كل منهم عن كل يوم مسكيناً، نصف صاع من التمر، أو من الرز ونحو ذلك، يعني: نصف صاع من قوت البلد عن كل يوم ولا قضاء.","link":"https://binbaz.org.sa/fatwas/4461/حكم-المريض-اذا-افطر-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_007/00705.mp3","categories":["الأعذار المبيحة للفطر"]},{"id":7501,"question":"هذه الرسالة من مستمع رمز لاسمه بـ (م. ع. ك) وهي في الحقيقة مجموعة أسئلة، ولعلنا نأخذ منها سؤال في هذه الحلقة أو سؤالين، يقول: أنا موظف حكومي وعملي بعيد عن أهلي، علماً بأني أقوم بزيارة أهلي بعد كل أسبوعين وذلك بعد انتهاء دوام يوم الأربعاء، وأن هذه المسافة تستغرق أربع ساعات ونصف تقريباً، وأرجع إلى مقر عملي يوم الجمعة، المطلوب: هل يصح لي قصر الصلاة وجمعها مثل الظهر والعصر، والمغرب والعشاء، أم القصر فقط، أو الجمع بدون قصر، أو أصلي كل صلاة على وقتها ولا تشملني رخصة المسافر؛ وذلك لكثرة تكراري السفر لقصد عملي الأصلي ومكان أهلي، علماً بأنني أمتلك سيارة في حالة ذهابي وإيابي وتحت تصرفي الخاص؟ أفيدوني وفقكم الله.","title":"حكم القصر والإفطار في السفر المتكرر","answer":"الجواب: المسافر إذا سافر لأهله أو لحاجة يقصر ويجمع لا حرج عليه، ولو تكرر هذا منه، ولو أنه يذهب كل أسبوع أو كل أسبوعين إلى أهله في محل بعيد، إذا كان أهله في محل يعد سفراً، فلا بأس أن يقصر، يصلي ركعتين الظهر والعصر والعشاء، ولا بأس أن يفطر في رمضان في الطريق إذا كان السفر طويلاً، لا بأس عليه في ذلك ولا حرج، فله الجمع، وله القصر، وله الإفطار في السفر، إذا كانت المسافة تعد سفراً، كالذي مثلاً يعمل في الرياض ويسافر إلى القصيم، أو يسافر إلى حائل أو يسافر إلى الوشم إلى شقراء إلى كذا، هذا كله سفر، ما دام في السفر فله الإفطار، إلا إذا تعمد السفر من أجل الفطر، إذا كان قصده لأجل الفطر فلا يجوز هذا؛ لأن هذا تحيل، أما إذا كان يسافر لحاجته لأجل زيارة أهله وقضاء حاجاته فلا حرج في ذلك، وله أن يصلي الظهر ركعتين إذا كان في سفره والعشاء ركعتين في سفره والعصر ركعتين في سفره، وله أن يجمع بين الظهر والعصر، وبين المغرب والعشاء، لا بأس بذلك، لكن إذا كان سافر مثلاً أول النهار مفطر، ثم وصل إلى أهله في النهار يمسك؛ لأنه وصل إلى وطنه، يمسك ويقضي اليوم هذا الذي أفطر فيه، وإن صام في الطريق حتى لا يقضي ولم يفطر، فلا حرج، الصوم جائز والفطر جائز، والحمد لله.\nمقصوده: كل ما يسمى سفراً فله فيه القصر وله فيه الفطر، لكن إذا كان يصل في أثناء النهار إلى بلده، فإن صام حتى لا يتكلف القضاء فلعله أحسن له وأولى له .. حذراً من التكلف، تكلف القضاء، وإن أفطر ثم أمسك في بلاده إذا وصل، هذا هو الواجب عليه ويقضي ذلك اليوم الذي أفطر فيه، وهكذا الصلوات؛ يقصر الظهر والعصر والعشاء ثنتين، وله الجمع بين الظهر والعصر، وبين المغرب والعشاء في ذلك، كل ما يعد سفراً كثمانين كيلو سبعين كيلو وما يقاربها كل هذا يسمى سفر. نعم.","link":"https://binbaz.org.sa/fatwas/4462/حكم-القصر-والافطار-في-السفر-المتكرر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_007/00706.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":7522,"question":"سؤاله الثاني سؤال عادل ناصر الفصام يقول: أنا عندي مرض نفسي حيث عرضت نفسي على الطبيب فأعطاني جرعات على شكل حبوب، وذلك لمدة خمس سنوات، كل اثنا عشر ساعة حبة واحدة، فماذا أفعل وخاصة في شهر رمضان رغم أن طول الصيام في اليوم يصل إلى خمسة عشر ساعة، ولو تأخرت عن هذا الموعد أقل من ساعة فقد يعاودني هذا المرض؛ الصرعة، أفيدوني أفادكم الله؟","title":"حكم الإفطار في رمضان لأجل تناول الدواء","answer":"الجواب: الله يقول جل وعلا: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] فإذا كان المرض يحصل بتأخير الجرعة عن موعدها فلا بأس بالإفطار، إذا كان اليوم طويل مثل خمسة عشر ساعة من هذه الأيام، لا بأس أنه يأكل الجرعة الحبة التي عينت له ويفطر بذلك، ويقضي هذا اليوم، يأكلها ويمسك ويقضي؛ لأن الإفطار من أجلها، فيمسك ويقضي بعد ذلك، أما إذا تمكن أن يؤجل ولا يشق عليه ذلك، فإنه يلزمه التأجيل حتى يأكلها بالليل.\nالمقدم: هو في الحقيقة يقول: ما أستطيع أؤجل ...\nالشيخ: مثلما قال، قلنا: إذا كان لا يستطيع يأكلها والحمد لله، ويقضي اليوم في الأيام القصيرة، في الأيام الباردة.\nالمقدم: في الأيام الباردة؟\nالشيخ: الذي لا يزيد النهار فيها على اثنى عشر. نعم.","link":"https://binbaz.org.sa/fatwas/4496/حكم-الافطار-في-رمضان-لاجل-تناول-الدواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_009/00907.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":7642,"question":"هذه رسالة وردتنا يا سماحة الشيخ عبد العزيز من الحدود الشمالية يقول مرسلها ضبيان خضر الجرير الشمري: سافرت في رمضان وأفطرت يوماً، فما هي كفارته؟","title":"ما كفارة الإفطار في رمضان للسفر؟","answer":"الجواب: إذا كنت أفطرت في السفر فعليك القضاء فقط ولا فيه كفارة، إذا كنت أفطرت في السفر من أجل السفر فلا حرج بل سنة، يقول الله عز وجل: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فالله وسع ويسر سبحانه وتعالى، ورخص للمسافر والمريض أن يفطرا، فإذا سافرت إلى أي جهة من الجهات فأفطرت يوماً أو أكثر؛ فعليك القضاء ولا كفارة عليك، إلا إذا تأخر القضاء إلى رمضان آخر فلم تقض فعليك القضاء بعد رمضان مع إطعام مسكين عن كل يوم، نص صاع من التمر أو الرز أو غيرهما من قوت البلد عن التأخير، أفتى به جماعة من الصحابة رضي الله وأرضاهم وهو أصح قولي العلماء، يعني: تقضي يومك الذي أفطرته، وتفدي فدية تكفر بإطعام مسكين إذا كان القضاء تأخر إلى ما بعد رمضان آخر، والله سبحانه وتعالى أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/4776/ما-كفارة-الافطار-في-رمضان-للسفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_035/03503.mp3","categories":["قضاء الصيام","الأعذار المبيحة للفطر"]},{"id":7645,"question":"أيضاً هذا محمد ناصف معطي أو مطري يقول: لقد تركت بعض الأيام من شهر رمضان في العام الماضي، وأنا محرج حيث سيداهمني أو يداهمني رمضان هذا العام، هل أترك الصيام لما بعد رمضان وأصوم، أم أصوم الذي عن رمضان الماضي، ثم أبدأ مع المسلمين في صيام هذا الشهر؟","title":"حكم تأخير قضاء أيام من رمضان حتى رمضان التالي","answer":"الشيخ: تعيد السؤال.\nالمقدم: يقول: إنه قد فاتني بعض الأيام من شهر رمضان في العام الماضي، وأخشى أن يداهمني، أو يقول: داهمني رمضان هذا العام، وأنا لم أصم ما بقي علي من رمضان العام الماضي، فهل أصوم الذي من العام الماضي، أو أتركه وأؤجله وأصوم مع المسلمين رمضان هذا العام الذي علينا؟\nالشيخ: يلزم السائل وفقه الله أن يبادر بالصوم في هذه المدة الباقية، وأن يقضي ما عليه من الصوم، هذا الواجب عليه قبل رمضان، ولا يجوز له التأخير والتساهل، لكن لو غلبه أمر كمرض منعه من الصوم فإنه يصوم بعد رمضان، وعليه إطعام مسكين عن كل يوم؛ بسبب التساهل الذي ألجأه إلى التأخير، أما الآن فيلزمه الصوم، يلزمه أن يبادر ويصوم ما عليه ويقضي قبل رمضان، هذا هو الواجب عليه، إلا إذا منعه مانع من المرض، كالمرض ما استطاع فلا بأس أن يؤجل، إذا عجز بسبب المرض حتى جاء رمضان فإنه يؤجله ويصومه بعد رمضان إن شاء الله، وعليه إطعام مسكين عن كل يوم؛ لأنه تساهل في التأخير قبل المرض، أما لو أخره بسبب المرض في جميع السنة، يعني: من حين أفطر وهو في مرض إلى الآن في مرض حتى جاء رمضان فلا شيء عليه إلا القضاء، يقضي بعد ذلك إذا عافاه الله يقضي بعد رمضان ولا شيء عليه، أما الذي أخر الصيام تساهلاً وعدم عناية فإن هذا عليه التوبة والاستغفار، وعليه أن يقضي ويطعم إذا أخره إلى ما بعد رمضان، أما إذا صام في رجب أو في شعبان لا بأس، ما عليه شيء، يصوم ولا حرج عليه. نعم.","link":"https://binbaz.org.sa/fatwas/4785/حكم-تاخير-قضاء-ايام-من-رمضان-حتى-رمضان-التالي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_035/03506.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":7724,"question":"أيضاً يقول: هل صحيح أن الرسول ﷺ صلى الجمعة أربعاً في عرفة؟","title":"عدم ثبوت أن النبي صلى الجمعة أربعاً في عرفة","answer":"الجواب: هذا غلط .. ليس بصحيح، النبي ﷺ صلى الظهر في عرفات ركعتين ما صلى جمعة، كان في السفر لا يصلي جمعة عليه الصلاة والسلام، وكان في حجة الوداع صادف يوم عرفة يوم الجمعة فصلى النبي ﷺ ركعتين سماها الراوي ظهراً، ثم صلى بعدها العصر ركعتين جمعاً وقصراً جمع تقديم في يوم عرفة يوم الجمعة، ولم يجهر بالقراءة بل أسرها، ولو كانت جمعة لجهر بالقراءة، ثم خطب الناس عليه الصلاة والسلام خطبة واحدة، وكان في الجمعة يخطب خطبتين، وهنا خطب الناس قبل الأذان وكان في الجمعة يؤذن ثم يخطب. \nفهو صلى ظهراً لا جمعة من وجوه كثيرة: من جهة أنه صلاها ركعتين وسماها الراوي ظهراً، وصلى معها العصر قصراً وجمعاً، ومنها أنه خطب خطبة واحدة قبل الأذان والجمعة خطبتان، ومنها أنه خطب قبل الأذان والقاعدة في الجمعة أنه يخطب بعد الأذان، ومنها أنه لم يجهر بالقراءة والجمعة يجهر فيها بالقراءة؛ فعلم بذلك أن المسافر لا يصلي جمعة وإنما يصلي ظهراً ركعتين، وهذا الذي فعله النبي ﷺ في عرفات وفعله معه المسلمون. نعم.\nالمقدم: طيب بالنسبة للذين يخرجون للبرية دائماً في رحلات نهاية الأسبوع؟\nالشيخ: يصلون ظهراً لا يصلون جمعة نعم؛ لأنه في حكم السفر.\nالمقدم: لكن بعضهم يقول: إنني تخلفت عن الجمعة أكثر من ثلاث جمع، فأنا سوف أذهب إلى القرية الفلانية وآتي بالجمعة؟\nالشيخ: لا، إذا صلى في بعض القرى التي في الطريق أو حولهم طيب، يعني: إذا كان حولهم قرية يجب عليهم أن يصلوا فيها، إذا كانت قريبة منهم فالأولى بكل حال أن يصلوا فيها، الوجوب فيه نظر، لكن الأولى بكل حال أن يصلوا في القرية التي بقربهم. نعم.\nالمقدم: طيب هل يجوز للمسافر أن يؤخر الجمعة إلى صلاة العصر؛ ويصليها ظهراً قصراً وجمعاً مع العصر، أو العكس؟\nالشيخ: المسافر في سفره؟\nالمقدم: نعم.\nالشيخ: ما عليه جمعة، فإذا أخر صلاة الظهر مع العصر لا بأس؛ لأنه ليس مثل الجمعة في سفره ولو كان في يوم الجمعة، إن شاء جمع جمع تقديم وإن شاء جمع جمع تأخير؛ لكن الأفضل للمسافر إذا ارتحل من مكانه في السفر قبل الظهر أنه يؤخر الظهر مع العصر جمع تأخير، وإذا ارتحل بعد دخول الوقت الأول، يعني: بعد دخول وقت الظهر، فالأفضل أنه يقدم العصر مع الظهر فيصليهما جمع تقديم كما فعله النبي عليه الصلاة والسلام.\nأما إذا كان نازل مستريح نزل الضحى مثلاً يبقى حتى تغيب الشمس أو يبيت في محل، يعني ليس عنده العجلة، فهذا مخير: إن شاء صلى كل صلاة في وقتها، وهو أفضل إذا كان ما فيه مشقة، كل صلاة الظهر في وقتها والعصر في وقتها، هذا هو الأفضل، وإن جمع فلا بأس، إن جمع جمع تقديم أو جمع تأخير أو في وسط الوقت فلا بأس؛ لأن المجموعتين وقتهما واحد. نعم.","link":"https://binbaz.org.sa/fatwas/4923/عدم-ثبوت-ان-النبي-صلى-الجمعة-اربعا-في-عرفة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_031/03110.mp3","categories":["صلاة المسافر","الأعذار المبيحة للفطر"]},{"id":7730,"question":"أيضاً من محطة النصر طريق خيص وردت هذه الرسالة من سعيد ظافر الشهراني يقول في رسالته: إنني أشتغل في سيارة شحن بترومين، وحل علينا شهر رمضان المبارك فكنت أسافر أنا وكثير من قائدي السيارات الشحن، فكنت أصوم والسائقون الذين معي يفطرون طوال السفر، وقالوا: إن الأجر للي يفطر في السفر وليس للذي يصوم في السفر أجر، أرجو إرشادي ولكم تحياتي، وجزاكم الله ألف خير؟","title":"مشروعية الفطر للمسافر","answer":"الجواب: لا شك أن الإفطار في السفر مشروع ورخصة من الله عز وجل، وقد قال الله سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] وكان النبي عليه الصلاة والسلام في أسفاره يصوم ويفطر وهكذا أصحابه يصومون ويفطرون، فمن أفطر فلا بأس ومن صام فلا بأس، فالإفطار رخصة من الله عز وجل للمسافرين، سواء كان المسافر صاحب سيارة أو صاحب جمال أو في السفن أو في الطائرات لا فرق في ذلك، المسافر له أن يفطر في رمضان وإن صام فلا بأس، وإذا شق عليه الصوم فالأفضل الفطر، إذا كان حر وشدة فالأفضل الفطر ويتأكد الفطر أخذاً برخصة الله جل وعلا، جاء في الحديث عنه عليه الصلاة والسلام أنه قال: إن الله يحب أن تؤتى رخصه كما يكره أن تؤتى معصيته فإذا اشتد الحر فالسنة الإفطار، وقد رأى النبي ﷺ رجلاً قد ظلل عليه فسأل عن ذلك فقالوا: إنه صائم، فقال عليه الصلاة والسلام: ليس من البر الصوم في السفر يعني: في حق من اشتد به الأمر، أما من كان في حقه لا يضره ذلك ولا يشق عليه فهو مخير إن شاء صام وإن شاء أفطر. نعم.\nالمقدم: طيب بالنسبة لهؤلاء السائقين الذين يقضون حياتهم في السفر؟\nالشيخ: الصواب: أنه لا حرج ولو كان السفر مهنة له، كصاحب السيارة الدائم تكسي أو غيره، مثل صاحب الجمل الدائم في الوقت السابق له الفطر وإن كان دائم السفر؛ لكن إذا جاء إلى بلده صام وأمسك، أما في حال أسفاره وتنقلاته من بلد إلى بلد فله الإفطار ولو كانت هذه مهنته. نعم.","link":"https://binbaz.org.sa/fatwas/4929/مشروعية-الفطر-للمسافر ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_032/03205.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":7770,"question":"هذه رسالة من غزاي محمد الشلوي من الرياض يقول: متى يقصر المسلم صلاته؟ وما المدة التي يجوز فيها القصر؟","title":"مدة القصر ومسافته","answer":"الجواب: إذا سافر المؤمن سفر قصر، يعني: سفراً يعتبر سفر قصر؛ شرع له القصر؛ لأن الله جل وعلا قال: وَإِذَا ضَرَبْتُمْ فِي الأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَقْصُرُوا مِنَ الصَّلاةِ [النساء:101]، كان النبي ﷺ إذا سافر قصر، يعني صلى ثنتين الظهر والعصر والعشاء، هذه محل القصر، أما الفجر فلا قصر فيها، والمغرب لا قصر فيها، إنما القصر في الظهر والعصر والعشاء في الرباعية، فإذا سافر ما يعد سفراً من سبعين كيلو.. ثمانين كيلو.. أكثر ذلك، وهما في العهد الأول مرحلتان للإبل، يعني: يومين قاصدين، فلما ذهبت الإبل صارت السيارات الآن سبعين كيلو.. ثمانين كيلو أو ما يقاربها مرحلة تعد سفراً، هذا هو الأحوط للمؤمن، إذا كان في هذه المسافة قصر، وإذا كان في أقل منها كالخمسين والأربعين فالأحوط ألا يقصر؛ لأنها تشبه الضواحي للبلد، وتقرب من البلد بالنسبة إلى سرعة السيارات، وقد ذهب بعض أهل العلم إلى أن السفر كل ما يعد سفراً، فإذا احتاج إلى زاد ومزاد، هذا يعد سفر وإن لم يبلغ سبعين كيلو ولم يبلغ يوم وليلة، إذا كان يحتاج إلى زاد وإلى مزاد -إلى ماء يعني- ما يعد سفراً، ما يعد سفراً هو الذي يقصر فيه، وهو الذي يحتاج إلى الزاد يعني الطعام، والمزاد يعني: الماء- كخمسين كيلو وأربعين كيلو ونحو ذلك، في المطية والمشي على الأقدام.\nأما السيارة فإن حالها غير حال الأقدام، وغير حال المطية كما هو معلوم بسبب السرعة، فلهذا، إذا احتيط في هذا وصار السفر ما يعد سبعين كيلو تقريباً أو ثمانين كيلو يكون هذا أقرب وأحوط، وهو موافق لما قرره العلماء سابقاً من اليومين القاصدين، فإذا ذهب إلى نحو هذه المسافة قصر، صلى الظهر ركعتين والعصر ركعتين والعشاء ركعتين، وإن كانت أقل من ذلك فإنها تشبه ضواحي البلاد، فالأحوط له أن يتم أربعاً. نعم.\nالمقدم: أيضاً يقول: ما المدة التي يجوز فيها القصر؟ وأعتقد أنه يقصد المدة التي يقيم فيها الإنسان في سفره؟\nالشيخ: نعم. المدة التي يقيم فيها الإنسان في سفره، تنقسم قسمين:\nقسم مدة يحددها، ومدة لا يحددها، فأما المدة التي لا يحددها بأن يكون له حاجة في البلد، لا يدري متى تنقضي مثل طلبه لإنسان، يلتمس إنسان لعله يجده، مثل حق له على إنسان يطلبه منه، مثل خصومة يريد إنجازها وما أشبه ذلك، ليس لها مدة معلومة، بل مهمته أن ينهي هذه الحاجة، ولو في يوم واحد أو يومين، هذا يقصر مدة إقامته؛ لأنه ليس له أمد محدود، فهذا لا يزال يقصر حتى ينتهي، أما الحال الثاني فهي حالة الإنسان الذي قد عزم على أيام معلومة قد حددها، كونه يقيم عشرة أيام، عشرين يوم، أربعة أيام خمسة أيام، فهذه اختلف فيها أهل العلم:\nمنهم من قال: تحدد بثلاثة أيام، ومنهم من حددها بأربعة أيام، ومنهم من حددها بخمسة عشر يوماً، وقيل: بعشرين يوماً، والأحوط في هذا أربعة أيام، إذا نوى أكثر من أربعة أيام أتم، والحجة في هذا إقامة النبي ﷺ في حجة الوداع، فإنه أقام أربعة أيام؛ لأنه صبح مكة اليوم الرابع صباحاً، وأقام اليوم الرابع والخامس والسادس والسابع، ثم توجه إلى منى وعرفات في اليوم الثامن، قال العلماء: هذه أربعة أيام قد عزم على إقامتها، فيقصر فيها الصلاة كما قصر النبي ﷺ، فإذا نوى أكثر من ذلك أتم؛ لأن الأصل هو الإتمام، الأصل أن الواجب إتمام الصلاة، شرع القصر في السفر، فهذه إقامة ليست سفراً، إقامة فيتم فيها، بخلاف الأربعة أيام فأقل فإنها في حكم السفر، كما فعله النبي ﷺ في حجة الوداع، ولعل هذا أحوط إن شاء الله وأقرب. نعم.","link":"https://binbaz.org.sa/fatwas/4982/مدة-القصر-ومسافته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_046/04605.mp3","categories":["صلاة المسافر","الأعذار المبيحة للفطر"]},{"id":7789,"question":"سؤال علي ناصر يماني الثاني يقول: إذا كنت أعمل في سيارة كبيرة ودائماً طول السنة في السفر، وأقل مسافة ما بين مكة وجدة حوالي خمسة وسبعين كليو متر، هل يجوز لي الصوم وعدم تقصير الصلاة وأداء السنن الراتبة، وما هي أقل مسافة بالكيلو مترات التي تقصر فيها الصلاة ويفطر فيها الصائم، وإذا أتى على مسجد فهل يصلي معهم؟","title":"بعض الأحكام المتعلقة بالسفر من المسافة والقصر والصيام","answer":"الجواب: السنة في السفر القصر والفطر، ومن أتم في السفر أو صام في السفر لا حرج عليه، إذا أتم لا حرج عليه، وإذا صام في السفر لا حرج عليه، ولكن الأفضل أنه في السفر يفطر ويقصر.. يصلي الرباعية ركعتين، هذا هو السنة التي كان النبي يفعلها عليه الصلاة والسلام وأصحابه، وكان يصوم في السفر وربما أفطر عليه الصلاة والسلام في السفر، وهكذا كان أصحابه يسافرون فمنهم الصائم ومنهم المفطر، وقد دلت السنة على أن الإفطار أفضل ولاسيما مع شدة الحر، فالفطر أفضل، والقصر أفضل بكل حال، إذا سافر يقصر ركعتين، والسفر الذي تقصر فيه الصلاة هو ما يعد سفر عرفاً، ما يعده الناس سفر عرفاً هذا هو السفر، وهو الذي يحتاج إلى الزاد والمزاد، يحتاج إلى الماء ويحتاج إلى الطعام، إذا سافر الإنسان في الطريق الذي ما فيه قهاوي ولا فيه شيء يحتاج فيه إلى الزاد والمزاد، هذا هو السفر، وحده الأكثرون بمسافة يومين قاصدين نحو سبعين كيلو.. ثمانين كيلو، هذا سفر، إذا كانت مسافة سبعين كيلو.. ثمانين كيلو وما يقارب ذلك هذا يعد سفراً، ويحتاج إلى الزاد والمزاد، إذا كان في جهة ليس فيها قهاوي في الطريق، فإن العاقل لا يسافر إليه إلا باحتياط معه ماء.. معه طعام؛ لئلا يتعطل في الطريق، أما الطرق التي فيها القهاوي وفيها المطاعم فالناس لا يحتاجون فيها إلى الزاد والمزاد لوجود ما يكفيهم في الطرقات، فلا تعتبر هذه، والحاصل أن ما كان مسافته من الطريق الذي مسافته ثمانين كيلو.. سبعين كيلو مثلما بين الطائف ومكة وجدة ومكة كل هذا يعتبر سفر، وهكذا ما أشبه ذلك يعتبر سفراً، لكن لا ينبغي للمؤمن أن يصلي وحده بل يصلي مع الناس إذا كان ..... مسجد يصلي معهم، إذا كان جماعة موجودون يصلي معهم أربعاً إذا كانوا مقيمين، لا يصلي وحده ثنتين؛ لأن الجماعة واجبة، فالمسافر إذا صادف جماعة مقيمين صلى معهم أربعاً ولا يصلي وحده، فإن لم يجد صلى وحده ثنتين.. صلى ثنتين؛ لأنها السنة، أو كان معه جماعة مسافرون يصلي وإياهم جميعاً ثنتين، ثنتين ثنتين في الظهر والعصر والعشاء، أما المغرب فتصلى ثلاثاً دائماً لا تقصر، والفجر على حالها ثنتان لا تقصر، إنما القصر في الظهر والعصر والعشاء، هذه الفرائض الثلاث هي محل القصر، والله سبحانه وتعالى أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/5136/بعض-الاحكام-المتعلقة-بالسفر-من-المسافة-والقصر-والصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_049/04902.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":7812,"question":"تقول السائلة: امرأة لم تصم شهر رمضان لأنها جاهلة، والآن قضت ما فاتها، ولكن تسأل: هل يلزمها إطعام وكفارة؟","title":"حكم من لم يصم رمضان جهلاً لفريضته","answer":"الجواب: نعم، عليها أن تطعم عن كل يوم مسكين إذا كانت قضاؤها تأخر بعد رمضان، عليها نص صاع كيلو ونصف عن كل يوم للفقراء؛ لأنها تأخرت في القضاء بغير عذر شرعي، إذا كان قضاؤها بعد رمضان آخر. نعم.","link":"https://binbaz.org.sa/fatwas/5209/حكم-من-لم-يصم-رمضان-جهلا-لفريضته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05127.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":7895,"question":"أولاً نبدأ برسالة: سعود عبد الرحمن الفرج ، وقد عرضنا بعضاً منها في اللقاء الماضي.يقول في رسالته سعود: عمري واحد وعشرون سنة لم أصم ولا شهر من رمضان، ولكن نويت -أعتقد أنه يقول أتوب- ونبت إلى الصواب والحق، وأريد أن أبتدئ من جديد، هل يجوز ذلك أم لا؟ -يعني: أعتقد أنه يقول: هل ما أصوم السنوات الماضية-.","title":"حكم من ترك صيام عدة رمضانات ثم تاب","answer":"الجواب: عليك أن تصوم رمضان والتوبة إلى الله عز وجل، وعليك أن تصوم ما مضى من الشهور عند جمهور أهل العلم، هذا هو الصواب عليك أن تصوم ذلك ولو مفرقاً غير متتابع تصوم السنة الأولى بعد بلوغك، السنوات التي بعد البلوغ بإكمال خمسة عشر سنة، أو بإنزال المني عن شهوة، أو بإنبات الشعر الخشن حول الفرج، هذه الأشياء التي يبلغ بها الرجل، فعليك أن تقضي رمضان الذي بعد هذا، رمضانات تصومها مع التوبة إلى الله والإنابة إليه سبحانه وتعالى، وإذا أطعمت مع هذا عن كل يوم مسكيناً كان ذلك أكمل؛ لأن بعض الصحابة أفتى بهذا ، فتطعم مسكيناً عن كل يوم مع القضاء. هذا إذا كنت تصلي، أما إذا كنت لا تصلي مع ترك الصوم فترك الصلاة كفر وضلال، فيكفي التوبة وليس عليك صوم ولا صلاة، إذا كنت لا تصلي فعليك التوبة إلى الله عز وجل، والرجوع إليه والإنابة والصدق وليس عليك قضاء بعد ذلك لا صلاة ولا صيام؛ لأن ترك الصلاة كفر، كفر أكبر على الصحيح، والكافر تكفيه التوبة، إذا تاب إلى الله وأناب كفى ذلك، وليس عليه قضاء ما ترك في حال الكفر، كما قال الله سبحانه: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]، وقال النبي ﷺ: التوبة تجب ما كان قبلها، والإسلام يهدم ما كان قبله. نعم.\nالسؤال: سؤاله هذا موجه لنا شخصياً يقول الأخ، هل سليمان الشبانة يستطيع الإجابة على الأسئلة؟\nالجواب نقول: يا أخ سعود عبد الرحمن لا، يوجد من يستطيع الإجابة على الأسئلة، وفقنا وإياك لما يحبه ويرضاه.","link":"https://binbaz.org.sa/fatwas/5367/حكم-من-ترك-صيام-عدة-رمضانات-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_060/06001.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":7910,"question":"هذه رسالة وردتنا من المرسلة أم محمد من جدة، تقول: السلام عليكم ورحمة الله وبركاته.لقد مرضت أمي قبل شهر رمضان بعدة أشهر، ولقد استمر مرضها إلى أن اختارها الله سبحانه وتعالى إلى جواره، ولقد صامت شهر رمضان إلا تسعة أيام، مع أنها مريضة، ولكنها أفطرت هذه الأيام من أجل العلاج، ولكنها قالت لي: إنها تود أن تقضي هذه الأيام التسعة بعد أن ينتهي شهر رمضان، ولكنها توفيت، فهل يجوز علي أن أقضي هذه الأيام التسعة، أم ماذا، أرشدوني جزاكم الله عني كل خير؟","title":"حكم من أفطرت في مرضها ثم ماتت","answer":"الجواب: مادامت ماتت في مرضها فلا قضاء عليها ولا إطعام، هذا هو الصواب، مادامت والدتها ماتت في مرضها فليس عليها قضاء ولا إطعام بل معفو عنها. نعم.","link":"https://binbaz.org.sa/fatwas/5393/حكم-من-افطرت-في-مرضها-ثم-ماتت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06202.mp3","categories":["قضاء الصيام","الأعذار المبيحة للفطر"]},{"id":8145,"question":"هذه رسالة وردتنا من المستمع محمد بن عبد الله الرياض يقول: إذا اعتمرت العائلة في شهر رمضان، هل يجوز لهم أن يفطروا خلال مكثهم في مكة المكرمة، أو أنهم يمسكون عن الأكل بمجرد وصولهم إلى مكة؟","title":"حكم الفطر في رمضان بمكة للمعتمر","answer":"الجواب: المعتمر في رمضان هو مسافر، مثلاً جاء من بلاد بعيدة يأتي من نجد أو من غيره هو مسافر، فله أن يفطر في الطريق، إذا سافر من الرياض من القصيم من حائل من المدينة من غير ذلك سفر، فله أن يفطر في الطريق وفي مكة، إلا إذا كان قد عزم على الإقامة أكثر من أربعة أيام، فإنه إذا وصل مكة فالأحوط له أن يصوم، والأولى أن يصوم؛ لأن جمهور أهل العلم يرون أنه إذا عزم عزماً جازماً على أكثر من أربعة أيام، فإنه يتم الصلاة ولا يفطر، أما إذا كان عزمه يومين ثلاث أربع ما يزيد عليها، فله أن يفطر وله أن يصوم، وله أن يقصر يصلي ثنتين وله أن يصلي مع الناس أربعاً، وليس له أن ينفرد بنفسه يصلي ثنتين إذا كان فرداً، لا بد أن يصلي مع الجماعة، أما إذا كان معه ناس، فهو مخير إن شاء صلى ثنتين هو وإياه، وإن شاءوا صلوا أربعاً مع الناس في الجماعة، فإن كانت الإقامة أكثر من أربعة أيام، فينبغي لهم الصوم وإتمام الصلاة عند جمهور أهل العلم. نعم.\nالمقدم: شكراً أثابكم الله،","link":"https://binbaz.org.sa/fatwas/5948/حكم-الفطر-في-رمضان-بمكة-للمعتمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_089/08906.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":8205,"question":"سؤال يقول: هل يجوز قضاء أيام من رمضان يوماً بعد يوم؟","title":"حكم التتابع في قضاء أيام رمضان","answer":"الجواب: نعم يجوز، المتابعة أفضل إذا تيسر ذلك، فإن فرق بين أيام القضاء فلا بأس ؛ لأن الله قال جل وعلا: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، ولم يقل متتابعة ، قال: فَعِدَّةٌ ...، هذا يشمل المتتابعة والمفرقة، فالأمر في هذا واسع والحمد لله.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6021/حكم-التتابع-في-قضاء-ايام-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09507.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":8216,"question":"سؤال يقول: هل يجوز قضاء أيام من رمضان يوماً بعد يوم؟","title":"حكم التتابع في قضاء أيام رمضان","answer":"الجواب: نعم يجوز، المتابعة أفضل إذا تيسر ذلك، فإن فرق بين أيام القضاء فلا بأس ؛ لأن الله قال جل وعلا: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، ولم يقل متتابعة ، قال: فَعِدَّةٌ ...، هذا يشمل المتتابعة والمفرقة، فالأمر في هذا واسع والحمد لله.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6021/حكم-التتابع-في-قضاء-ايام-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09507.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":8462,"question":"أخونا عثمان حسن الشريف يسأل مجموعة من الأسئلة في سؤاله الأول، يقول: توفي والدي يوم ثلاثة رمضان، فهل يجب علي إكمال رمضان له، يعني: أصوم بالنيابة عنه سبعة وعشرين يوماً؟","title":"حكم القضاء عمن مات في رمضان","answer":"الجواب: ... لا ليس عليك شيء، الحمد لله، لما توفي سقط عنه الواجب، فليس عليك ولا يشرع لك أن تصوم عنه أيضاً. نعم.","link":"https://binbaz.org.sa/fatwas/6468/حكم-القضاء-عمن-مات-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_123/12309.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":8482,"question":"أختنا تقول: إنها لم تكن تقضي الأيام التي فاتتها من شهر رمضان وهي لا تستطيع إحصاءها فكيف توجهونها؟","title":"حكم من أفطر أياماً لا يعلم عددها ويريد القضاء","answer":"","link":"https://binbaz.org.sa/fatwas/6541/حكم-من-افطر-اياما-لا-يعلم-عددها-ويريد-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_125/12509.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":8637,"question":"هذه رسالة وردتنا من السائل محمد أحمد يوسف ، سوداني مقيم بالمملكة جيزان، يقول: كنت مريضاً بالكلى وقد أعفاني الدكاترة عن الصيام -هكذا- عن صيام شهر رمضان، وذلك منذ مدة، وقد حضرت إلى السعودية بقصد طلب الرزق وذلك في عام ألف وأربعمائة وواحد هجرية ولم أتصدق عن كل السنوات هذه ولم أفعل فيها شيئاً، فالرجاء توجيهي إلى الطريق الصحيح وفقكم الله؟","title":"حكم من أصيب بمرض يمنعه من الصيام","answer":"الجواب: إذا كان الأطباء ذكروا لك -أيها السائل- أن الصوم يضرك أبداً دائماً دائماً فعليك أن تطعم عن كل يوم مسكين عن السنوات الماضية والمستقبلة، إذا دخل رمضان لك الإفطار وتطعم عن كل يوم مسكين سواء جمعت ذلك في أول الشهر أو في آخر الشهر، نصف صاع من التمر أو من الرز أو من الحنطة، سواء جمعت ذلك وأعطيته بعض المساكين في أول الشهر أو في وسطه أو في آخره تجمع ذلك، ومقداره كيلو ونصف تقريباً، مقدار نصف الصاع كيلو ونصف تقريباً من طعام بلدك من رز أو من حنطة أو من غير ذلك من قوت بلدك، أما إن كانوا لا. قالوا لك: سنة، سنتين، أربع، خمس، ثم تصوم، فلا حرج عليك أن تؤجل الصيام وإذا عافاك الله وجاء وقت الإذن تصوم ما مضى وليس عليك صدقة؛ لأنك معذور، والله يقول سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185].\nأعيد الجواب: إن كان الأطباء قرروا أنك لا تصوم أبداً؛ لأن الصوم يضرك، فليس عليك صيام وعليك الإطعام عما مضى وعما يأتي، عن كل يوم نصف صاع، كيلو ونصف تقريباً من قوت بلدك من تمر أو رز أو غير ذلك.\nأما إن كان الأطباء قالوا: لا تصم هذه السنوات القريبة، سنتين.. ثلاث.. أربع ثم صم بعد ذلك، فإنك تؤجل الصيام حتى يأتي وقت الإذن، ثم تصوم وليس عليك إطعام، والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6778/حكم-من-اصيب-بمرض-يمنعه-من-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_212/21205.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":8738,"question":"أخ لنا من سوريا بعث بمجموعة من الأسئلة ولم يذكر اسمه بل وقع في نهاية الرسالة، أسئلته تدور حول ما يلي:أولاً: يقول: هل يجوز لشخص الإفطار في رمضان من أجل الدراسة لتقديم الفحص إن وجد في الصيام مشقة؟","title":"حكم إفطار رمضان من أجل الامتحانات الدراسية","answer":"الجواب: ليس للطلبة أن يفطروا في رمضان من أجل الاختبار، بل عليهم أن يجتهدوا ويستعدوا في الليل لاختبارهم ويصوموا في النهار، وهكذا العمال ليس لهم أن يفطروا، بل الواجب على العامل أن يعمل بقدر طاقته في نهار الصيام، وهكذا التلاميذ يعملون فيما يتعلق بالاختبار بقدر طاقتهم في النهار، وعليهم أن يجعلوا معظم العمل معظم العناية والمذاكرة في الليل؛ لأن ذلك أقوى لهم، وعلى المسئولين أن يخففوا عنهم في النهار وألا يضغطوا عليهم في هذا حتى لا يحرجوهم من جهة الصيام، وإذا تيسر أن يكون ذلك قبل رمضان أو بعد رمضان فهو خير وأولى، حتى لا يشقوا على التلاميذ في ذلك، ولكن ليس الاختبار وليس العمل عذرًا في الإفطار، بل الواجب أن يهيئ الإنسان نفسه مع الصوم فيعمل ما يستطيع مع الصوم ويعمل في الاختبار ما يستطيع ويكون معظم المذاكرة والعناية تكون في الليل، يكون في الليل وقت الفطر، ويكون وقت النهار لمجرد أداء الاختبار، وعلى المسئولين أن يلاحظوا هذا حتى لا يشقوا على التلاميذ، بل عليهم أن يجعلوا الاختبار بقدر الطاقة، وإذا أمكن أن يقدم على رمضان أو يؤخر فذلك أرفق بالتلاميذ وأولى. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6892/حكم-افطار-رمضان-من-اجل-الامتحانات-الدراسية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_162/16203.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":8965,"question":"أختنا تقول: كان لي أخ يشتغل سائق في أرض زراعية وحدث مرة أن اصطدم برجل كبير في السن فمات الرجل، سلم أخي نفسه للشرطة معترفاً أنه اصطدم بالرجل لكن بدون قصد، فخرج أخي بكفالة ولم يمض عام واحد حتى قتل أخي بيد طفل في العاشرة، فسامحه أبي وسامحت أمي وكلنا سامحنا الطفل وأهله، أمي صامت شهرين متتابعين حتى تكفر عن أخي بعض ذنوبه، ما حكم صيامها وهل علينا في جانب أخي من شيء أرجو التكرم بإفادتنا؟","title":"الواجب على أولياء الميت إذا مات وعليه صوم","answer":"الجواب: قد أحسنتم في التسامح والعفو، وأحسنت الوالدة في الصوم عن ابنها؛ لأن عليه الكفارة، وهي: عتق رقبة مؤمنة، فإن لم يستطع صام شهرين متتابعين، ولقد أحسنت الوالدة في صيام شهرين؛ لأن تحصيل الرقبة قد يتعسر في بعض الأحيان، وقد يعجز عنه القاتل وهو لا يوجد إلا قليل يوجد في بعض دول أفريقيا ولكنه قليل، فإذا تمكن من شراء عبد أو الأمة من عتق فهو مقدم على الصيام، وإذا لم يتمكن صام شهرين متتابعين، ولما صامت أمك عنه فقد أحسنت في ذلك، لقول النبي ﷺ: من مات وعليه صيام صام عنه وليه، يعني: قريبه، وهي أقرب الناس إليه فقد أحسنت في ذلك. نعم.\nالمقدم: كأني بالوالدة لم تصم من أجل القتل الخطأ سماحة الشيخ بل صامت للتكفير عن ذنوب أخرى؟ ترشدونها إلى شيء لو تكرمتم؟\nالشيخ: إن كانت صامت عن ابنها لأجل الصوم الذي عليه بسبب قتله الشيخ الكبير فهذا صحيح، فإن كانت صامت لغير ذلك فهذا لا يجزي، لقول النبي ﷺ: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى، فيستحب لها.. يشرع لها أن تصوم أو أبوه إن كان هو موجود أو أحد إخوانه أو إحدى خواته، هذا كله طيب، لقوله ﷺ: من مات وعليه صيام صام عنه وليه. نعم.\nالمقدم: بارك الله فيكم، لو توزعت الأسرة الصيام يجوز هذا؟\nالشيخ: هذا فيه التتابع لابد يصومه واحد. نعم.","link":"https://binbaz.org.sa/fatwas/7123/الواجب-على-اولياء-الميت-اذا-مات-وعليه-صوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_145/14507.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":9052,"question":"حياكم الله، شيخ عبد العزيز! هذه الحلقة ستكون بإذن الله عن الصيام وعن المرضى، فهل من كلمة نستهل بها هذا اللقاء لو تكرمتم؟","title":"مشروعية إفطار المسافر والمريض في شهر رمضان مع القضاء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفقد سبق في حلقة مضت ما يتعلق بشأن الصيام وفضل صيام رمضان ووجوبه على المسلمين، وما يجب أيضاً على المسلمين من العناية بحفظه وصيانته عما حرم الله  حتى يوفوا أجورهم كاملة، ومعلوم أن الإنسان يعرض له عوارض من المرض والسفر، والله  قد بين هذا في كتابه العظيم، فمن نزل به المرض وشق عليه الصوم فله أن يفطر ثم يقضي بعد ذلك، وهكذا من عن له سفر لحاجة فلا بأس أن يسافر ويفطر ويقضي، وليس لأحد أن يسافر من أجل الإفطار والتحيل على الإفطار هذا لا يجوز؛ ولهذا يقول  في كتابه العظيم لما ذكر الصيام قال: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلا يُرِيدُ بِكُمُ الْعُسْرَ[البقرة:185] الآية، فالمؤمن يحاسب نفسه وهكذا المؤمنة، فإن وجد أحدهما مرضاً يشق عليه معه الصوم والله يعلم أنه صادق فلا حرج عليه في الفطر، وهكذا إذا سافر لحاجة فإنه لا بأس عليه أن يفطر ثم يقضي بعد ذلك والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7203/مشروعية-افطار-المسافر-والمريض-في-شهر-رمضان-مع-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_149/14901.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":9055,"question":"أول أنواع المرض ذلكم المرض الذي تفشى في كثير من المسلمين ونسأل الله لهم العافية هو الفشل الكلوي، المصاب بهذا المرض يحتاج إلى الغسيل، والغسيل قد يكون في نهار رمضان، ويسأل كثير من المصابين بهذا المرض فيما لو أذن لهم الأطباء بالصيام هل يؤثر غسيل الكلى على الصيام أو لا يؤثر؟","title":"هل يؤثر غسيل الكلى على الصيام؟","answer":"الجواب: الأمراض متنوعة والمرضى أعلم بأنفسهم، فكل مرض يشق معه الصيام ويؤثر على المريض بزيادة المرض أو تأخر البرء فإنه يجوز له الإفطار، فالغسيل الذي يحصل لأصحاب الكلى إذا كان هذا الغسيل يؤثر عليه لو صام فإنه له الفطر ولا حرج عليه.\nأما نفس الغسيل كونه يعطى شيئاً دواءً يخرج منه شيئاً يضره ويبقي فيه شيء ينفعه فلا أعلم ما يمنع من ذلك إذا كان مثل الحقن، مثل الإبر التي يعطاها الإنسان لحفظ الصحة أو لإسكان المرض كالحمى، أو لإخراج دم فاسد من فمه أو دبره فهذا لا يعتبر مفطراً له في هذه الحالة؛ لأنه لم يتعمده وإنما هو من جهة العلاج الذي تحفظ به صحته، فهو يعطى هذا لحفظ الصحة وسلامته من الهلاك وما يترتب على العلاج من الإبر التي يعطاها خروج شيء ودخول شيء، فهو يدخل له شيئاً طيباً ويخرج منه ما يضره بقاؤه، هذا هو الذي يتبادر فيما نعلم من عملهم في الغسيل، وإذا كان صومه في هذه الحال يضره في تأخير المرض وطول أجله أو زيادته فإنه يفطر ويتعاطى هذا العمل وهو مفطر ولا حاجة إلى الصوم الذي يضره والله به أرحم سبحانه وتعالى وهو القائل : وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، هذا هو المتبادر في هذه المسألة، وإذا قضى بعد ذلك احتياطاً لإخراج هذا الذي يخرج منه ما نعلم بأساً في ذلك، أما الذي يظهر والله أعلم أنه في هذه الحال شبه من قال فيه النبي ﷺ: من ذرعه القيء فلا قضاء عليه؛ لأنه إن ترك العمل أضره الترك، وإذا أعطي هذه الإبر التي تحفظ بها صحته خرج منه هذا الشيء كما قد يخرج من طريق الأسفل كونه يعطى مواد تجعله يصاب بالاستسهال وخروج ما يضره من أسفل، فهكذا خروج ما يضره من فوق من طريق القذف من نزيف، قذف الدم أو نحو ذلك، أو خروجه من أسفل من أجل العلاج ما يضره إن شاء الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7209/هل-يوثر-غسيل-الكلى-على-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_149/14902.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":9057,"question":"بالنسبة للمصابين بمرض السكر ماذا يقول الشيخ عبد العزيز لمثل هؤلاء؟","title":"الواجب على المصابين بمرض السكر في شهر رمضان","answer":"الجواب: هذا مثلما تقدم إن كان المرض يضرهم ولا يستطيعون معه الصوم بل يشق عليهم الصوم بزيادة المرض عليهم والتعب عليهم تعبًا كثيرًا واضحًا أو يسبب عدم برئه فلهم الفطر، أما إن كان عاديًا المرض معهم سواء صاموا أم لم يصوموا، هو معهم لا يتغير عليهم ولا يضرهم فالواجب عليهم الصوم؛ لأنه مرض عادي لا يضرهم معه الصوم فأشبه حال الهزالى وكبير السن الذي لا يضره الصوم. نعم.\nالمقدم: بارك الله فيكم. ماذا لو احتاجوا تعاطي نوعاً من الأدوية ربما يكون الإبر أو ما أشبه؟\nالشيخ: أما الأكل فلا، حبوب أو شراب يفطر الصائم، أما الإبر في العضل أو في العروق يحصل بها تخفيف الربو أو ما أشبه ذلك فلا حرج في ذلك إن شاء الله؛ لأن هذه الإبر فيما نعتقد وفيما نفتي به بعد البحث لا تعتبر أكلًا ولا شربًا وإنما هي علاج ودواء. نعم.\nالمقدم: هل هناك فرق بين الإبر التي تؤخذ عن طريق الوريد أو الإبر التي تؤخذ عن طريق آخر؟\nالشيخ: الصواب لا فرق في ذلك، الصواب لا فرق وإن كانت إبر الوريد أبلغ لكن لا فرق في عدم الإفطار، أما الإبر التي تؤخذ للتغذية بدل الأكل والشرب يغذونه بها فهذه قامت مقام الطعام والشراب فهي إبر تغذية فتفطر، من تعاطها أفطر بها. نعم.","link":"https://binbaz.org.sa/fatwas/7215/الواجب-على-المصابين-بمرض-السكر-في-شهر-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_149/14904.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":9058,"question":"أهل الصرع ماذا يقول عنهم الشيخ عبدالعزيز المصابون بالصرع؟","title":"حكم صيام المصابين بالصرع","answer":"الجواب: إذا صاموا وأصابهم الصرع في أثناء النهار مثل النوم لا يضرهم صومهم صحيح، أما إذا غابوا عن العقل غابت عقولهم يوماً كاملاً فهم مثل بقية المجانين لا صوم لهم ولا شيء عليهم ولا قضاء عليهم، فلو جن في آخر الليل أو صرع في آخره ولم يفق إلا في الليلة الآتية فلا صوم عليه، بخلاف الإغماء فإنه مثل النوم. نعم.","link":"https://binbaz.org.sa/fatwas/7216/حكم-صيام-المصابين-بالصرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_149/14905.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":9146,"question":"السؤال الثاني في رسالتها تقول فيه: علي صيام من ست سنوات، ويقولون: بأن اليوم بيومين، فما حكم الشرع في ذلك؟ وهل هذا صحيح، أفيدونا أفادكم الله؟","title":"كيفية قضاء الصوم المتأخر من سنوات","answer":"الجواب: عليك أن تقضي الصيام الذي عليك فقط من غير زيادة، وقول بعض الناس: اليوم بيومين هذا خطأ باطل ما له أصل، وإنما تصومين الأيام فقط التي أفطرتيها، وليس عليك زيادة فقط. لكن إذا كان تأخير الصيام من دون عذر شرعي ليس هناك مرض يمنع ولا أعذار أخرى من حمل أو نفاس أو نحو ذلك فإن عليك مع الصوم إطعام مسكين عن كل يوم إذا تيسر لك ذلك، إذا كنت مليئة تطعمي عن كل يوم مسكيناً، يعني: نصف صاع عن كل يوم كيلو ونص تقريباً عن كل يوم يجمع أو يعطى لبعض الفقراء عن الأيام التي عليك كلها، كل يوم عنه نصف صاع من قوت البلد من أرز أو تمر أو حنطة أو شعير أو ذرة من قوت البلد ونحو ذلك، تدفعينه لبعض الفقراء، تنظرين بعض البيوت الفقيرة ويدفع إليهم هذا الطعام عن جميع الأيام التي لم تصوميها إذا كنت أخرتيها من دون عذر، أما إذا كان لك عذر كالمرض فليس عليك إطعام، تصومين فقط عدد الأيام فقط لا زيادة، وأما قول من قال: إنه يصام عن كل يوم يومين فهذا قول باطل ليس له أساس.","link":"https://binbaz.org.sa/fatwas/7308/كيفية-قضاء-الصوم-المتاخر-من-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23011.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":9148,"question":"الرسالة الأولى وصلت إلى البرنامج من السيدة رانية الجندي الأردن المفرق، تقول في رسالتها وفي بدايتها: بسم الله الرحمن الرحيم، السلام عليكم ورحمة الله وبركاته، أرجو التكرم بالإجابة عن هذا  أنا امرأة مسلمة، منذ سنتين لم أصم شهر رمضان، في السنة الأولى؛ لأنني كنت في أيام النفاس، وفي السنة الثانية كنت حامل ومريضة، ونصحني الدكتور بعدم الصيام، وأنا لم أقض هذه الأيام ولم أخرج بدلاً منها مال، هل يقبل الله توبتي؟ وما الحكم في هذه الحالة أفيدوني أفادكم الله؟","title":"حكم من مضت عليها سنتان ولم تصم بسبب النفاس والحمل","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، والصلاة والسلام على عبده ورسوله وخيرته من خلقه، وأمينه على وحيه، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: أيها الأخت في الله السائلة! لا شيء عليك والحمد لله ما دمت إنما أخرت الصيام لأجل النفاس والحمل فعليك أن تصومي ما أفطرت من السنتين والحمد لله، إن كنت تساهلت في هذا وأخرت القضاء من غير عذر بعد الطهور من النفاس، فعليك أن تطعمي عن كل يوم مسكين زيادة، هذا هو الذي أفتى به جمع من أصحاب النبي صلى الله عليه وسلم، فتصومي الأيام التي عليك وتطعمي عن كل يوم مسكيناً، أما إن كنت معذورة في المدة كلها أولاً: بالنفاس، وثانياً: بالحمل، وليس هناك مدة بينهما حصل فيها قدرة على القضاء، فإنك تقضين فقط وليس عليك إطعام، بل تصومين الأيام التي عليك والحمد لله وليس عليك إطعام، ولا حرج أن تصوميها متتابعة أو متفرقة، وأما إن كنت تساهلت ولم تصومي وأنت تستطيعين الصوم فإنك عليك التوبة إلى الله مع ذلك والاستغفار، وعليك الصيام، وعليك إطعام مسكين عن كل يوم، كيلو ونصف عن كل يوم للفقراء والمساكين، يعني من التمر أو من الأرز أو من الحنطة من قوت البلد، يعطاها المساكين ولو جمعت كلها ودفعت إلى مسكين واحد أو اثنين أو ثلاثة كفى ذلك والحمد لله.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7298/حكم-من-مضت-عليها-سنتان-ولم-تصم-بسبب-النفاس-والحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23001.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":9156,"question":"هذه رسالة وصلت إلى البرنامج من الأخ صالح سعد العوفي المدينة المنورة، حي سيد الشهداء، يقول فيها: بسم الله الرحمن الرحيم، أرجو من فضيلتكم إجابتي على هذه الأسئلة:السؤال الأول: إذا أفطرت في رمضان وأنا على سفر، ثم وصلت محل إقامتي بعد العصر، فهل يجوز لي الأكل والشرب في محل إقامتي أم لا، أفيدونا أفادكم الله؟","title":"حكم من أفطر أثناء سفره ثم وصل إلى بلده","answer":"الجواب: إذا كانت الإقامة لمدة أربعة أيام فأقل، فلك أن تأكل وتشرب؛ لأنك مسافر، أما إذا كانت المحلة التي قصدتها وتقيم فيها هي وطنك، أو تقيم فيها مدة طويلة أكثر من أربعة أيام وقد عزمت على ذلك، فإذا وصلت إليها فأمسك، أمسك حتى تغيب الشمس، وهكذا لو كنت مسافراً من بلاد بعيدة ووصلت إلى بلدك في رمضان، ضحى أو ظهر أو عصر، فالصحيح من قولي العلماء أنك تمسك؛ لأنه زال العذر في الإفطار فتمسك حتى تغيب الشمس، لأنك صرت من أهل الصيام في هذه الحال.\nأما إذا كانت البلد التي قدمت إليها لك فيها حاجة، وتقيم فيها يوماً أو يومين ثم ترتحل عنها، فأنت مسافر، وهكذا ثلاث إلى أربع، فإذا نويت الإقامة أكثر من أربع فالصواب الذي عليه جمهور أهل العلم أنك تمسك عن رخص السفر، لا تفطر ولا تقصر نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7328/حكم-من-افطر-اثناء-سفره-ثم-وصل-الى-بلده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_232/23210.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":9188,"question":"الرسالة التالية وصلت إلى البرنامج من الرياض وباعثها أحد الإخوة يقول (ص. أ. أ) سوداني، أخونا يقول: قبل ثلاث عشرة سنة كنت أعمل في مدينة غير التي أسكنها وكان العمل شاقاً للغاية، وصادفت تلك الفترة شهر رمضان الكريم ولم أستطع صيام خمسة عشر يوماً من شهر رمضان، فهل يجوز القضاء، وهل علي أشياء غير القضاء أرجو أن توجهوني، وفيما إذا تكرر الحال مرة أخرى كيف أتصرف جزاكم الله خيراً؟","title":"حكم الفطر في رمضان لعذر مشقة العمل","answer":"","link":"https://binbaz.org.sa/fatwas/7348/حكم-الفطر-في-رمضان-لعذر-مشقة-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_151/15103.mp3","categories":["قضاء الصيام","الأعذار المبيحة للفطر"]},{"id":9204,"question":"عند قضاء الأيام التي يفطرها الإنسان من شهر رمضان للأعذار المبيحة مثل: المرض، والسفر، والحيض، يقولون: يجب زيادة يوم عند قضائها ليكون شاهد، فهل هذا صحيح؟","title":"حكم زيادة صيام يوم فوق قضاء الأيام التي أفطرها","answer":"الجواب: ليس له أصل، لا، ليس عليها إلا قضاء ما تركت، إذا نامت عن شيء أو نسيت شيء من الصلوات تصلي ما فاتها فقط، وفي الحيض لا صلاة عليها، لو كانت حائض أو نفساء ليس عليها قضاء صلاة الحيض والنفاس وإنما الصوم صوم رمضان فقط، لكن لو نامت عن صلاة أو نسيتها فعليها أن تقضي فقط ما تركت؛ لقول النبي ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكر لا كفارة لها إلا ذلك.","link":"https://binbaz.org.sa/fatwas/7364/حكم-زيادة-صيام-يوم-فوق-قضاء-الايام-التي-افطرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18111.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":9287,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من العراق الموصل وباعثتها إحدى الأخوات من هناك، تقول نهلة قاسم أحمد، الرسالة مطولة في الواقع سماحة الشيخ، ملخصها أن والدتها مصابة بقرحة المعدة ونصحها الطبيب بعدم الصيام إلا بعد سنتين أو ثلاث سنوات، ثم بعد ذلك تبدأ تصوم من كل أسبوع يومين فقط وهكذا حتى تتحسن حالتها، وتسأل عن الحكم سماحة الشيخ؟","title":"حكم إفطار رمضان لمن أصيب بالقرحة","answer":"الجواب: المريض شرع الله له الإفطار، قال تعالى: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فإذا ثبت بقول الطبيب الثقة أو الطبيبين أن هذا المرض الداخلي يضرها إذا صامت فلا بأس بالإفطار، تعتمد قول الطبيب الثقة، وإذا احتاطت بطبيبين يكون أكمل وأطيب، فإذا قررا أن الصوم يضرها بالنسبة إلى القرحة أو مرض آخر فإنها تفطر هذا هو الأفضل لها، ثم تقضي بعد ذلك قضاء لا يضرها. نعم.","link":"https://binbaz.org.sa/fatwas/7451/حكم-افطار-رمضان-لمن-اصيب-بالقرحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18403.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":9307,"question":"من المنطقة الشرقية راس تنورة، رسالة بعثها أخونا مشبب القحطاني ، أخونا يقول: أنا شاب أبلغ من العمر الخامسة والعشرين، قدر الله وأصبت بمرض في إحدى الكليتين، ورقدت في المستشفى لمدة ستة شهور، وبعد خروجي من المستشفى سافرت إلى الهند وأجريت لي عملية هناك تمت بنجاح ولله الحمد، والآن الحمد لله أتمتع بتحسن نحو الشفاء الكامل ولا زلت في فترة العلاج، وقد سألت الدكتور المختص بالعلاج عن الصيام في شهر رمضان ونصحني عن الصيام، ذلك أن علي من الصيام مضرة كما يقول، كما أني سألت نفس السؤال طبيبًا مسلمًا ووجدت نفس الجواب، والآن أسأل سماحة الشيخ كيف أتصرف؟ وإذا كان يصح التكفير من مال أو إطعام كيف يتم إخراجه؟ هل يتم دفعة واحدة، أو في كل يوم، أفيدوني جزاكم الله خيرا؟","title":"حكم من منعه الطبيب من صيام رمضان لمرضه","answer":"الجواب: لا حرج عليك في ترك الصيام، لما ذكره لك الطبيبان حتى يشفيك الله، فإن سمح لك الأطباء بالصيام فالحمد لله، وإلا فعليك أن تكفر عن كل يوم إطعام مسكين، نصف صاع تمر أو رز أو حنطة، أو غير هذا من قوت البلد، ولا حرج أن تجمعها وتعطيها واحدًا في آخر الشهر، أو اثنين أو أكثر، أو تخرجها كل يوم الأمر واسع، إن جمعتها وأعطيتها بعض الفقراء أو أخرجتها كل يوم، أو بعد العيد كل ذلك لا حرج فيه والحمد لله، كل سنة إلى أن يسمح لك الأطباء بالصوم، فلعل الخطر يزول إذا مضى بعض السنوات واستقرت سلامة الكلية لعلهم يسمحون لك بالصوم، فإن سمحوا لك فالحمد لله، وإلا فاستمر على الإطعام. نعم.","link":"https://binbaz.org.sa/fatwas/7466/حكم-من-منعه-الطبيب-من-صيام-رمضان-لمرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18407.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":9308,"question":"الأخ مجدي محمد عبدالخالق مصري الجنسية ومقيم بالعراق يسأل مجموعة من الأسئلة، في سؤاله الأول يقول: أنا رجل متزوج ومعي عائلتي، وقد وضعت زوجتي في أول يوم من شهر رمضان الماضي، وأتى رمضان الآخر وهي مرضع، كيف يكون حالها لو تكرمتم؟","title":"حكم الصيام لمن أتى رمضان وهي مرضع","answer":"الجواب: لا حرج عليها في الإفطار إذا كان الرضاع يضرها معه الصوم، فالحاصل أنها مأذون لها المرضع والحامل، والمريضة، كلهن معذورات، حتى تستطيع الصيام، فإذا جاء رمضان الآخر وهي ترضع ولم تستطع الصيام بل يشق عليها من أجل الرضاع فإنها تفطر رمضان الآخر ثم تصومهما بعد ما يحصل لها القوة على ذلك، إما بفطم الولد أو بقوة تعينها على الصوم، أو بغير هذا من أسباب القدرة.\nفالحاصل: أنها ما دامت يشق عليها الصوم من أجل الرضاع أو من أجل الحمل، أو من أجل بعض الأمراض فإنها تفطر ولا كفارة عليها؛ لأنها غير يائسة من الصوم بل ترجو القدرة عليه، فإذا يسر الله لها الصوم فالحمد لله تصوم الجميع، تصوم ما مضى عليها متتابعًا أو مفرقًا لا حرج، ولا كفارة عليها. نعم.\nالمقدم:إذا أفطرت من أجل الإرضاع، هل يلزمها مع القضاء شيء أو لا.. ؟\nالشيخ: لا يلزمها شيء؛ لأنه كالمرض.\nالمقدم: لأنه كالمرض؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7469/حكم-الصيام-لمن-اتى-رمضان-وهي-مرضع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18408.mp3","categories":["قضاء الصيام","الأعذار المبيحة للفطر"]},{"id":9337,"question":"أولى رسائل هذه الحلقة وردت من السائلة (ن. س) من الخرج تقول في رسالتها: أنا مريضة منذ ثلاث سنوات ولم أصم وهذه السنة التي مضت هي الرابعة، فهل علي الصيام أو الكفارة، وهل يجوز لي إن استطعت أن أؤخر القضاء إلى أيام الشتاء وأقضي منها ما قدرت عليه أفيدوني أفادكم الله؟","title":"حكم من أفطر في رمضان لمرض","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالمريض قد عفا الله عنه في تأخير الصوم؛ لقول الله : وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فهذا فضل من الله  أن سامح المريض في الإفطار وأن يؤجل القضاء إلى الشفاء، ولهذا قال بعده: يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلا يُرِيدُ بِكُمُ الْعُسْرَ [البقرة:185]، فإذا شفاك الله تقضين ما تركت من الصيام والحمد لله.\nأما إن قرر الأطباء أن هذا المرض لا يرجى برؤه وأنه يستمر فعليك أن تطعمي عن كل يوم مسكين ويكفي، كالشيخ الكبير والعجوز الكبيرة اللذين لا يستطيعان الصوم فإنهما يطعمان عن كل يوم مسكيناً، نصف صاع من التمر أو الأرز أو غيرهما من قوت البلد، وهو كيلو ونصف تقريباً، ويكفي عن كل يوم يعطاه بعض الفقراء، أما إنسان ينتظر الشفاء ويرجو الشفاء فهذا لا إطعام عليه ولكن يصبر حتى يشفيه الله، فإذا شفاه الله قضى ما مضى من الصيام ولو سنوات، لأنه معذور شرعاً. نعم.\nالمقدم: ولا كفارة؟\nالشيخ: ولا كفارة.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7501/حكم-من-افطر-في-رمضان-لمرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_238/23801.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":9468,"question":"السؤال الأول ورد من الأخ شيخي محمد بلدية عين الخضرة ولاية المسيلة الجزائر- العاصمة، يسأل في أول سؤال عن حكم من أفطر في رمضان يومين حتى أتاه شهر رمضان القادم، فما حكم ذلك وأفيدوه؟","title":"حكم من أخر قضاء ما عليه من رمضان حتى دخل رمضان","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن من أفطر في رمضان يجب عليه أن يقضي قبل رمضان الآخر، وما بين الرمضانين فهو محل سعة من ربنا ، إذا قضى في شوال أو في ذي القعدة أو في ذي الحجة أو في المحرم أو ما بعد ذلك.. إلى شعبان، فعليه أن يقضي ما أفطره لمرض أو سفر أو نحو ذلك قبل رمضان، فإن أخره إلى رمضان آخر لم يسقط القضاء بل يجب عليه القضاء ولكن يلزمه مع القضاء إطعام مسكين عن كل يوم زيادة مع القضاء، أفتى به جماعة من أصحاب النبي ﷺ، فيقضي ويطعم عن كل يوم مسكينًا نصف صاع من قوت البلد كيلو ونصف من قوت البلد من تمر أو أرز أو غير ذلك، أما إن صام ذلك قبل رمضان القادم فإنه يقضي ولا إطعام عليه. نعم.","link":"https://binbaz.org.sa/fatwas/7632/حكم-من-اخر-قضاء-ما-عليه-من-رمضان-حتى-دخل-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_192/19201.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":9666,"question":"يقول: كنت في وقت مضى تركت شهوراً كثيرة من رمضان لم أصمها عمداً، وهي تقارب ست سنوات، يعني: ستة رمضانات، وكنت في نفس الوقت لا أقصر في صلاتي، والآن لا أقدر على صيامها كلها، وكذلك لا أستطيع أن أكفر إلا أنني أستطيع أن أصومها مجزأة ولو يوماً في الأسبوع، ولا أستطيع أكثر من ذلك أفيدوني أفادكم الله؟","title":"حكم ترك صيام عدة رمضانات","answer":"الجواب: الواجب عليك يا أخي! التوبة إلى الله، التوبة الصادقة التي تشتمل على الندم على الماضي والأسف ما مضى منك، والعزم الصادق أن لا تعود في ذلك، وعليك قضاؤها على حسب طاقتك، ولو يوماً في الأسبوع تقضيها حتى تكمل إن شاء الله، تلك السنوات الست ما دمت تصلي والحمد لله، فعليك أن تكمل وتقضي هذا الصيام على حسب طاقتك فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. نعم.\nوالأول الأول أيضاً عليه إطعام، عليك أن تطعم عن هذه السنوات، عن كل يوم نصف صاع على الصحيح أفتى به جماعة من أصحاب النبي ﷺ، فعليك أن تطعم عن كل يوم مسكيناً إذا كنت تستطيع ذلك، نصف صاع من قوت البلد، من تمر أو رز أو غيرهما إذا استطعت، أما إذا كنت فقيراً فلا شيء عليك. نعم.\nالمقدم: يعني: مع القضاء؟\nالشيخ: مع القضاء، مع الصيام.\nالمقدم: لأنه مر عليها رمضانات؟\nالشيخ: ... مضى عليه رمضانات. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7830/حكم-ترك-صيام-عدة-رمضانات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25112%20After%20editing.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":9897,"question":"سماحة الشيخ: السائل (ع. ب. أ) يقول: لديه فشل كلوي ويداوم على غسيل الكلية لمدة ثلاثة أيام في الأسبوع، فهل يجوز له الصيام في هذه الأيام عند دخول رمضان؟","title":"حكم الصيام في أيام الغسيل الكلوي","answer":"الجواب: نعم يجوز له الصيام في الأيام التي ليس فيها غسيل، ويجب عليه إذا كان عليه قضاء يجب عليه القضاء في الأيام السليمة التي ما فيها غسيل، أما التطوع فالأمر واسع فيه، إذا كان التطوع يضره فالأولى ترك التطوع، لكن إذا كان عليه صيام فريضة بنذر أو قضاء رمضان، فالواجب عليه البدار بالصوم في الأيام التي ما فيها غسيل. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8065/حكم-الصيام-في-ايام-الغسيل-الكلوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27309.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":9926,"question":"يسأل ثانية ويقول: أفطر رمضان وأنا في العراق من أجل العمل الذي أعيش منه أولادي، ولكن أستطيع إعادة الصيام عند العودة إلى مصر فما حكم ذلك؟ بارك الله فيكم.","title":"الإفطار في رمضان بحجة العمل","answer":"الجواب: ما دمت قد نويت الإقامة في العراق للعمل عليك أن تصوم، إن كنت نويت أن تقيم رمضان أو ما هو أكثر من رمضان في العراق أو في غيره فعليك أن تصوم مع الناس، وليس لك عذر في الإفطار، هذا الذي عليه جمهور أهل العلم أن عليك أن تصوم ولست في حكم المسافر، بل تصوم مع الناس، فإذا أصابك ما يمنع من مرض أو سافرت في أثناء رمضان لك أن تفطر بالسفر والمرض، أما وأنت مقيم تعمل فعليك أن تصوم مع المسلمين، وليس لك الإفطار، ومتى أفطرت من دون عذر سفر ولا مرض فعليك التوبة إلى الله وعليك القضاء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8095/الافطار-في-رمضان-بحجة-العمل","audio":"","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":9930,"question":"أخيراً تقول هذه السائلة: في أول يوم من شهر رمضان المبارك زارتني امرأة عجوز عمرها في حدود مائة سنة أحياناً يكون وعيها معها وأحياناً العكس، فطلبت مني أن أقدم لها قهوة ففعلت ذلك وأحضرت لها القهوة فهل علي ذنب في هذا مع العلم أنني أخبرتها أننا في شهر رمضان؟ أفيدوني أفادكم الله.","title":"حكم إطعام شخص كبير السن في نهار رمضان","answer":"الجواب: إذا كان ظاهرها أن عقلها مفقود وأنها قد دخلت في التخريف والهرم فلا بأس؛ لأنها ليس عليها صيام، وحضور بعض العقل معها بكلام المضبوط تقول أبغى كذا وإلا أعطوني كذا هذا ما يدل على عقل، والغالب على من بلغ مائة سنة يدخله التخريف والتغير، فإذا ظهر لك من حالها أن عقلها مفقود وأنها غير منضبطة فلا بأس أن تأكل وتشرب، أما إن ظهر لك أن عقلها معها وأنها متساهلة فلا تعطيها قهوة ولا غيرها لا تعينيها على الباطل، الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2] فاللي يطلب الطعام في رمضان وهو صحيح من المسلمين لا يعطى لا طعام ولا شراب ولا دخان لا يعان على الباطل، أما من كان فاقد العقل كالمعتوه والمجنون والهرم والهرمة هؤلاء ليس عليهم جناح ذهب عنهم الصوم. والله المستعان.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8102/حكم-اطعام-شخص-كبير-السن-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_269/26907.mp3","categories":["الأعذار المبيحة للفطر","من يجب عليه الصوم"]},{"id":9978,"question":"هذه رسالة من الأخت السائلة (زينب . ع. ف. ض.) من السعودية الأخت زينب تقول في رسالتها: هي فتاة مسلمة والحمد لله تصوم وتصلي وقد أصابها مرض شديد في يوم من أيام رمضان، وقد أوشكت على الموت فأفطرت من شدة المرض ثم قضت هذا اليوم، فتسأل هل عليها في فطرها إثم؟","title":"حكم الفطر في نهار رمضان للمريض","answer":"الجواب: ليس عليها إثم بل مأجورة، الإنسان إذا أصابه المرض وشق عليه الصوم شرع له أن يفطر وهو مأجور في قبول الرخصة، يقول الله سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] ويقول النبي ﷺ: إن الله يحب أن تؤتى رخصه كما يكره أن تؤتى معصيته فإذا أخذ الإنسان بالرخصة طاعة لله وعملًا بما شرع  فهو مأجور ولا إثم عليه، فأنت أيها الأخت السائلة لا حرج عليك في إفطارك من أجل مرض وعليك القضاء وقد قضيت والحمد لله. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8137/حكم-الفطر-في-نهار-رمضان-للمريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_200/20006.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10235,"question":"امرأة كانت لا تعلم أن على المرضع والنفساء قضاء الأيام التي أفطرتها في رمضان، وقال لها بعض الناس: إن عليها أن تطعم عن كل يوم أفطرته مسكينًا، وقد فعلت ذلك، فهل يكفي هذا الإطعام، أم لابد من قضاء الأيام التي أفطرتها؟ وهل إطعامها الذي أطعمته يكفي، أم تطعم مرة أخرى؟ علمًا بأن هذا الإطعام مرت عليه سنوات كثيرة.","title":"حكم من أفطرت بسبب عذر شرعي وأطعمت ولم تقض","answer":"الجواب: عليها أن تقضي، إذا أفطرت الحامل أو المرضع وهكذا المريضة فإنها تقضي بعد ذلك، تقضي المريضة إذا شفيت، وتقضي الحامل إذا وضعت واستطاعت القضاء بعد ذلك، وتقضي المرضع كذلك، كلهن يقضين ولا يجزئ عنهن الإطعام، وإذا تأخر القضاء بغير عذر وجب القضاء والإطعام، أما إذا كان التأخير للعذر لأنها حامل، ولأن الرضاع يمنعها من ذلك أو المرض فالإطعام لا يجب، ولكن يجب القضاء فقط؛ لأنها معذورة في التأخير، فليس عليها إلا القضاء إذا شفيت المريضة وفطمت المرضعة أو قويت على الصيام وإن لم تفطم، وولدت الحامل وقويت على القضاء فإن كلًا منهن يقضي، وليس عليه إطعام لأنه معذور، لكن من تأخر قضاؤها بدون عذر فعليها مع القضاء الإطعام، ويجزئها الإطعام الذي أخرجته تحسب أن هذا هو الواجب عليها لفتوى بعض الناس، يجزئها الإطعام عما يجب عليها من الإطعام إذا كانت تأخرت في القضاء؛ لأنها أخرجت الإطعام عن تأخيرها وعن إفطارها. \nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8403/حكم-من-افطرت-بسبب-عذر-شرعي-واطعمت-ولم-تقض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_335/33509.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10290,"question":"تقول في قضية أخرى سماحة الشيخ: عندما بلغت سن التكليف لم أكن أعلم بالطريقة الصحيحة لأداء الفروض ومن ذلكم الصيام، فكنت أصوم أياماً وأفطر أياماً ولم ينبهني أهلي على هذا الأمر، ولما كبرت أكثر وأكثر أدركت أني كنت مخطئة، كيف أتصرف والحال ما ذكر ولا سيما وقد أفطرت بعض الأيام ولا أدري كم هي، جزاكم الله خيراً؟","title":"حكم قضاء من أفطر أياماً معلومة من رمضان جاهلاً","answer":"الجواب: عليك أن تقضي الأيام التي أفطرت بالظن، الذي يغلب على ظنك أنك أفطرت صومي اقضيه والحمد لله، فإذا كان ظنك أنك أفطرت عشرة أيام عشرين يوماً أكثر أقل فاعملي بذلك، ولا حاجة إلى اليقين، اعملي بالظن والحمد لله، الذي تظنين افعلي، فإذا شككت هل هي عشرة أو خمسة عشر، صومي خمسة عشر، شككت هل أفطرت خمسة عشر أو عشرين صومي عشرين، اعملي بغالب الظن والحمد لله، ولا شيء عليك.\nلكن إذا كنت مليئة تستطيعين أن تطعمي أطعمي عن الصيام الذي مضى قبل رمضان الماضي، الصيام الذي أخرتيه قبل رمضان الماضي أطعمي عن كل يوم مسكين زيادة مع الصوم نصف صاع مقدار كيلو ونصف من قوت البلد من تمر أو أرز أو حنطة أو شعير نصف صاع يقارب كيلو ونصف تقريباً يعطاه الفقير، تجمعين ذلك كله وتعطينه لبعض الفقراء فقير أو فقيرين يكفي، والحمد لله، إذا كنت موسرة، أما إذا كنت عاجزة فقيرة فلا حاجة إلى الإطعام يكفي الصوم والحمد لله، حسب ظنك واجتهادك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8462/حكم-قضاء-من-افطر-اياما-معلومة-من-رمضان-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_312/31202.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10295,"question":"تقول في قضية أخرى سماحة الشيخ: عندما بلغت سن التكليف لم أكن أعلم بالطريقة الصحيحة لأداء الفروض ومن ذلكم الصيام، فكنت أصوم أياماً وأفطر أياماً ولم ينبهني أهلي على هذا الأمر، ولما كبرت أكثر وأكثر أدركت أني كنت مخطئة، كيف أتصرف والحال ما ذكر ولا سيما وقد أفطرت بعض الأيام ولا أدري كم هي، جزاكم الله خيراً؟","title":"حكم قضاء من أفطر أياماً معلومة من رمضان جاهلاً","answer":"الجواب: عليك أن تقضي الأيام التي أفطرت بالظن، الذي يغلب على ظنك أنك أفطرت صومي اقضيه والحمد لله، فإذا كان ظنك أنك أفطرت عشرة أيام عشرين يوماً أكثر أقل فاعملي بذلك، ولا حاجة إلى اليقين، اعملي بالظن والحمد لله، الذي تظنين افعلي، فإذا شككت هل هي عشرة أو خمسة عشر، صومي خمسة عشر، شككت هل أفطرت خمسة عشر أو عشرين صومي عشرين، اعملي بغالب الظن والحمد لله، ولا شيء عليك.\nلكن إذا كنت مليئة تستطيعين أن تطعمي أطعمي عن الصيام الذي مضى قبل رمضان الماضي، الصيام الذي أخرتيه قبل رمضان الماضي أطعمي عن كل يوم مسكين زيادة مع الصوم نصف صاع مقدار كيلو ونصف من قوت البلد من تمر أو أرز أو حنطة أو شعير نصف صاع يقارب كيلو ونصف تقريباً يعطاه الفقير، تجمعين ذلك كله وتعطينه لبعض الفقراء فقير أو فقيرين يكفي، والحمد لله، إذا كنت موسرة، أما إذا كنت عاجزة فقيرة فلا حاجة إلى الإطعام يكفي الصوم والحمد لله، حسب ظنك واجتهادك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8462/حكم-قضاء-من-افطر-اياما-معلومة-من-رمضان-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_312/31202.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10309,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (س. ص) يقول: ذكرت بعد مضي سنة أني لم أصم يوماً من الأيام وأنا مسافر في رمضان، فهل علي قضاء هذا اليوم والإطعام أم ماذا جزاكم الله خيراً؟","title":"حكم نسيان قضاء رمضان حتى دخول رمضان آخر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالواجب عليك قضاء هذا اليوم؛ لأن الله جل وعلا يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185].\nأما كونك ناسياً فلا يمنع من القضاء وإنما يسقط عنك الإثم بسبب النسيان، وليس عليك كفارة ما دمت لم تذكر إلا بعد رمضان آخر؛ لأنك معذور بالنسيان ولا حرج عليك في عدم التكفير.\nأما إن كنت ذكرت اليوم قبل رمضان ثم تساهلت ولم تقضه إلا بعد رمضان فعليك إطعام مسكين نصف صاع من قوت البلد، من تمر أو حنطة أو أرز أو شعير يدفع لمسكين واحد، أما إذا كان النسيان استمر معك حتى دخل رمضان آخر فلا شيء عليك إلا القضاء. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8475/حكم-نسيان-قضاء-رمضان-حتى-دخول-رمضان-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_313/31301.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10338,"question":"المستمع مليكي موسى أحمد السويرد الصلاحي طالب بمعهد إعداد المعلمين بالليث، بعث برسالة وضمنها جمعاً من الأسئلة:من بينها سؤال يقول فيه: سافرت يوماً في رمضان، إلى منطقة تبعد عن المنطقة التي أسكن فيها ثلاثمائة وثمانين كيلو متر، وأنا صائم، وسافرت في الصباح وعندما وصلت جدة في الثاني عشر ظهراً لم أستطع أن أكمل اليوم فاضطررت إلى الإفطار، فهل علي من إثم وبماذا تنصحونني جزاكم الله خيراً؟","title":"حكم المسافر إذا أفطر في نهار رمضان","answer":"الجواب: المسافر السنة له الفطر، والأفضل له الفطر، فإذا سافرت فالأفضل لك الفطر، حتى ولو ما اشتد عليك شيء الأفضل الفطر ولو كنت مستريحاً، وإذا كانت جدة في طريق السفر ليست هي المقصودة، فإنك تفطر فيها، ولو كان لا شدة عليك في ذلك، أما مع الشدة فيتأكد الفطر، لقول النبي ﷺ: ليس من البر الصوم في السفر، ولما نزل بأصحابه في بعض الأسفار وفيهم صوام ومفطرون، سقط الصوام بسبب شدة الظمأ، وقام المفطرون فضربوا الأخبية وسقوا الركاب، فقال النبي ﷺ: ذهب المفطرون اليوم بالأجر.\nأما إن كانت جدة هي المقصود وأنك مسافر إليها، فإن كنت تريد الإقامة فيها أكثر من أربعة أيام أتممت الصوم؛ لأنك الآن في حال الصوم، مأمور بالصيام لا تفطر أما إن كان في الطريق أو ما أردت الإقامة فيها إلا أقل من أربعة أيام فأقل فلك الإفطار ولو ما اشتد بك الأمر، هكذا السنة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8503/حكم-المسافر-اذا-افطر-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_315/31503.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":10341,"question":"المستمع مليكي موسى أحمد السويرد الصلاحي طالب بمعهد إعداد المعلمين بالليث، بعث برسالة وضمنها جمعاً من الأسئلة:من بينها سؤال يقول فيه: سافرت يوماً في رمضان، إلى منطقة تبعد عن المنطقة التي أسكن فيها ثلاثمائة وثمانين كيلو متر، وأنا صائم، وسافرت في الصباح وعندما وصلت جدة في الثاني عشر ظهراً لم أستطع أن أكمل اليوم فاضطررت إلى الإفطار، فهل علي من إثم وبماذا تنصحونني جزاكم الله خيراً؟","title":"حكم المسافر إذا أفطر في نهار رمضان","answer":"الجواب: المسافر السنة له الفطر، والأفضل له الفطر، فإذا سافرت فالأفضل لك الفطر، حتى ولو ما اشتد عليك شيء الأفضل الفطر ولو كنت مستريحاً، وإذا كانت جدة في طريق السفر ليست هي المقصودة، فإنك تفطر فيها، ولو كان لا شدة عليك في ذلك، أما مع الشدة فيتأكد الفطر، لقول النبي ﷺ: ليس من البر الصوم في السفر، ولما نزل بأصحابه في بعض الأسفار وفيهم صوام ومفطرون، سقط الصوام بسبب شدة الظمأ، وقام المفطرون فضربوا الأخبية وسقوا الركاب، فقال النبي ﷺ: ذهب المفطرون اليوم بالأجر.\nأما إن كانت جدة هي المقصود وأنك مسافر إليها، فإن كنت تريد الإقامة فيها أكثر من أربعة أيام أتممت الصوم؛ لأنك الآن في حال الصوم، مأمور بالصيام لا تفطر أما إن كان في الطريق أو ما أردت الإقامة فيها إلا أقل من أربعة أيام فأقل فلك الإفطار ولو ما اشتد بك الأمر، هكذا السنة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8503/حكم-المسافر-اذا-افطر-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_315/31503.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":10408,"question":"مستمع مواطن مصري الجنسية مقيم في العراق يقول: لقد أصابني حريق في شهر رمضان ولم أستطع الصيام، والطبيب الذي كان يشرف على علاجي كان طبيبًا مسلمًا ونصحني بعدم الصيام، لم أطعم مساكين لحالتي المادية الضعيفة، وجهوني كيف أتصرف جزاكم الله خيرًا؟","title":"من أفطر رمضان بسبب المرض","answer":"الجواب: إذا كنت تستطيع الصيام تصوم تقضي والحمد لله، وإن كنت لا تستطيع الآن فيؤجل حتى تستطيع، وإذا استطعت تصوم والحمد لله وليس عليك شيء فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] الله يقول سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] والحرق الذي أصابك نوع من المرض.\nأما إن قرر الأطباء أنك لا تستطيع الصوم وأن هذا المرض مستمر وأنه صار هذا المرض ملازم ما في حيلة فيما يظهر لهم، فإنك تطعم عن كل يوم مسكين، من الأيام التي أفطرتها نص صاع من التمر أو نحوه كالرز والحنطة ويكفي إذا كنت عاجزًا عن الصيام، حسب تقرير الأطباء أن هذا المرض الذي حصل بسبب الحريق ملازم ولا يرجى برؤه ويشق عليك الصوم معه تطعم عن كل يوم مسكينًا من قوت البلد نصف صاع من قوت البلد.\nأما إذا قدرت فإنك تصوم، وإذا أخرت الصيام مع القدرة حتى جاء رمضان الآخر يكون عليك إطعام مع الصيام زيادة، تصوم وتطعم عن كل يوم مسكين؛ لأنه لا يجوز تأخير الصيام إلى رمضان الآخر وأنت قادر. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/8581/من-افطر-رمضان-بسبب-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34015.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10426,"question":"حدثونا لو تكرمتم عن امرأة عليها أيام من شهر رمضان من عامين أو ثلاثة أيام، هل تؤدي ما عليها من أيام فقط، أم عليها كفارة؟ وما كفارتها؟","title":"حكم من أخرت قضاء رمضان حتى دخل عليها رمضان الآخر","answer":"الجواب: إذا أخر الإنسان الصيام عاماً أو أكثر من دون عذر فعليه التوبة إلى الله والندم والعزم أن لا يعود، وعليه القضاء وعليه الكفارة جميعاً ثلاثة أشياء: التوبة، وقضاء الأيام التي على الإنسان من رجل أو امرأة، وإطعام مسكين عن كل يوم، أما إن كان لعذر كالمرض فلا شيء عليها إلا القضاء فقط، وأما التساهل فعليه القضاء، وعليه التوبة إلى الله، وعليه إطعام مسكين عن كل يوم بحسب الأيام، كل يوم عليه نصف صاع يجمعها ويعطيها بيتاً فقيراً أو شخصاً فقيراً كلها، لا بأس يجمعها ويعطيها بعض الفقراء في أول الشهر أو في آخره، في أول الصيام أو في آخر الصيام، هذا إذا كان أخرها عاماً أو أكثر، أما إذا كان قضاها في العام قبل رمضان الآخر، في نفس العام قضى.. هذا ما عليه إلا القضاء وليس عليه إطعام. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8602/حكم-من-اخرت-قضاء-رمضان-حتى-دخل-عليها-رمضان-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_317/31709.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10463,"question":"من إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (ص. هـ. ي) من الرياض تقول في أحدها: اشتد علي العطش في يوم رمضان، وكنت أقوم برعي الغنم في البادية، فأغمي علي وأفطرت، ماذا علي حينئذٍ، جزاكم الله خيراً؟","title":"حكم من أفطر في رمضان مضطراً","answer":"الجواب: لا شيء من أجل الضرورة، لكن عليك القضاء، .. لأن الإنسان إذا اضطر إلى الفطر أفطر ويمسك، إذا اشتد بالإنسان ظمأ يشرب ما يسد ما يزيل الظمأ ثم يمسك إلى الغروب ويقضي، وهكذا لو أصابه جوع شديد وأكل خوفاً من الخطر يقضي بعد ذلك، يمسك ويقضي فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8646/حكم-من-افطر-في-رمضان-مضطرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32012.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10472,"question":"يقول: أفطرت بعض أيام من رمضان وحينئذٍ تأخرت في القضاء، وبدأت أقضيها الآن، فماذا علي، جزاكم الله خيراً؟","title":"حكم من أفطر في رمضان وأخر القضاء حتى رمضان الآخر","answer":"الجواب: إذا كنت قضيتها قبل رمضان الثاني فليس عليك إلا القضاء الحمد لله، أما إذا كنت أخرتها بعد رمضان فعليك مع القضاء إطعام مسكين عن كل يوم مع التوبة والاستغفار، وهو إطعام مسكين يعني: نص صاع تمر أو رز أو غيره من قوت البلد مقداره كيلو ونص تقريباً مع التوبة والاستغفار والصيام، إذا كنت أخرتها بغير عذر لا مرض ولا عذر آخر كالسفر، فالإنسان إذا أخر الصيام عن السنة إلى رمضان الآخر فإنه يكون قد أتى معصية، فعليه التوبة إلى الله، وعليه القضاء وعليه إطعام مسكين عن كل يوم، أفتى به جماعة من الصحابة  وأرضاهم كالتعزير. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8644/حكم-من-افطر-في-رمضان-واخر-القضاء-حتى-رمضان-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32010.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10593,"question":"من جامعة الملك فهد للبترول والمعادن أحد الإخوة المستمعين سمى نفسه منصور بعث برسالة وضمنها قضية يقول فيها: قبل سنوات قليلة حوالي ثلاث أو أربع سنوات كنت أجهل الكثير من أحكام الصيام والعقوبات المترتبة على من خالف أحد هذه الأحكام، كنا ثلاثة إخوة بالغين، وكان إذا جاء رمضان صمنا بعض أيامه الأولى، ثم أفطرنا البعض بجهل تام منا بالعقوبة الوخيمة المترتبة على الإفطار المتمثلة بالحديث الذي معناه: «من أفطر يوماً من رمضان لم يجزئه صيام الدهر كله وإن صامه» الحديث قلته بالمعنى، أفيدوني كيف نتصرف جزاكم الله خيراً؟","title":"ما يلزم من أفطر في رمضان عمداً وهو جاهل","answer":"الجواب: عليكم التوبة إلى الله والندم، والعزم الصادق أن لا تعودوا، وعليكم قضاء الأيام التي أفطرتموها كلكم، والحديث المذكور حديث ضعيف ليس بصحيح عند أهل العلم حديث مضطرب، ويكفي أن يصوم مع التوبة، من صام يوماً بدل يوم كفى والحمد لله، شهر بدل شهر كفى والحمد لله مع التوبة إلى الله، وأما الحديث الذي ذكره السائل: من أفطر يوماً عمداً بغير عذر لم يقضه صوم الدهر وإن صامه، حديث ضعيف ذكر المحققون من أهل العلم أنه مضطرب لا يثبت، ولو صح لكان من باب الوعيد والتحذير، وإلا فاليوم يكفي، قال الله تعالى: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، وهكذا من أفطر عمداً عليه عدة من أيام أخر مع التوبة إلى الله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8770/ما-يلزم-من-افطر-في-رمضان-عمدا-وهو-جاهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_325/32508.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10597,"question":"من جامعة الملك فهد للبترول والمعادن أحد الإخوة المستمعين سمى نفسه منصور بعث برسالة وضمنها قضية يقول فيها: قبل سنوات قليلة حوالي ثلاث أو أربع سنوات كنت أجهل الكثير من أحكام الصيام والعقوبات المترتبة على من خالف أحد هذه الأحكام، كنا ثلاثة إخوة بالغين، وكان إذا جاء رمضان صمنا بعض أيامه الأولى، ثم أفطرنا البعض بجهل تام منا بالعقوبة الوخيمة المترتبة على الإفطار المتمثلة بالحديث الذي معناه: «من أفطر يوماً من رمضان لم يجزئه صيام الدهر كله وإن صامه» الحديث قلته بالمعنى، أفيدوني كيف نتصرف جزاكم الله خيراً؟","title":"ما يلزم من أفطر في رمضان عمداً وهو جاهل","answer":"الجواب: عليكم التوبة إلى الله والندم، والعزم الصادق أن لا تعودوا، وعليكم قضاء الأيام التي أفطرتموها كلكم، والحديث المذكور حديث ضعيف ليس بصحيح عند أهل العلم حديث مضطرب، ويكفي أن يصوم مع التوبة، من صام يوماً بدل يوم كفى والحمد لله، شهر بدل شهر كفى والحمد لله مع التوبة إلى الله، وأما الحديث الذي ذكره السائل: من أفطر يوماً عمداً بغير عذر لم يقضه صوم الدهر وإن صامه، حديث ضعيف ذكر المحققون من أهل العلم أنه مضطرب لا يثبت، ولو صح لكان من باب الوعيد والتحذير، وإلا فاليوم يكفي، قال الله تعالى: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، وهكذا من أفطر عمداً عليه عدة من أيام أخر مع التوبة إلى الله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8770/ما-يلزم-من-افطر-في-رمضان-عمدا-وهو-جاهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_325/32508.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10615,"question":"أولى رسائل هذه الحلقة، رسالة وصلت إلى البرنامج من المستمع (ع. م.هـ) من معهد الدلم العلمي، أخونا ضمن رسالته جمعاً من الأسئلة، في أحدها يقول: إنني في شهر رمضان المبارك قبل سنتين ذهبت إلى مكة المكرمة لأداء مناسك العمرة، فاضطررت للإفطار في اليوم الذي ذهبت فيه، وكان يجب علي أن أصومه فيما بعد -أي: بعد شهر رمضان المبارك- ولكنني تهاونت، فجاء شهر رمضان بالسنة المقبلة ولم أصم ذلك اليوم، فقلت بعد هذا الشهر، ولكن مرت الأيام ولم أصمه، كل يوم أقول: غداً، حتى جاء شهر رمضان للسنة الثانية ولم أصمه حتى هذا اليوم، ولكنني تنبهت لهذا الأمر، فقررت أن أصومه، ولكن هل أصوم يوماً واحداً؟ أم علي صيام أيام تكفيراً، ما هو الحكم ، وأنا في انتظار إجابتكم، جزاكم الله خيراً؟","title":"حكم من أفطر من رمضان ولم يقضه حتى جاء رمضان الآخر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالواجب قضاء يوم واحد؛ لأن الله سبحانه يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فأنت عليك قضاء يوم واحد مع التوبة والاستغفار؛ لأجل تفريطك في التأخير، وعليك مع ذلك إطعام مسكين نصف صاع من تمر أو أرز مقدار كيلو ونصف تقريباً، يدفع لبعض الفقراء، مع التوبة والاستغفار، والحمد لله.\nالمقدم: الحمد لله، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8789/حكم-من-افطر-من-رمضان-ولم-يقضه-حتى-جاء-رمضان-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_327/32701.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10713,"question":"من الجمهورية العربية السورية الأخت السائلة نورا محمد بعثت تقول: إنني لم أستطع صيام شهر رمضان المبارك، بسبب الحمل، وقد نويت على الصيام بعد الولادة، ولكن بعد الولادة إرضاع فلم أستطع الصيام، بسبب الإرضاع كما قلت، ولأن جسمي لا يتحمل الصيام، أفيدونا أفادكم الله، هل تجوز الصدقة عن الصيام، أم يجب أن أصوم الشهر الذي فاتني وأنا لا أستطيع؟ بماذا ترشدوني جزاكم الله خيراً؟","title":"حكم من عجزت عن الصوم وقضائه بسبب الحمل والرضاع","answer":"الجواب: عليك الصيام عند الاستطاعة: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، فالمرضعة والحامل مثل المريض، إذا شق عليهما الصيام أجلا الصيام ولو بعد رمضان آخر، ما دمت لا تستطيعين من أجل الرضاع، فأنت معذورة كالمريضة، فإذا يسر الله لك الصيام ولو مفرقاً، يوم تصومين ويومين تفطرين، وثلاثة تفطرين، وأربعة تفطرين، فلا بأس، ليس بلازم المتابعة، لا بأس بالتفرقة، فإذا عجزت أجلي والحمد لله، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8895/حكم-من-عجزت-عن-الصوم-وقضاىه-بسبب-الحمل-والرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34310.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10714,"question":"من الجمهورية العربية السورية الأخت السائلة نورا محمد بعثت تقول: إنني لم أستطع صيام شهر رمضان المبارك، بسبب الحمل، وقد نويت على الصيام بعد الولادة، ولكن بعد الولادة إرضاع فلم أستطع الصيام، بسبب الإرضاع كما قلت، ولأن جسمي لا يتحمل الصيام، أفيدونا أفادكم الله، هل تجوز الصدقة عن الصيام، أم يجب أن أصوم الشهر الذي فاتني وأنا لا أستطيع؟ بماذا ترشدوني جزاكم الله خيراً؟","title":"حكم من عجزت عن الصوم وقضائه بسبب الحمل والرضاع","answer":"الجواب: عليك الصيام عند الاستطاعة: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، فالمرضعة والحامل مثل المريض، إذا شق عليهما الصيام أجلا الصيام ولو بعد رمضان آخر، ما دمت لا تستطيعين من أجل الرضاع، فأنت معذورة كالمريضة، فإذا يسر الله لك الصيام ولو مفرقاً، يوم تصومين ويومين تفطرين، وثلاثة تفطرين، وأربعة تفطرين، فلا بأس، ليس بلازم المتابعة، لا بأس بالتفرقة، فإذا عجزت أجلي والحمد لله، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8895/حكم-من-عجزت-عن-الصوم-وقضاىه-بسبب-الحمل-والرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34310.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":10867,"question":"رسالة وصلت إلى البرنامج من المستمع (ع. أ. ح) من مدينة جدة مفهوم ما في هذه الرسالة يقول: كان النساء لا يقضين ما أفطرنه من رمضان بسبب أعذارهن الشرعية، كالحيض مثلًا، والآن اكتشفن أنهن كن على خطأ، بم تنصحونهن؟ جزاكم الله خيرًا، ولا سيما أنهن لا يعلمن عدد الرمضانات التي أفطرن فيها.","title":"حكم من نسيت عدد ما أفطرته في رمضان","answer":"الجواب:  عليهن أن يقضين ما يغلب على الظن أنهن تركنه من الصيام، والله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، فعليهن أن يتحرين ما أفطرن فيه، ويقضينه، ويطعمن عن كل يوم مسكينًا، زيادة مع القضاء إذا كن قادرات على الطعام، كل يوم عنه إطعام مسكين، نصف صاع من التمر، أو الأرز، أو الحنطة، أو الشعير حسب الطاقة، وإذا كن لا يستطعن الطعام كفى الصيام، والحمد لله؛ لأن الله يقول -جل وعلا-: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]. والحائض كذلك، والنفساء كذلك كالمريض يقضي، تقضي الصوم كما يقضي المريض، والمسافر، وإذا نسيت العدد فإنها تتحرى في غالب ظنها، وتصوم، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9039/حكم-من-نسيت-عدد-ما-افطرته-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35707.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11056,"question":"بعد هذا ننتقل إلى سلطنة عمان عبر رسالة بعث بها المستمع: محمد بن سالم، أخونا له جمع من الأسئلة من بينها سؤال يقول فيه: تهاونت في الصيام في بعض الأيام في أشهر مضت من رمضان حيث أفطرت عمدًا، وقبل رمضانين التزمت وتبت ولزمت، ثم إني عزمت على عدم العودة إلى التهاون في رمضان، هل تجزئ هذه التوبة، أم تلزمني الكفارة؟ علمًا بأني قد نسيت عدد الأيام التي أفطرتها؟","title":"حكم من أفطر أياماً من رمضان عمداً ولا يعلم عددها","answer":"الجواب:  التوبة يمحو الله بها الذنب، ولك فيها الأجر العظيم، كما قال الله سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، وقال النبي ﷺ: التائب من الذنب كمن لا ذنب له، وقال -عليه الصلاة والسلام-: التوبة تهدم ما قبلها، وعليك قضاء الأيام لقول الله  في المريض والمسافر: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، فتقضي حسب ظنك هذا هو الأحوط لك، وإن كنت قد تبت فعليك أن تقضيها حسب ظنك، فإذا كنت تظنها عشرة أيام اقض عشرة، عشرين عشرين، وهكذا.. اعمل بظنك إذا كنت لا تستطيع الجزم، والله -جل وعلا- يعفو عما سلف بالتوبة الصحيحة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9234/حكم-من-افطر-اياما-من-رمضان-عمدا-ولا-يعلم-عددها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36707.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11104,"question":"تقول: في بداية حياتي كنت معذورة شرعًا، ولكنني لم أقض الأيام التي أفطرتها في رمضان، لجهلي بكثير من الأحكام، وبما فطر عليه النساء، والآن أريد أن أقضي تلك الأيام، لكني لا أعرف عددها، ولا كم هي، فكيف توجهونني، وهل يلزمني مع الصيام أشياء أخرى؟ جزاكم الله خيرًا.","title":"عليه أيام من رمضان لا يعرف عددها فماذا يفعل؟","answer":"الجواب:  عليك التوبة إلى الله النصوح، والصدق وبالندم والحزن على ما جرى منك، والعزيمة الصادقة أن لا تعودي في ذلك، وعليك القضاء بحسب ظنك، إذا لم تعلمي عليك العمل بالظن، تحسبين الأيام التي عليك، عشرين يومًا، ثلاثين يومًا، أربعين يومًا التي أفطرت، الأيام التي أفطرتيها من رمضان، عليك أن تقضيها، مع إطعام مسكين عن كل يوم إذا كنت قادرة. أما إن كنت فقيرة ما تستطيعين فإنه يكفي الصيام، أما مع الاستطاعة تطعمين عن كل يوم مسكينًا، كيلو ونصف عن كل يوم، نصف صاع يعني، فعن اليومين صاع، وعن.. الأربعة صاعان وهكذا، تعطيها بعض الفقراء، قبل الصيام، أو بعد الصيام، ولو فقيرًا واحدًا، تجمع ويعطاها فقير أو فقيران، أو أهل بيت فقير يكفي هذا، والحمد لله، مع التوبة والاستغفار والندم وعدم العود، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9298/عليه-ايام-من-رمضان-لا-يعرف-عددها-فماذا-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36816.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11120,"question":"تقول: في بداية حياتي كنت معذورة شرعًا، ولكنني لم أقض الأيام التي أفطرتها في رمضان، لجهلي بكثير من الأحكام، وبما فطر عليه النساء، والآن أريد أن أقضي تلك الأيام، لكني لا أعرف عددها، ولا كم هي، فكيف توجهونني، وهل يلزمني مع الصيام أشياء أخرى؟ جزاكم الله خيرًا.","title":"عليه أيام من رمضان لا يعرف عددها فماذا يفعل؟","answer":"الجواب:  عليك التوبة إلى الله النصوح، والصدق وبالندم والحزن على ما جرى منك، والعزيمة الصادقة أن لا تعودي في ذلك، وعليك القضاء بحسب ظنك، إذا لم تعلمي عليك العمل بالظن، تحسبين الأيام التي عليك، عشرين يومًا، ثلاثين يومًا، أربعين يومًا التي أفطرت، الأيام التي أفطرتيها من رمضان، عليك أن تقضيها، مع إطعام مسكين عن كل يوم إذا كنت قادرة. أما إن كنت فقيرة ما تستطيعين فإنه يكفي الصيام، أما مع الاستطاعة تطعمين عن كل يوم مسكينًا، كيلو ونصف عن كل يوم، نصف صاع يعني، فعن اليومين صاع، وعن.. الأربعة صاعان وهكذا، تعطيها بعض الفقراء، قبل الصيام، أو بعد الصيام، ولو فقيرًا واحدًا، تجمع ويعطاها فقير أو فقيران، أو أهل بيت فقير يكفي هذا، والحمد لله، مع التوبة والاستغفار والندم وعدم العود، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9298/عليه-ايام-من-رمضان-لا-يعرف-عددها-فماذا-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36816.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11343,"question":"تقول عندما كنت صغيرة لم أكن أهتم بقضاء الصيام عندما أفطر للعذر الشرعي والآن تذكرت، لكني لا أدري كم هي المدة التي لم أصمها، وكم هي عدد الأشهر التي أفطرت فيها، فبماذا تنصحونني الآن، وهل علي كفارة وقضاء؟ جزاكم الله خيرًا.","title":"حكم من أفطرت أياماً في عدة رمضانات لعذر ولم تقضها","answer":"الجواب:  عليك أن تصومي بالتحري والظن جميع الأيام التي أفطرتيها، عليك أن تتحري وتعملي بالظن حتى تصومي جميع الأيام ولو مفرقة غير متتابعة ولو مفرقة، مع التوبة الصادقة إلى الله مع التوبة النصوح والندم على ما مضى منك والعزم ألا تعودي في هذا الشيء ومع إطعام مسكين عن كل يوم نصف صاع عن كل يوم تجمعيها وتعطيها بعض الفقراء، فقير أو فقيرين أو أكثر، مع التوبة الصادقة والندم وعدم العود. نعم. المقدم: جزاكم الله خيرًا، إذًا عليها مع القضاء كفارة؟ الشيخ: نعم إطعام مسكين عن كل يوم. المقدم: بارك الله فيكم وجزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9540/حكم-من-افطرت-اياما-في-عدة-رمضانات-لعذر-ولم-تقضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37817.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11357,"question":"تقول عندما كنت صغيرة لم أكن أهتم بقضاء الصيام عندما أفطر للعذر الشرعي والآن تذكرت، لكني لا أدري كم هي المدة التي لم أصمها، وكم هي عدد الأشهر التي أفطرت فيها، فبماذا تنصحونني الآن، وهل علي كفارة وقضاء؟ جزاكم الله خيرًا.","title":"حكم من أفطرت أياماً في عدة رمضانات لعذر ولم تقضها","answer":"الجواب:  عليك أن تصومي بالتحري والظن جميع الأيام التي أفطرتيها، عليك أن تتحري وتعملي بالظن حتى تصومي جميع الأيام ولو مفرقة غير متتابعة ولو مفرقة، مع التوبة الصادقة إلى الله مع التوبة النصوح والندم على ما مضى منك والعزم ألا تعودي في هذا الشيء ومع إطعام مسكين عن كل يوم نصف صاع عن كل يوم تجمعيها وتعطيها بعض الفقراء، فقير أو فقيرين أو أكثر، مع التوبة الصادقة والندم وعدم العود. نعم. المقدم: جزاكم الله خيرًا، إذًا عليها مع القضاء كفارة؟ الشيخ: نعم إطعام مسكين عن كل يوم. المقدم: بارك الله فيكم وجزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9540/حكم-من-افطرت-اياما-في-عدة-رمضانات-لعذر-ولم-تقضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37817.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11367,"question":"سؤالها الثاني تقول: بأن والدتي عندما توفت كان عليها قضاء لصيام شهر رمضان ولا نعلم كم عدد هذه الأيام لكثرة إفطارها بسبب مرض الربو وكانت تنوي القضاء ولكنها ماتت، ماذا يلزمنا سماحة الشيخ؟","title":"كيفية الصيام عن مات ولا يُعلم عدد الأيام التي أفطرها","answer":"الجواب:  يشرع لكم الصيام عنها، يشرع لكم الصيام عنها حسب الظن، تجتهدون وتصومون ما يغلب على الظن أنها أفطرته من رمضان وأنتم مأجورون، يقول النبي ﷺ: من مات وعليه صيام صام عنه وليه يعني: قريبه. فالأفضل لكم أن تصوموا عنها ما تيسر أنت وأخواتك أو واحدة منكن تصوم عنها حسب الظن، إذا ظننتم أنها عشرة أيام صوموا عشرة، ظننتم أنها خمسة عشر صوموا خمسة عشر، وهكذا بالظن ويكفي هذا، وإن تصدقتم عنها عن كل يوم طعام مسكين كفى، لكن صومكم عنها أفضل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9549/كيفية-الصيام-عن-مات-ولا-يعلم-عدد-الايام-التي-افطرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29310.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11404,"question":"تقول: ذهبت مني تقريبًا ستون يومًا صيامًا من خلال وضع الحمل أربعة أطفال، وإنني جسديًا غير متمكنة، وغير قادرة على الصيام، فارشدوني ماذا أعمل؟ جزاكم الله خيرًًا.","title":"حكم من أفطرت بسبب الحمل ولم تستطع القضاء","answer":"الجواب:  إذا كنت أفطرت في الحمل هذا ستين يومًا؛ فعليك القضاء، وإذا كنت مريضة؛ حتى تشفي -إن شاء الله- أما إن كنت قد عجزت، وعجزت عن الصيام لأجل كبر سنك؛ فعليك الإطعام عن كل يوم، إطعام مسكين نصف صاع عن كل يوم تجمعينه وتعطيه لبعض الفقراء. أما إذا كنت تستطيعين الصوم؛ فعليك الصوم، عليك أن تقضي ولو مفرقاً غير متتابع، وعليك مع ذلك إطعام مسكين عن التأخير، إذا قد أخرت، وأنت قادرة؛ عليك إطعام مسكين بعدد الأيام نصف صاع عن كل يوم، يجمع ويعطاه بعض الفقراء، ولا يجوز التساهل في هذا الأمر، هذه أمور عظيمة، فريضة صوم رمضان ركن في الإسلام، فالواجب العناية بهذا الأمر، إن كنت قادرة؛ فبادري بالصوم، وإن كنت عاجزة؛ يؤجل حتى تشفي من مرضك، الله يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، أما إذا كان تساهلًا؛ فعليك التوبة إلى الله، والندم، والإقلاع، والبدار بالصوم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9583/حكم-من-افطرت-بسبب-الحمل-ولم-تستطع-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38004.mp3","categories":["قضاء الصيام","الأعذار المبيحة للفطر"]},{"id":11446,"question":"بعد هذا رسالة بعث بها المستمع محمد أحمد سيد أحمد سوداني، يقول: لقد حل علي شهر رمضان، وصمت منه اثنين وعشرين يومًا، وأفطرت الأيام الباقية، وذلك لسخونة الجو، وللعمل الشاق، فكيف أقضي ما فاتني؟ أفيدوني أفادكم الله.","title":"حكم من أفطر أياماً من رمضان لمشقة العمل وسخونة الجو","answer":"الجواب:  عليك التوبة والاستغفار، وعليك القضاء، سواءً جمعت، أو فرقت، الأيام الباقية عليك أن تقضيها مجتمعة، أو مفرقة، لا بأس، وأما العمل وسخونة الجو لا يبيح لك الإفطار، تستريح وتصوم، تستريح من العمل، وتصوم، والحمد لله، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا، الذين يفتون يا سماحة الشيخ بأن العمل الشاق، أو أن سخونة الجو تبيح الإفطار.  الشيخ: ليس بعذر، لا، ليس بعذر، كل هذه لها علاج، يجلس في المحل الذي يرى أنه مناسب، ويستريح، وبقية المدة تسد على بقية الأيام هذه، الحمد لله لا يتعلق بالعمل، نعم، العمل يستريح منه، أو يؤجل، أو يستقيل، أو يكون في وقت خاص قليل لا يضره، نعم. المقدم: نعم، أو ينقله إلى الليل؟ الشيخ: أو ينقله إلى الليل كله طيب، كله طيب. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9627/حكم-من-افطر-اياما-من-رمضان-لمشقة-العمل-وسخونة-الجو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38103.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11467,"question":"رسالة بعث بها المستمع ... حاشي محمد من الطائف يقول: سماحة الشيخ! إذا كان الشخص سوف يسافر في التاسعة صباحًا في رمضان، فهل يجوز أن يفطر ذلك اليوم من الصباح الباكر؟ وجهونا جزاكم الله خيرًا.","title":"حكم الفطر في رمضان لمن عزم على السفر","answer":"الجواب:  ثبت عن أنس : أنه كان عزم على السفر، واستعد للسفر، ولبس ثياب السفر، فأكل قبل أن يسافر، فسأله بعض أصحابه هل هذا سنة؟ فقال: نعم سنة، وجاء عن أبي بصرة الغفاري نحو ذلك، فلا حرج في ذلك، وإن صبر حتى يخرج؛ فهو أحوط، نعم، وإن تهون عن السفر؛ لزمه الإتمام، وقضاء اليوم، إن هون؛ لزمه الإتمام، عليه أن يتم الصيام، ويقضي اليوم الذي أفطر فيه، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9648/حكم-الفطر-في-رمضان-لمن-عزم-على-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38122.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":11468,"question":"يسأل أيضًا ويقول: إذا سافر الشخص في الليل وسوف يصل إلى مكان إقامته بعد السحور، فهل يمسك، ويبقى صائمًا؟ أم كيف توجهونه؟","title":"حكم إمساك المسافر إذا كان وصوله لمكان إقامته بعد السحور","answer":"الجواب:  هو بالخيار إن شاء صام، وإن شاء أفطر، إذا كان يمر عليه بعض اليوم وهو صائم في سفره؛ فهو مخير، إن شاء نوى الإفطار، وإن شاء صام، فالصوم في السفر جائز، وتركه جائز، الحمد لله، نعم. المقدم: الحمد لله، ما هو الأفضل سماحة الشيخ؟ الشيخ: الأفضل عدم الصوم، عدمه إلا إذا كان يصل البلد الفجر؛ فالأفضل نية الصوم؛ لأنه ما عنده شيء من الوقت للسفر إلا قليل، لكن قد يتأخر إذا نوى الفطر؛ لأنه قد يتأخر في السفر، قد يعرض عارض، لا يضر، لكن الأفضل له في مثل هذا الحال إذا كان في أول النهار يصل البلد، أو سافر في أثناء النهار، ويصل العصر؛ فالأفضل له البقاء على الصوم؛ لأنه حينئذ إفطاره يكلفه القضاء، والمدة قليلة، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.  إذا بقي المسافر في مدينة ما لمدة أربعة أيام فأقل، فهل له أن يفطر؟ جزاكم الله خيرًا.  الشيخ: نعم، ما دام المدة أربعة أيام فأقل؛ له أن يفطر، وله أن يصوم، أما إن عزم على أكثر من أربعة أيام؛ فإنه يلزمه الصوم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9649/حكم-امساك-المسافر-اذا-كان-وصوله-لمكان-اقامته-بعد-السحور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38123.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":11478,"question":"من منطقة عشيرة إحدى الأخوات المستمعات تقول، الرمز (س. ح. ف) تسأل وتقول: إنني مريضة قبل عشرين عامًا، وأفطرت بعض أيام من شهر رمضان، وأنا لا أدري الآن كم عدد تلك الأيام، وصمت الآن عشرة أيام، ولا أدري أهي أكثر، أم أقل، فبماذا توجهونني الآن؟ جزاكم الله خيرًا.","title":"حكم من أفطر أياماً من رمضان لمرض ونسي عدد الأيام","answer":"الجواب:  عليك أن تصومي ما يغلب على ظنك حتى تكملي، إذا كان يغلب على ظنك أنها خمسة عشر؛ كملي بخمسة أيام، وهكذا، تحري بغلبة الظن، ويكفي، والحمد لله، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا، تقول: إنها صامت الآن عشرة، هل تنصحونها بشيء آخر سماحة الشيخ؟ الشيخ: نعم تنظر، تتأمل، فإن ذكرت أنها خمسة عشر؛ تكمل ثلاثة عشر؛ تكمل سبعة عشر، وهكذا، بغالب الظن. المقدم: وإن اعتقدت أنها عشرة فقط، فتكتفي؟ الشيخ: فقد انتهت، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9666/حكم-من-افطر-اياما-من-رمضان-لمرض-ونسي-عدد-الايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38212.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11494,"question":"يقول أخونا: قبل سنوات كنت خارج المملكة للعلاج، فصادفني شهر رمضان، فلم أصمه جهلًا مني، ثم عاودني المرض، وبعد شهر من إجراء العملية هلَّ شهر رمضان، فلم أستطع سوى صيام اثني عشر يومًا، وشعرت بالتعب، فتوقفت، وفي السنة التي بعدها لم أصم سوى ثلاثة وعشرين يومًا، وتوقفت بسبب المرض، فبماذا تنصحونني وحالي ما ذكرت؟ جزاكم الله خيرًا.","title":"حكم من يشق عليه الصيام لمرض يعاوده","answer":"الجواب:  ننصحك بأن تقضي الأيام التي أفطرتها على مهلك مفرقة، حتى لا تشق على نفسك، تقضي الأيام الأولى والثانية والثالثة، الكل تقضيها بهدوء، تصوم وتفطر حتى تكمل من دون أن تشق على نفسك بالمتابعة، تقضيها ولو مفرقة وتستغفر الله، والحمد لله، أنت على خير، ومعذور -إن شاء الله- ما دمت عاجزًا؛ تصم طاقتك، وإذا شق عليك؛ تفطر، ثم تقضي -والحمد لله- الله يقول -جل وعلا-: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، تصوم مع الناس، وإذا أحسست بالمشقة؛ أفطرت، ثم تقضي بعد ذلك، وهكذا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9675/حكم-من-يشق-عليه-الصيام-لمرض-يعاوده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38308.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":11538,"question":"يسأل أخونا ويقول: شاب مراهق أفطر ثلاثة أيام من رمضان؛ لأنه بذل مجهودًا عضليًا كبيرًا، ولم يستطع أن يكمل صيامه لرغبته الشديدة في الماء، فما هو الحل؟ هل يصوم عن كل يوم ستين يومًا متتالية، أم ماذا يفعل؟ مع العلم بأنه محافظ الآن على صيام رمضان، وصيام الإثنين والخميس جزاكم الله خيرًا.","title":"كيفية قضاء من أفطر من رمضان بسبب شدة العطش","answer":"الجواب:  إذا كان أفطر؛ لأنه لم يستطع إكمال الصوم بسبب شدة الظمأ، بسبب الإرهاق الذي أصابه، وخاف على نفسه الموت، أو مرض شديد، فهذا له عذر، وليس عليه إلا أن يقضي يومًا بدل اليوم، يعني: ثلاثة أيام بدل ثلاثة أيام فقط لا زيادة، إذا كان فطره بالماء. أما إذا كان فطره بالجماع؛ فهذا شيء آخر، لكن إذا كان فطره بالماء؛ فعليه قضاء اليوم فقط، والحمد لله. أما إذا كان تساهل وإلا ما هناك ضرورة؛ فعليه التوبة مع القضاء، قضاء يوم فقط، عن كل يوم يوم، ثلاثة ثلاثة، مع التوبة إلى الله، أما إن كان الأمر خطيرًا، يعني أصابه شدة عظيمة، وخاف من مرض شديد، أو من موت؛ فهذا عذر، الله يقول -جل وعلا-: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119]. نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ قد يفطر بعض الناس لأمر ما، كهذا الأمر الذي حل بأخينا، فإذا ما أفطر لا يستمر في صيامه بعد ذلك، بل يستمر مفطرًا، فيأكل ويشرب ويستبيح المأكولات؟ الجواب: لا يجوز له، يفطر بقدر الحاجة، يشرب، ثم يمسك إذا كان من أجل الظمأ، يأكل ما يسد رمقه إذا كان الخطر من أجل الجوع، ثم يمسك حتى غروب الشمس، ما يستمر في الفطر، إنما أكل وشرب الضرورة، ثم يستمر، وهكذا لو أن الإنسان أراد إنقاذ إنسان من غرق، أو من عدو، ولم يستطع إلا بالفطر؛ أفطر، وأنقذ أخاه، ثم أمسك، أمسك إلى غروب الشمس، وقضى اليوم فقط، يقضي اليوم فقط؛ لأنه أفطر للضرورة نعم؛ لأن إنقاذ المسلم واجب، إنقاذ أخيه المعصوم واجب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9721/كيفية-قضاء-من-افطر-من-رمضان-بسبب-شدة-العطش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_295/29504.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":11614,"question":"مستمع بعث يسأل ويقول: أصيب أبي بمرض في شهر رمضان، وحينئذ لم يصم تلك الأيام التي مرض فيها حتى انقضى الشهر، هل يجب علينا أن نقضي عنه؛ لأن مرضه لا يرجى برؤه؟","title":"حكم من لا يستطيع صيام رمضان لمرض لا يرجى برؤه","answer":"الجواب:  الواجب الإطعام، يطعم عنه عن كل يوم مسكينًا، إذا كان المرض لا يرجى برؤه؛ فهو كالميت، يطعم عنه فقط يجزئ، وكالشيخ الهرم الكبير السن، والعجوز الكبيرة، الذي لا يستطيع والتي لا تستطيع؛ يطعم عن كل يوم مسكينًا نصف صاع تمر، أو رز، أو غيره من قوت البلد، كيلو ونصف تقريبًا، يجمع الجميع في آخر الشهر ويعطاه بعض الفقراء، ولو فقيرًا واحدًا، ليس بلازم أن كل يوم يخرج عنك بيومه، بل إذا جمع في أول الشهر، أو في آخره، أو في وسطه، وأعطي بعض الفقراء؛ يكفي هذا، والحمد لله. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9797/حكم-من-لا-يستطيع-صيام-رمضان-لمرض-لا-يرجى-بروه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38808.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":11759,"question":"يقول: أنا راعي إبل، وضاعت مني، ورحت على أثرها، وكنت صائمًا لرمضان، ولم أجد شربًا ولا أكلًا في وقت الإفطار، وأصبحت في اليوم الثاني ونويت الإفطار، وفعلًا وجدت الأكل والشرب حوالي العاشرة صباحًا، ولم أمسك باقي اليوم، ماذا علي؟ أكرمكم الله، وسدد خطاكم.","title":"حكم الفطر لمن خاف الضرر وما يجب عليه","answer":"الجواب:  لا حرج عليك إذا كنت مضطرًّا في الأكل والشرب خوفًا من الموت، أو من المرض؛ فلا بأس، لكن الواجب عليك الإمساك؛ لأنه لما يسر الله لك الأكل والشرب أن تمسك؛ فعليك التوبة إلى الله من عدم الإمساك فقط والقضاء، قضاء اليوم الذي أفطرته. أما كونك أفطرت لأجل الضرورة، كونك بقيت يومك وليلتك لم تجد أكلًا، ولا شربًا، فإذا كنت مضطرًّا لذلك؛ فلا حرج في ذلك، والحمد لله، إنما الواجب عليك لما أكلت وشربت أن تمسك بقية نهارك، وأنت لم تفعل جهلًا منك؛ فعليك قضاء ذلك اليوم مع التوبة، والاستغفار. نعم. المقدم: سماحة الشيخ! من بقي يومًا وليلة حتى العاشرة صباحًا بدون أكل، ولا شرب، هل هذا عذر، أو لا؟ الشيخ: إذا كان يشق عليه.. الناس يختلفون، إذا كان يشق عليه؛ فهو عذر له، وإن كان ما في مشقة؛ يكمل. المقدم: مثل أخينا في الصحراء، ويبحث عن رعيته. الشيخ: الظاهر أنه يشق عليه كثير ظاهر عذره ظاهر. المقدم: بارك الله فيكم، أحسن الله إليكم. الشيخ: عذره طاهر. المقدم: إذًا يرى سماحتكم أنه معذور؟ الشيخ: نعم نعم. المقدم: وليس عليه القضاء. الشيخ: عذره ظاهر لا، قضاء اليوم يقضي اليوم الثاني الذي أكل فيه، أما الأكل ما فيه قضاء الأكل ما أكل ولا شرب. نعم. المقدم: الله المستعان، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9943/حكم-الفطر-لمن-خاف-الضرر-وما-يجب-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39405.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":11790,"question":"من الجمهورية اليمنية رسالة بعث بها مستمع من هناك، يقول حسين عبده أحمد المنصوري من رداع، أخونا يقول: تعالجت لمدة سنتين من عام 1402 وذلك لأني أعاني من مرض مزمن، ولا زال بي حتى الآن، وإذا جاء رمضان؛ أحتار كيف أصوم؛ لأنه يشق علي مشقة كبيرة، هل أطعم؟ أم كيف توجهونني؟ جزاكم الله خيرًا، ونفع بكم الإسلام والمسلمين في مشارق الأرض ومغاربها؟","title":"حكم من عجز عن الصيام لمرض مزمن","answer":"الجواب:  عليك أن تقضي إذا شفاك الله؛ لقول الله سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، لكن إذا قرر الطبيب الثقة، أو أكثر من طبيب أن هذا المرض لا يرجى برؤه، ويشق عليك الصوم؛ فإنك تطعم عن كل يوم مسكينًا، نصف صاع من التمر، أو الأرز، أو الحنطة، أو غيرها من قوت البلد تجمعها، وتعطيها بعض الفقراء، في أول الشهر، أو في آخره، أو في وسطه، والحمد لله، أما مادمت ترجو العافية؛ فإنه يلزمك القضاء إذا شفاك الله. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9974/حكم-من-عجز-عن-الصيام-لمرض-مزمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_422/42207.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":11892,"question":"رسالة من إحدى الأخوات المستمعات تقول أم عبدالعزيز وعلي: لها جمع من الأسئلة تقول في أحدها: توفي جدي لأبي، وعليه صيام من رمضان، وقمت أنا وأبي بالصيام عنه، أنا ثمان وأبي ثمان، فهل يصح ذلك؟ جزاكم الله خيرًا.","title":"حكم صيام المرأة عن جدها الذي مات وعليه صوم","answer":"الجواب:  مشكور جزاكم الله خير طيب، يقول النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه يعني: قريبه، فإذا قضيت أنت والأب ما على الميت؛ جزاكم الله خيرًا هذا عمل مشكور، ومأجور، وينفع الميت.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10076/حكم-صيام-المراة-عن-جدها-الذي-مات-وعليه-صوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42513.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12020,"question":"أحد الإخوة المستمعين بعث برسالة وضمنها أربعة أسئلة: يقول في أحدها: بعض النساء يفطرن في رمضان لعذر شرعي، فهل لهن الحق في الأكل والشرب جهارًا، أم يأكلن سرًا، ولو أدى ذلك إلى أكثر من ثلاث وجبات؟ جزاكم الله خيرًا.","title":"صفة الفطر في نهار رمضان للمعذور شرعًا","answer":"الجواب:  من أفطر في رمضان للعذر؛ فإنه يفطر سرًا كالمسافر الذي لا يعرف أنه مسافر، والمرأة التي لا يعرف أنها حائض، فيكون أكلها سرًا، وشربها سرًا حتى لا تتهم بأنها متساهلة، وحتى لا يتهم الرجل بأنه متساهل بأمر الله. أما إذا كان بين قوم يعرفون حاله أنه مسافر، وكانت بين جماعة من النساء يعرفون أنها حائض؛ فلا حرج عليها أن تأكل عندهم وتفطر؛ لأنه يعرفون حالها، وهكذا المسافر بين قوم يعرفون حاله، أما أن يأكل عند الناس، وهم لا يعرفون حاله؛ فهذا لا ينبغي له حينئذ، بل الواجب عليه أن يختفي بذلك حتى لا يتهم بالشر، وهكذا المرأة التي لا يعرف من حولها أنها حائض، فإنها لا تأكل عندهم ولا تشرب؛ لأن هذا يسبب تهمتها بأنها متساهلة بأمر الله، وأنها لا تصوم رمضان، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10205/صفة-الفطر-في-نهار-رمضان-للمعذور-شرعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43211.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":12130,"question":"إحدى الأخوات المستمعات تقول أم حسن تقول: إنها كانت تضع مواليدها في رمضان، ولم تقض، ولم تدر عدد ما فاتها من الأيام، فكيف تتصرف الآن؟ جزاكم الله خيرًا.","title":"حكم من أفطرت في رمضان لعذر ولم تدر عدد الأيام","answer":"الجواب:  تعمل بغالب ظنها، عليها أن تعمل بغالب ظنها، عليك يا أم حسن أن تعملي بغالب الظن في قضاء الأيام التي أفطرت من رمضان، اعملي بغالب الظن، والحمد لله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] إذا غلب على ظنك أنك أفطرت عشرة أيام، خمسة عشر يومًا؛ فاقضيها من كل سنة، حتى تكملي، سواءً قضيتيها متتابعة، أو مفرقة؛ لا بأس، اعملي بالظن، ويكفيك هذا، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10315/حكم-من-افطرت-في-رمضان-لعذر-ولم-تدر-عدد-الايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43815.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12205,"question":"من ليبيا رسالة وصلت بتوقيع إحدى الأخوات المستمعات التي رمزت إلى اسمها بالحروف. (أ. أ. ع) تقول: لي أخت أكبر مني سنًا تعاني من مرض في أحد قدميها، مما يجعلها مستمرة في العلاج وبدون انقطاع، حتى إنها إذا انقطعت عن العلاج؛ رجع المرض إليها، وأصبحت لا تصوم من شهر رمضان، وأحيانًا تصوم ثلاثة، أو أربعة أيام، وعند انتهاء رمضان تنوي أن تقضي الأيام التي أفطرتها، ولكن كما قلت: علاجها مستمر، إذا انقطعت عنه؛ رجع المرض، أي ليس هنالك فرصة لكي تقضي الأيام حتى يأتي شهر رمضان آخر، ولم تقض الأيام التي أفطرتها، ما الحكم والحال ما ذكر؟ جزاكم الله خيرًا.","title":"حكم صيام رمضان لمن به مرض لا يرجى برؤه","answer":"الجواب:  إذا قرر الأطباء ولو طبيبًا واحدًا ثقة أن هذا المرض يستمر، وأنه لا يرجى برؤه؛ فإنها تطعم عن كل يوم مسكينًا، كالشيخ الكبير العاجز، والمرأة العجوز الكبيرة العاجزين عن الصيام يطعمان عن كل يوم مسكينًا نص صاع، يعني: كيلو ونص تقريبًا من التمر أو الأرز من قوت البلد، ويكفي ذلك، فإذا كان هذا المرض معها مستمرًا، ولم يظهر رجا أنه يشفى بحسب قول الأطباء؛ فإنها تطعم عن كل يوم مسكينًا، والحمد لله، وليس عليها صوم. أما إذا كان يرجى شفاؤه، والعلاج قد ينفع الله به، والأطباء يقولون: إنه يمكن أن تشفى منه -إن شاء الله- فإنها يبقى في ذمتها الصوم حتى تقضي -إن شاء الله- ولو طالت المدة، ولو طالت المدة تقضي بعد حين، إن شاء الله. لكن إذا قرر الطبيب المختص، أو طبيبان، أو أكثر من ذلك أن هذا المرض لا يرجى برؤه، وأن التجربة تدل على أنه يستمر، ويضرها الصوم معه؛ فإنها تفطر، والحمد لله، وتطعم عن كل يوم مسكينًا، كالعجوز الكبيرة العاجزة عن الصوم، والشيخ الكبير العاجز عن الصوم، يطعم عن كل يوم مسكينًا، ولا يصوم، وليس عليه القضاء. والواجب نصف الصاع من قوت البلد من تمر أو رز أو بر أو شعير أو ذرة، مقداره بالكيلو كيلو ونصف تقريبًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10391/حكم-صيام-رمضان-لمن-به-مرض-لا-يرجى-بروه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_444/44412.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":12305,"question":"علي قضاء أربعة رمضانات بعيدة جدًا، ولا أذكر عدد الأيام التي أفطرت فيها، علمًا بأنني أصبحت أقضي ما علي من صيام أولًا بأول، لكن تلك الأيام الماضية يقلقني أنني لم أقضها، ولم أدر ما مقدارها، وهي أربعة رمضانات كما قلت، فكيف تنصحونني؟","title":"حكم من أفطرت في رمضان ولا تعلم عدد الأيام","answer":"الجواب:  ننصحك بأن تقضي هذه الأيام التي عليك بحسب الظن، يجب عليك أن تقضي ما أفطرت فيه بحسب الظن، وتحتاطي، فإذا كنت تظنين من كل سنة سبعة أيام، أو ثمانية أيام؛ اجعليها ثمانية، وإذا كنت تشكين هل ثمانية، أو تسعة؛ اجعليها تسعة، اعملي بالاحتياط، وصوميها كلها، وأطعمي عن كل يوم مسكينًا أيضًا زيادة؛ لتفريطك وتأخيرك للصيام، وهو نصف صاع، عن كل يوم كيلو ونصف تقريبًا من تمر، أو حنطة، أو أرز، هكذا أفتى جمع من الصحابة -رضي الله عنهم وأرضاهم- في حق من أخر الصيام إلى رمضان آخر أنه يطعم مع القضاء، إذا لم يكن له عذر، وأنت أخرت بلا عذر سنوات. فالواجب عليك التوبة إلى الله، والقضاء مع إطعام مسكين عن كل يوم في الأيام الماضية كلها، والله يعينك ويهديك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10505/حكم-من-افطرت-في-رمضان-ولا-تعلم-عدد-الايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45311.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12349,"question":"هل يجوز قضاء أيام الإفطار من شهر رمضان في العشرة الأيام الأخيرة من شعبان، أو قبلها بالنسبة للمرأة؟","title":"حكم تأخير قضاء رمضان إلى شعبان","answer":"الجواب:  لا حرج بالنسبة للمرأة والرجل جميعًا، يجوز تأخير القضاء إلى شعبان، كانت عائشة تؤخر إلى شعبان -رضي الله عنها-.... والله -جل وعلا- قال: فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:184] ولم يقل في كذا، ولا في كذا، ولم يقل يجب المبادرة، فدل هذا على التوسعة، فإذا قضى أيام رمضان في شوال، في ذي القعدة، في ذي الحجة، في محرم، في صفر إلى آخره؛ يصح، لا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10551/حكم-تاخير-قضاء-رمضان-الى-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39910.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12370,"question":"إحدى الأخوات المستمعات تقول: (ص. ع. م) مقيمة في الرياض، وهي مصرية تسأل وتقول: أفطرت شهر رمضان كاملًا نظرًا لأنني وضعت حملي الأول، وفي السنة الثانية لنفس العذر أفطرت نصف شهر رمضان، وإلى الآن لم أستطع قضاء ما علي من صيام؛ لأن حالتي الصحية لا تسمح، ما هو مقدار ما علي من إطعام للمساكين؟ أفيدوني جزاكم الله خيرًا.","title":"حكم تأخير قضاء رمضان للحامل والمرضع","answer":"الجواب:  عليك القضاء إذا استطعت بدون إطعام، ما دمت تركت القضاء من أجل العجز؛ فلا بأس أن تقضي إذا وجدت الاستطاعة -عافاك الله- واستطعت تقضين، والحمد لله، وليس عليك إطعام، إلا إذا كنت تساهلت، وتركت القضاء، وأنت تستطيعين، فعليك مع القضاء إطعام مسكين، عن كل يوم نصف صاع، كيلو ونصف عن كل يوم ، تجمع ويعطاها بعض الفقراء، إذا كنت تساهلت، أما إذا كنت أخرت لأجل العجز؛ فليس عليك إلا القضاء إذا استطعت، ولو تأخر سنتين ثلاثًا؛ لا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10580/حكم-تاخير-قضاء-رمضان-للحامل-والمرضع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40018.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12406,"question":"رسالة وصلت إلى البرنامج من الأخ المستمع نور الدين آدم من الجمهورية العربية السورية محافظة الحسكة، قرية هلالية، يقول في رسالته: أنا شاب في السابعة عشرة من العمر، أصلي وأقرأ القرآن، وأبتعد عما هو شر وآثام، ولكن مشكلتي عندما يحين وقت رمضان لا أصوم الشهر؛ وذلك لأنني أعمل أعمالًا شاقة، ولا سيما في أيام الصيف، فهل يجوز لي أن أصوم في أوقات أخرى؟ أو ماذا علي أن أفعل؟أرشدوني جزاكم الله خيرًا.","title":"حكم من ترك الصيام في رمضان بحجة الأعمال الشاقة","answer":"الجواب:  عليك القضاء مع التوبة، تقضي الصيام، وتتوب إلى الله -جل وعلا- وفي المستقبل تصوم مع الناس، وتترك العمل الذي يشق عليك، تعمل أعمالًا لا تشق عليك مع الصوم، فإذا كنت لا تستطيع إلا بترك العمل؛ فاترك العمل، وادخر لرمضان ما يكفيك في رمضان من أعمالك التي في شعبان وقبله، ادخر من نقودك وأجورك التي تحصل لك في شعبان ورجب، وما قبلهما، ادخر منها ما يعينك على صيام رمضان، أو رتب نفسك على عمل لا يشق عليك، وتمكن معه من الصيام، أما التساهل، والحرص على الدنيا، والأعمال الشاقة، وتترك الصوم؛ هذا لا يجوز لك.  فاتق الله ما استطعت، اعمل عملًا قليلًا إذا كنت محتاجًا إليه ليس فيه ما يمنعك من الصوم، وإلا فادخر من أعمالك التي قبل رمضان، ادخر من أجورها ما يعينك على الفراغ للصيام مع المسلمين، نسأل الله لنا ولك الهداية، والتوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا! سماحة الشيخ الذين يفتون العمال، والذين يعملون أعمالًا شاقة بجواز الفطر في رمضان، هل هم على حق؟ الشيخ: لا نعلم لهذا أصلًا أقول ليس له أصل، الواجب أنهم يعملون بقدر الطاقة، وإذا كان لابد من عمل؛ فليؤجلوا العمل إلى بعد رمضان، ويدخروا من أعمالهم السابقة ما يعينهم على صيام رمضان، فالتساهل في هذا شره عظيم، وعاقبته وخيمة.  فالواجب عدم التساهل في هذا الأمر، ولكن إذا تيسر له عمل يستطيع معه الصوم؛ فلا حرج في العمل في رمضان ويصوم، أما إذا كان لابد من الفطر؛ فليترك العمل الذي يلجئه إلى الفطر، وليستعن بالله على صومه بما عنده من المال السابق. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/10611/حكم-من-ترك-الصيام-في-رمضان-بحجة-الاعمال-الشاقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_455/45511.mp3","categories":["قضاء الصيام","الأعذار المبيحة للفطر"]},{"id":12451,"question":"المستمع أحمد بن محمد بن سعيد العبري من سلطنة عمان بعث يسأل ويقول: لدي ابنة أصيبت بمرض -أجاركم الله منه- وهو الفشل الكلوي، وقد أصيبت به وهي في التاسعة من عمرها، وقد قمنا بتسفيرها إلى الخارج للعلاج، وقامت أيضًا بزراعة الكلية، وهذا منذ سنتين والاستفسار الآن هو أنها بلغت من العمر الآن ستة عشر عامًا، وفي هذا السن يجب على المرء الصيام، وقد منعها الأطباء من الصيام، فما الحكم الشرعي في هذا؟ جزاكم الله خيرًا.","title":"حكم من منعه الأطباء من الصيام بسبب المرض","answer":"الجواب:  عليها أن تصوم بعد الإذن لها في الصوم، بعدما يكون الصوم لا يضرها تصوم، أما إذا قرر الأطباء أنه يضرها الصوم دائمًا، فإنها تطعم عن كل يوم مسكينًا، ولا صوم عليها كالمريض الذي لا يرجى برؤه، وكالهرم الذي لا يستطيع الصوم، والعجوز التي لا تستطيع الصوم، كل منهما يطعم عن كل يوم مسكينًا، إذا كان قادرًا نصف صاع يجمع ذلك ويعطيه بعض الفقراء في أول الشهر، أو في آخره، أو في وسطه، والحمد لله. المقدم: بارك الله فيكم، إذًا إذا قال الأطباء: لا تصم؛ فعليها أن تمتنع عن الصوم؟ الشيخ: نعم، لكن إذا كان محددًا؛ تمتنع، ثم تقضي، أما إذا كان لا، دائمًا؛ فإنها تطعم عن كل يوم مسكينًا، كل شهر، كلما جاء رمضان. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/10651/حكم-من-منعه-الاطباء-من-الصيام-بسبب-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40316.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":12502,"question":"يقول في سؤال آخر: والدة زوجتي كانت مريضة بمرض أقعدها في الفراش، وفي شهر رمضان أجبرها الأطباء على الإفطار، ولم تصم من ذلك الشهر إلا خمسة أيام فقط، واستمر بها المرض حتى توفاها الله في نهاية ذلك العام، هل على أولادها أن يصوموا ما أفطرت بسبب المرض؟ وجهونا جزاكم الله خيرًا.","title":"حكم من أفطر بسبب المرض واستمر مرضه حتى مات","answer":"الجواب:  إذا كانت ماتت في مرضها؛ فليس على أولادها، ولا غيرهم قضاء، الحمد لله، نعم، معفو عنها؛ لأن الله يقول -جل وعلا-: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] وهي توفيت في مرضها؛ فلا شيء عليها، ولا يقضى عنها، والحمد لله، غفر الله لنا ولها. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10716/حكم-من-افطر-بسبب-المرض-واستمر-مرضه-حتى-مات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40710.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":12549,"question":"رسالة وصلت إلى البرنامج من جمهورية مصر العربية سوهاج أولاد طوق، وباعثة الرسالة إحدى الأخوات من هناك، تقول أم ممدوح: إنه علي أيام صيام من رمضان، وكنت وما زلت مريضة، ولم أستطع الصيام، وسبق أن أطعمت عن كل يوم مسكينًا، وهذا لعدم استطاعتي الصيام؛ لأنني أشكو من مرض في المعدة، هل يكفي الإطعام، أم توجهونني إلى شيء آخر؟ أفيدوني جزاكم الله خيرًا.","title":"حكم من أفطر في رمضان لمرض لا يرجى برؤه","answer":"الجواب:  إذا كان المرض يرجى برؤه؛ فإنه لا يكفي الإطعام، وعليك إذا عافاك الله أن تصومي، أما إذا قرر الأطباء، يعني الطبيب المختص، أو أكثر أن هذا المرض لا يرجى برؤه، وأنه معروف من جهة العادة أن مثل هذا يستمر، فالإطعام كافٍ، والحمد لله، مثلما يطعم الشيخ الكبير، والعجوز الكبيرة اللذان لا يستطيعان الصوم؛ فإنهما يطعمان عن كل يوم نصف صاع، ويكفيهما، فهكذا المريض الذي لا يرجى برؤه حكمه حكم الشيخ الكبير، والعجوز الكبيرة في إجزاء الإطعام عن الصيام. نعم. المقدم: جزاكم الله خيرًا، الإطعام بالفلوس تسأل عنها. الشيخ: لا ما يكفي لا، إطعام بالطعام عن كل يوم نصف صاع، يعني كيلو ونص عن كل يوم تقريبًا من التمر، أو من الحنطة، أو من الأرز من قوت البلد. المقدم: لو أطعمت المساكين في مطعم؟ الجواب: كفى، نعم. المقدم: جزاكم الله خيرًا.  الشيخ: غدتهم، أو عشتهم .. كفى. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10763/حكم-من-افطر-في-رمضان-لمرض-لا-يرجى-بروه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_410/41008.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":12564,"question":"أنا آدم جمعة محمد أحمد سوداني الجنسية أبلغ من العمر ثمانًا وثلاثين سنة، قبل بضع سنوات أفطرت رمضان كله بأمر من الدكتور حيث كنت مريضًا، وبعدها أفطرت في رمضان آخر خمسة عشر يومًا لأسباب أخرى، ومر على هذه الأيام سنين، وما قضيتها، وصمت بعدها، وأريد أن أقضيها، فماذا أفعل؟ أفيدوني أثابكم الله.","title":"حكم تأخير قضاء صوم رمضان لعدة سنوات","answer":"الجواب:  عليك القضاء مع التوبة إلى الله -جل وعلا- عما حصل من التأخير، فعليك يا أخي أن تستغفر الله، وتتوب إليه، وتندم على ما فعلت، وعليك أن تقضي هذه الأيام، وأن تطعم مع ... عن كل يوم مسكينًا من قوت البلد، نصف صاع من قوت البلد، فالمعنى: عليك ثلاثة أمور: الأمر الأول: القضاء والمبادرة به. والأمر الثاني: إطعام مسكين عن كل يوم مع القدرة، فإن كنت فقيرًا عاجزًا؛ سقط عنك الإطعام، وبقي عليك الصيام. الأمر الثالث: التوبة إلى الله من هذا التأخير والاستغفار والندم، ومن تاب؛ تاب الله عليه، نسأل الله لنا ولك الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10772/حكم-تاخير-قضاء-صوم-رمضان-لعدة-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_411/41107.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12629,"question":"أم نواف من الرياض بعثت تقول: امرأة حامل يأتيها نزيف أثناء فترة الحمل في شهر رمضان، فهل يجب عليها الصوم، أو تفطر، ثم تقضي؟ أفيدونا، جزاكم الله خيرًا.","title":"حكم نزيف المرأة الحامل في نهار رمضان","answer":"الجواب:  الحامل لا تحيض في أصح قولي العلماء، فإذا كانت حاملًا، فالنزيف الذي معها يعتبر دمًا فاسدًا، تصلي وتصوم، وتتحفظ بالقطن ونحوه، وتتوضأ لوقت كل صلاة، ولا تقضي كالمستحاضة؛ لأن هذا النزيف دم فساد، هذا هو الصحيح، فإذا استمر معها؛ فإنها تتحفظ بالقطن ونحوه، وتتوضأ لوقت كل صلاة وتصلي، كما يصلي غيرها من الطاهرات، وإن شق عليها ذلك؛ جمعت، لا بأس أن تجمع بين المغرب والعشاء وبين الظهر والعصر كالمريضة؛ لأنه نوع مرض، وصومها صحيح، وصلاتها صحيحة؛ لكن لا تتوضأ إلا بعد دخول الوقت، كلما دخل الوقت؛ تتوضأ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10839/حكم-نزيف-المراة-الحامل-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41503.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":12649,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المواطنة (ط. م) من بغداد العراق، أختنا رسالتها مطولة بعض الشيء ملخص ما فيها كالتالي: تقول: على أثر الصيام تصاب بمرض الشقيقة، ونصحها الطبيب بالإفطار لئلا تصاب بالشلل، فماذا يجب عليها؟","title":"حكم الفطر في رمضان لمن يضرها الصيام","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فقد قال الله -جل وعلا- في محكم التنزيل: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فإذا كانت السائلة يضرها الصوم في شقيقتها، يعني: في رأسها ضررًا بينًا، فإنها تفطر، وتقضي إذا استطاعت بعد ذلك، فإذا قرر الأطباء أن هذا المرض يحصل بالصوم دائمًا، فإنها تطعم عن كل يوم مسكينًا، كالشيخ الكبير العاجز، والعجوز الكبيرة العاجزة.  أما إذا كان يزول فإنها تقضي عند السلامة إذا شفيت من هذا المرض، تقضي إما في أيام الشتاء، وإلا في أوقات أخرى ترى أنها تستطيع فيها القضاء بدون هذا المرض، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10859/حكم-الفطر-في-رمضان-لمن-يضرها-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45801.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":12701,"question":"يقول: لمرض أصابني لم أصم رمضان لعامين متتالين، ماذا علي أن أفعل؟","title":"حكم من أفطر رمضان في عامين لمرض","answer":"الجواب:  ما دمت أفطرت لعذر شرعي؛ فعليك القضاء، عليك أن تقضي ما أفطرته من العامين، وإذا كان التأخير إلى رمضان الثاني بعذر شرعي؛ فلا شيء عليك سوى الصيام تقضي، أما إذا كنت أخرت من غير عذر، بل تساهلًا منك؛ فعليك مع القضاء إطعام مسكين عن كل يوم، كما أفتى بذلك جمع من الصحابة، من أصحاب النبي ﷺ. أما إن قضيت في العام قبل رمضان؛ فإنك تقضي بدون إطعام، لكن إذا أخرت القضاء إلى رمضان الآخر؛ فعليك القضاء مع الإطعام نصف صاع عن كل يوم من التمر، أو الحنطة، أو الرز مع التوبة والاستغفار.  أما المعذور فلا شيء عليه، إذا أخر من أجل المرض؛ فلا شيء عليه سوى القضاء؛ لأن الله يقول: فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:184] فعليه القضاء فقط. لكن من تساهل، وأمكنه القضاء، ولم يقض حتى جاء رمضان؛ فعليه مع القضاء إطعام مسكين عن كل يوم، مع التوبة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10911/حكم-من-افطر-رمضان-في-عامين-لمرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45906.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12727,"question":"مستمع رمز إلى اسمه بالحروف (س. م. ح) من الرياض بعث برسالة، وضمنها سؤالًا طويلًا ملخصًا، سؤالًا يقول: من توفي وعليه صيام أيام أفطرها للسفر، هل يصوم عنه ورثته؟","title":"حكم من مات وعليه صوم أيام أفطرها في السفر","answer":"الجواب:  نعم، إذا كان فرط، إذا كان قدم، ولا صام؛ فالسنة أن يصوموا، أما إذا كان مات في السفر، أو مات من حين قدم، مثل المريض الذي مات في مرضه، أو من حين شفي، مات، ما أمكنه أن يصوم؛ فهو معذور. لكن إذا فرط المريض، أو المسافر بأن شفي المريض؛ قدم من السفر المسافر، ولكن تساهل، ما صام، ثم مات يشرع لأقاربهما أن يصوموا عنهما، لقول النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه وسأله جماعة هذا يقول: أمي ماتت وعليها صوم شهر، وهذا يقول: أبي مات وعليه صوم شهر، عليه صوم شهرين، فهل أصوم عنه؟ فيقول النبي ﷺ نعم. يجيبهم بنعم. فالسنة لهؤلاء أن يصوموا عن أقاربهم، ويحسنوا إليهم بذلك، إذا كان أقاربه قد فرطوا، يعني: تساهلوا، أما إذا كان مات في مرضه، أو مات في سفره، أو من حين شفي مات، أو من حين قدم مات ما أمكنه؛ فهو معذور. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10940/حكم-من-مات-وعليه-صوم-ايام-افطرها-في-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46015.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12841,"question":"سؤال طويل جدًا ملخصه سماحة الشيخ كما يلي: يقول: أفطرت في رمضان؛ لأني كنت أعمل عملًا شاقًا، وأسأل عن القضاء في أيام الجمع بالذات؟","title":"حكم الفطر في رمضان بسبب مشقة العمل والقضاء أيام الجمع","answer":"الجواب:  الواجب على المؤمن أن يستكمل الصوم في رمضان، وألا يفطر بسبب العمل، إذا كان عمله شاقًا لا يعمل، بل يترك العمل حتى يؤدي الفريضة، أو يعمل بعضه، يعمل بعض العمل، ويترك العمل الذي يسبب له الفطر: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ولو بالأجرة، يقول للمستأجر: هذا يوم من رمضان فيكون في أيام رمضان العمل أقل من أيام الفطر؛ حتى يجمع بين المصلحتين بين مصلحة الصوم، ومصلحة العمل، والله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] أما أنه يفطر بسبب العمل، لا، هذا منكر لا يجوز، وعليه القضاء إذا أفطر، والقضاء يكون في غير الجمعة أولى، يقضيه الخميس والجمعة جميعًا، لا يخص الجمعة هذا هو الأحوط؛ لأن الرسول ﷺ نهى عن تخصيصها بالصوم، قال ﷺ: لا يصومن أحدكم يوم الجمعة إلا أن يصوم يومًا قبله أو يومًا بعده وهذا في النفل بلا شك، ولكن عمومه قد يخشى منه دخول تخصيصه بالقضاء.  فالأحوط للمؤمن ألا يخصه، ولو صام في يوم الجمعة للقضاء؛ صح -إن شاء الله- لأنه لم يقصد .. التطوع به، وإنما قصد القضاء، لكن تركه أولى، كونه يصوم معه السبت، أو مع الجمعة الخميس في القضاء، أو في النافلة، هذا هو المشروع، ولا يخص يوم الجمعة بالنفل ولا بالقضاء، هذا هو الأحوط والأولى نعم. أما في النفل فلا يجوز، ما يجوز أن يخص الجمعة بالنفل أبدًا، لابد إذا أراد الصوم يصوم يومًا قبله، أو يومًا بعده، وأما في الفريضة قضاء الفريضة فالأحوط ألا يفعل، فلو فعل؛ صح -إن شاء الله- لأنه ما قصد تخصيص الجمعة بتطوع، إنما قصد أداء الفريضة التي عليه، لكن كونه يحتاط يصوم في غير الجمعة الخميس أو الإثنين، أو يضم مع الجمعة يومًا قبلها، أو يومًا بعدها؛ فهذا يكون أحوط؛ لقوله ﷺ: دع ما يريبك إلى ما لا يريبك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11055/حكم-الفطر-في-رمضان-بسبب-مشقة-العمل-والقضاء-ايام-الجمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46407.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":12844,"question":"المستمع (ع. ب. ي. أ) بعث برسالة يقول فيها: في الماضي قبل حوالي أربعين سنة تقريبًا كانت الأحوال المادية والاجتماعية سيئة، وأنا أبلغ من العمر الآن ستين سنة، وكان يأتي شهر رمضان، ولا أصوم لعدة أسباب منها: ضعف في الوازع الديني؛ لعدم علمي، ولجهلي في كل أمور الدين؛ ولأني كنت أرعى الغنم في الحر الشديد في الصحراء، فاضطررت للإفطار، استمر هذا الوضع إلى أن أفطرت أربعة شهور، أي: في أربع سنوات، فماذا علي؟ هل علي قضاء، أم أن لي توبة بحكم إقلاعي عن ذلك العمل، ولأنني أبشركم تفقهت، وهداني الله للإسلام، أم ما ذا علي؟ وما صفة القضاء إذا لزم، جزاكم الله خيرًا؟","title":"الواجب على من أفطر عدة رمضانات تساهلًا","answer":"الجواب:  الواجب عليك القضاء مع التوبة إلى الله، والندم، والعزم الصادق على ألا تعود في ذلك، وعليك القضاء للشهور الأربعة، ولا يلزمك التتابع، تقضيها ولو متفرقة، لا يلزم التتابع، تصوم وتفطر حتى تكملها -إن شاء الله- وعليك مع ذلك إطعام مسكينًا، عن كل يوم نصف صاع، كيلو ونصف عن كل يوم تمرًا، أو رزًا، أو حنطة، يعني: نصف صاع من قوت بلدك، والمقدار كيلو ونصف عن كل يوم، مع القدرة، فإن كنت فقيرًا لا تقدر؛ فليس عليك إلا الصوم فقط، تصومها وتستعين بالله -جل وعلا- مع التوبة إلى الله. وهذا هو الواجب على المسلم؛ لأن الله يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فإذا كان المريض والمسافر يقضي، فالمتساهل يقضي من باب أولى، مع التوبة إلى الله  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11058/الواجب-على-من-افطر-عدة-رمضانات-تساهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46410.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12910,"question":"تقول عن نفسها: أنا فتاة بلغت العادة من قبل اثني عشر عامًا، وكنت لا أقضي ما أفطره في رمضان، وقد علمت بالذنب، وتبت إلى الله تعالى، وقررت، بل عاهدت الله: بأن أصوم الشهر، وأقضي الأيام التي أفطرت، ما حكم ذلك؟ هل أقضي السنوات الماضية، أم ماذا أفعل؟ علمًا بأني لا أستطيع القضاء؛ لأن صحتي ضعيفة جدًا، وأيضًا لا أستطيع إطعام كل يوم مسكينًا؛ لأنني فقيرة، لا أملك المال، وجهوني جزاكم الله خيرًا.","title":"حكم من أفطرت في رمضان بسبب العادة الشهرية ولم تقضي","answer":"الجواب:  عليك القضاء متى استطعت، ولو مفرقًا، كلما استطعت تصومين يومًا، يومين ثلاثًا، أربعًا، ثم تفطرين، وهكذا، تصومين بالتدريج حسب القوة والقدرة، كلما استطعت، وكل ما قويت؛ تصومين، والحمد لله، وتضبطين هذا، وتكتبينه، تكتبين ما تصومين حتى تكملي ما عليك، والله يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] أبشري بالخير، عليك التوبة الصادقة، والندم، ثم استمري في القضاء، ولو كان قضاءًا متفرقًا على حسب طاقتك، نسأل الله لك العون والتوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11125/حكم-من-افطرت-في-رمضان-بسبب-العادة-الشهرية-ولم-تقضي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46812.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12953,"question":"أيضًا يسأل المستمع (ص. س. س) من جمهورية مصر العربية بعض الأسئلة، من بينها سؤال يقول: لقد وضعت أمي طفلًا في شهر رمضان من مدة طويلة، ولم تصم، ولم تطعم، وهي الآن لا تقدر على ذلك، كيف توجهونها -جزاكم الله خيرًا- هل تصوم ابنتها بدلًا منها؟","title":"حكم من عجز عن قضاء الصيام","answer":"الجواب:  عليها أن تطعم، ويكفي والحمد لله مادامت تعجز عن الصوم، عليها التوبة إلى الله، والندم على ما مضى من عملها السيئ، وعليها أن تطعم عن كل يوم مسكينًا نصف صاع من التمر، أو من قوت البلد كالرز ونحوه، كيلو ونص يدفع لبعض المساكين عن جميع الأيام التي ما صامتها، ويكفي والحمد لله. المقدم: جزاكم الله خيرًا. الشيخ: نعم، ولو لفقير واحد، أو أهل بيت فقراء، يجمع ويعطاه أهل بيت فقراء، أو جماعة آخرون فقراء مع التوبة والندم والعمل الصالح، نعم. المقدم: جزاكم الله خيرًا، تطعم عن كل يوم مسكينًا.  الشيخ: نعم بعدد الأيام.  المقدم: بعدد الأيام.  الشيخ: وإن كانت لا تحفظها يكفي الظن، إذا كانت لا تحفظ الأيام؛ يكفي الظن والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11170/حكم-من-عجز-عن-قضاء-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47002.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":12964,"question":"شخص أفطر في رمضان متعمدًا، ستة أيام متعمدًا على معصية، هل له قضاء، أو كفارة، أفيدونا بذلك؟","title":"حكم من أفطر أياماً من رمضان متعمداً","answer":"الجواب:  نعم، عليه التوبة والقضاء، عليه التوبة والقضاء، التوبة إلى الله من معصيته، وعليه القضاء، وإن كانت المعصية جماعًا، زنًا؛ فعليه كفارة مع القضاء، والتوبة كفارة عتق رقبة، فإن عجز؛ يصوم شهرين متتابعين، فإن عجز؛ يطعم ستين مسكينًا، إذا كان جماعًا، زنًا، أو لزوجته عليه الكفارة، وعليه التوبة، وعليه القضاء جميعًا.  أما إن أفطر من الأكل، أو الشرب؛ فعليه القضاء مع التوبة، التوبة إلى الله، والقضاء، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11181/حكم-من-افطر-اياما-من-رمضان-متعمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50220.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13011,"question":"لها سؤال آخر تقول: علي قضاء من رمضان، ذات يوم نويت الصيام إلا أنني لم أتمه؛ لأنني أحسست بجوع، فأفطرت على أن أصومه في اليوم التالي، ولكن زميلاتي لمنني كثيرًا ووصفوا ما فعلته بالحرام، والحقيقة أنني لم أكن أعلم ذلك خاصة أنه ليس في رمضان، وظننت أن الأمر فيه سعة، فماذا علي؟","title":"حكم الإفطار في صوم القضاء","answer":"الجواب:  نعم، الذي قال لك أخواتك هو الصواب، لا يجوز لك الإفطار لإحساس بالجوع، بل عليك الصبر حتى تغيب الشمس؛ لأن قضاء رمضان فرض لا يجوز التساهل فيه. وإذا جاع الإنسان وهو صائم في الفرض، أو ظمئ؛ يتصبر، ويتحمل حتى يكمل، إلا إذا خشي الموت، أو مرضًا شديدًا يعلم أنه يترتب على هذا الشيء هذا عذر له في إفطاره، ثم إمساكه، يأخذ ما يزيل الخطر، ثم يمسك إلى الغروب، أما مجرد الجوع، أو مجرد الظمأ الذي ليس معه خطر؛ فهذا لا يسوغ الإفطار في الفريضة، لا في رمضان، ولا في قضاء رمضان، ولا في النذور في الصيام المنذورة، ولا في الكفارات، بل يجب الإمساك والصبر حتى تغيب الشمس، وعليك التوبة إلى الله والاستغفار وقضاء اليوم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11228/حكم-الافطار-في-صوم-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47107.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13118,"question":"رسالة من مستمع لم يذكر اسمه داخل الرسالة، له جمع من الأسئلة.في أحدها يقول: ما حكم صيام وإفطار المسافر لليوم الأول من رمضان إذا أتاه رمضان أثناء سفره؟","title":"حكم الفطر للمسافر أول يوم من رمضان","answer":"الجواب:  الأفضل له الفطر، إذا كان في السفر الأفضل له الفطر في رمضان، هذا هو الأفضل له، في أول رمضان، أو في غيره، الأفضل له الفطر؛ لقول الله سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] ولأن الرسول ﷺ وأصحابه كانوا يفطرون في السفر ويصومون، ودلت السنة على أن الفطر أفضل؛ لقوله ﷺ: ليس من البر الصوم في السفر نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11335/حكم-الفطر-للمسافر-اول-يوم-من-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47313.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":13130,"question":"من اليمن لواء إب المستمع محمد ناجي يسأل ويقول: إنني قد أفطرت يومًا من أيام رمضان، وذلك لأنه اشتد بي العطش، وخشيت على نفسي من الضر، فهل الواجب علي أن أقضي يومًا واحدًا، أم أنه يجب علي تطبيق حكم من أفطر متعمدًا؟ أفيدونا، جزاكم الله خيرًا.","title":"ما الواجب على من أفطر في رمضان خشية الضرر؟","answer":"الجواب:  ليس عليك إلا قضاء يوم واحد، وهكذا من أفطر متعمدًا عليه التوبة، ويقضي يومًا واحدًا، أما حديث: إنه لا يقضي عنه الدهر ولو صامه فهو حديث ضعيف. من أفطر عامدًا؛ فعليه التوبة، والقضاء لما أفطره يومًا، أو أكثر، يقضي ما أفطر، والحمد لله مع التوبة النصوح. أما من اضطر إلى ذلك، كمسألتك الذي خشيت معها الضرر البين، ثم أفطرت؛ فإنك تقضي هذا اليوم، وتمسك باقي النهار.. إذا أفطرت تمسك، وتقضي إلا عند الضرورة، والخوف من المرض الشديد، أو الموت نعم. المقدم: إذا لم يمسك -سماحة الشيخ- إذا أفطر، ولم يمسك بقية يومه؟ الشيخ: يأثم يأثم، يأثم وعليه التوبة إلى الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11359/ما-الواجب-على-من-افطر-في-رمضان-خشية-الضرر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47408.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13132,"question":"رسالة من أحد الإخوة السودانيين، وسؤالها طويل على طريقة إخوتنا في السودان، يقول فيه: أنا سوداني مقيم في المملكة العربية السعودية، والحمد لله على ذلك، لي أخت شقيقة في السودان أرسلت لي بسؤالها؛ لكي أرسله لكم، ونص سؤالها كالآتي: في بداية حياتها أي: في السنة الأولى من سن بلوغها أفطرت ثمانية أيام من أول شهر رمضان، حتى اليوم الثامن، وكانت هذه السنة هي أول سنة تشعر فيها بعلامات البلوغ، وكانت لا تدري بذلك، وواصلت من اليوم الثاني حتى نهاية الشهر، والحمد لله حتى الآن هي مواظبة على صيامها المفروض والتطوع، وعلى صلواتها المفروضة والنوافل، وهي مؤمنة ومتدينة والحمد لله على ذلك، والآن قد ناهزت الثلاثين من عمرها، وتذكرت تلك الأيام الثمانية، وسألت أحد العلماء في السودان وأفتى لها بأن تصوم عن كل يوم شهرين، والآن ومن حوالي ستة شهور هي مواصلة في الصيام، ولا أدري هل هذا هو السبيل الوحيد، أم ماذا، خوفي عليها يكاد يقتلني، كيف تصوم أربعمائة وثمانين يومًا مقابل ثمانية أيام، وهي مصرة على إتمام الأربعمائة والثمانين يومًا، فأفتونا جزاكم الله خيرًا.","title":"حكم من أفطر متعمدًا في رمضان","answer":"الجواب:  هذه الفتوى باطلة لا أساس لها من الصحة، وهذا جهل كبير ممن أفتاها بذلك، ليس عليها إلا الأيام الثمانية فقط، ليس عليها أن تصوم إلا الأيام الثمانية، مع التوبة والاستغفار، وإطعام مسكين، عن كل يوم نصف صاع، كيلو ونص تمرًا، أو رزًا، عن كل يوم تجمع ويعطاها بعض الفقراء، أربعة أصواع عن ثمانية أيام، أو اثنا عشر كيلو عن ثمانية أيام، كل يوم عنه كيلو ونص، يعطاها بعض الفقراء، والصيام ثمانية أيام فقط مثلما أفطرت. أما هذه الفتوى عن كل يوم شهرين فهذه فتوى باطلة، نسأل الله السلامة والعافية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11366/حكم-من-افطر-متعمدا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47410.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13161,"question":"المستمع (ع. ع. أ) سوداني مقيم في الجبيل بعث برسالة، وفيها سؤال طويل لخصته في العبارات التالية، يقول: إنني مسافر في نهار رمضان بالجمال، والمسافة تستغرق خمسة وعشرين يومًا، وعند بداية سفري أفطرت، وبعد نصف المسافة مات جملي، ولم أجد شيئًا أواصل به باقي المسافة، فانتظرت في طريق القوافل مدة أسبوع مفطرًا، ما حكم ما فعلت جزاكم الله خيرًا؟","title":"حكم الفطر للمسافر في نهار رمضان","answer":"الجواب:  لا حرج عليك، أنت مسافر من حين خرجت من بلدك، وفارقت البلد فأنت مسافر، لا تفطر في البلد، لكن الإفطار يكون بعد الخروج من البلد، بعد مغادرة الأبنية، وأنت في سفر تقصر وتفطر.  وهكذا لما مات جملك فأنت تنتظر ليس لك إقامة معلومة، أنت منتظر؛ فلا حرج عليك في القصر والفطر؛ لأنك في حكم السفر، وليس عندك علم متى تسافر من هذه البقعة التي مات فيها الجمل؛ لأنك تنتظر من يمر عليك من المسلمين، فلا حرج عليك والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11415/حكم-الفطر-للمسافر-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_475/47503.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":13169,"question":"بعد ذلك ننتقل إلى رسالة السائلة أم عبدالله من اليمن تقول: كانت لدي ابنة أصيبت بمرض في بداية شهر رمضان، ولم تصم غير ثلاثة أيام، واستمر معها هذا المرض حتى بداية محرم، ثم توفيت،  هل يجب علينا صيام رمضان بدلًا عنها؟ وهل الذي يصوم عنها واحد فقط، أم أنه ممكن أن يشارك الوالدة والأبناء في قضاء الصيام عنها؟ مأجورين.","title":"حكم الصيام عمن مرضت في رمضان ثم ماتت","answer":"الجواب:  إذا كانت ماتت وهي عاجزة عن الصوم من أجل المرض؛ فلا شيء عليها، ولا يصام عنها؛ لأنها معذورة، والله يقول سبحانه: ومَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ يُرِيدُ [البقرة:185] يعني: بعد الشفاء، وبعد السفر، أما إن كانت شفيت، وتساهلت حتى مضت الأيام التي تستطيع فيها الصيام؛ فإنه يشرع لأقاربها أن يصوموا عنها؛ لقول النبي ﷺ: من مات، وعليه صيام؛ صام عنه وليه يعني: قريبه، أمها وأخواتها وإخوانها لا بأس إذا صاموا عنها، ولو اشتركوا في ذلك. فإذا كان عليها -مثلًا- عشرون يومًا، إذا كان عليها عشرون يومًا، فصاموا عنها، صام كل واحد خمسة؛ أربعة، صام كل واحد خمسة، أو خمسة صام كل واحد أربعة، أو عشرة صام كل واحد يومين؛ فلا بأس. أما إذا كانت ماتت وهي في مرضها؛ فلا شيء عليها، ولا يصام عنها. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11424/حكم-الصيام-عمن-مرضت-في-رمضان-ثم-ماتت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51105.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13192,"question":"نعود في بداية هذه الحلقة إلى رسالة وصلت إلى البرنامج من الأخ المستمع بشير شداد، أخونا بشير عرضنا له بعض الأسئلة في حلقة مضت، وفي هذه الحلقة بقي له سؤال واحد يقول فيه: ما هو الحكم في شخص كان لا يصوم رمضان، ثم تاب، وعاد إلى الله، وبدأ يصوم، ما حكم الأشهر التي أفطرها جزاكم الله خيرًا؟","title":"حكم من أفطر أيامًا من رمضان متعمدًا ثم تاب","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  الحكم في ذلك أن عليه أن يقضي ما ترك عند جمهور أهل العلم مع التوبة إلى الله  إذا كان يصلي، أما إذا كان لا يصلي؛ فتارك الصلاة، كافر وليس عليه إلا التوبة، ليس عليه قضاء لصوم ولا صلاة، بل عليه التوبة إلى الله  ثم يستقبل الأمر استقبالًا.  أما إذا كان يصلي، ولكنه تساهل في الصيام؛ فإنه يقضي، فإنه مسلم عاصي؛ فعليه التوبة والقضاء، مع إطعام مسكين، عن كل يوم نصف صاع من قوت البلد، من تمر أو غيره، يجمع ويعطاه بعض الفقراء عن جميع الأيام التي أفطرها، وعليه التوبة إلى الله التوبة الصادقة بالندم على ما مضى من فعله القبيح، والعزم الصادق ألا يعود في ذلك، والله المستعان نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11447/حكم-من-افطر-اياما-من-رمضان-متعمدا-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47601.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13252,"question":"بعد ذلك ننتقل إلى رسالة السائلة (خ. ص. ع) القصيم البكيرية، تقول: نرجو من سماحة الشيخ الرد على هذا السؤال، أخي توفي بحريق، وعمره في التاسعة عشرة، وله الآن متوف له ما يقارب من سنتين، ولم يصم مدة عمره بعد البلوغ إلا يومًا واحدًا فقط، ماذا ينبغي علينا أن نفعل، هل نتصدق عنه، أم نصوم؟ السائلة من البكيرية.","title":"حكم قضاء الصيام عن المتوفى","answer":"الجواب:  إذا كان هذا الميت يصلي؛ فالأفضل لكم أن تصوموا عنه؛ لأنه فرط وتساهل، وقد قال النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه متفق على صحته، والولي هو: القريب، كأخيه، وأبيه، وعمه، ونحو ذلك، فإذا كان عليه صيام رمضان، أو نذر، أو كفارة؛ يستحب لأقربائه أن يصوموا عنه. أما إن كان لا يصلي؛ فالذي ما يصلي كافر؛ فليس عليكم صيام، ولا يشرع لكم الصيام عنه، أما إذا كان يصلي، ولكنه تساهل في الصوم يدعى له بالمغفرة، ويصام عنه، نسأل الله الهداية للجميع. المقدم: اللهم آمين جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11537/حكم-قضاء-الصيام-عن-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51316.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13500,"question":"لها فقرة أخرى قبل أن نختم هذا اللقاء سماحة الشيخ، تقول: نحن ثلاث بنات توفيت والدتنا، وعليها قضاء من صيام رمضان حوالي عشرين يومًا، فهل نتساعد في القضاء عنها بمعنى: كل واحدة سبعة أيام، أم يلزمنا أن نقوم بالقضاء واحدة فقط؟","title":"حكم الاشتراك في قضاء ما على الميت من صيام","answer":"الجواب: لا حرج إذا تساعدوا ما دام قضاء رمضان لا حرج أن يتساعدوا، هذه تصوم يومين، وهذه تصوم أربعة حتى يكملوا لا حرج. أما إذا كان صومًا متتابعًا، مثل الكفارة المتتابعة، أو نذر متتابع يصومه واحد حتى يتابع بينه؛ لقول النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه فإذا كان على الميت كفارة قتل شهرين، أو كفارة ظهار؛ يصام عنه متتابعة، يصوم واحد متتابع، وإن كان في ذلك مشقة؛ كفروا عنه بالإطعام، مثل كفارة الظهار: إطعام ستين مسكينًا، أو الوطء في رمضان: إطعام ستين مسكينًا، وإن صام عنه أحدهم ستين يومًا فجزاه الله خيرًا. أما القتل ما فيه إطعام، ما فيه إلا الصيام، أو العتق، فإذا تيسر في تركته ما يوجب العتق، وتيسر العتق أعتقوا من تركته، فإن كان ما تيسر العتق يصوم عنه بعضهم؛ لقول النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه يصوم واحد منهم متتابعًا، أما إذا كان لا، قضاء رمضان فلا بأس أن يشتركوا فيه؛ لأنه ليس فيه التتابع، فإذا صام هذا أيامًا، وهذا أيامًا؛ صار عشرين يوم عليه.... أربعة، كل واحد صام خمسة؛ فلا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/11811/حكم-الاشتراك-في-قضاء-ما-على-الميت-من-صيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51812.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13516,"question":"السائل مشاري عثمان يقول في هذا  بأنه شاب في الثانوية يبلغ من العمر السابعة عشرة من العمر حصل له قبل ستة أشهر فشل كلوي، يقول: وأنا الآن لم أصم رمضان، وذلك بسبب الفشل، وبعد أسبوع سوف أبدأ بالغسيل الكلوي، فإني سألت عن ماذا أفعل عن عدم الصيام، فقالوا لي: تقوم بتوزيع فدية ثلاثين صاعًا عن رمضان كل صاع لمسكين، أفيدوني أفادكم الله في ذلك.","title":"ما يلزم من لم يصم رمضان بسبب الفشل الكلوي؟","answer":"الجواب: عليك أن تسأل الأطباء المختصين، فإذا كان يرجى شفاؤك؛ فتقضي، تصوم في الأوقات التي ما فيها غسيل، ولا يضرك فيها الصوم، أو في الأوقات التي يزول فيها الغسيل -إن شاء الله- وتبرأ. أما إن كان المرض يستمر، وأن القاعدة أن هذا المرض يستمر، وأنه يضرك الصوم؛ فلا مانع من الإطعام عن كل يوم نصف صاع، عن جميع الشهر خمسة عشر صاعًا. لكن الظاهر -والله أعلم- أن هذا يرجى زواله، وأن الأيام التي ما فيها غسيل يمكن أن تقضي فيها، فالحمد لله، تقضي في الأيام التي ما فيها غسيل إذا كنت تستطيع، أما إذا قرر الأطباء أن هذا يضرك، وأن الصوم يضرك، وأنه لا بد أن تستمر في عدم الصوم، فتطعم عن كل يوم مسكينًا، نصف صاع كيلو ونصف. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11840/ما-يلزم-من-لم-يصم-رمضان-بسبب-الفشل-الكلوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53114.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13519,"question":"السائل مشاري عثمان يقول في هذا  بأنه شاب في الثانوية يبلغ من العمر السابعة عشرة من العمر حصل له قبل ستة أشهر فشل كلوي، يقول: وأنا الآن لم أصم رمضان، وذلك بسبب الفشل، وبعد أسبوع سوف أبدأ بالغسيل الكلوي، فإني سألت عن ماذا أفعل عن عدم الصيام، فقالوا لي: تقوم بتوزيع فدية ثلاثين صاعًا عن رمضان كل صاع لمسكين، أفيدوني أفادكم الله في ذلك.","title":"ما يلزم من لم يصم رمضان بسبب الفشل الكلوي؟","answer":"الجواب: عليك أن تسأل الأطباء المختصين، فإذا كان يرجى شفاؤك؛ فتقضي، تصوم في الأوقات التي ما فيها غسيل، ولا يضرك فيها الصوم، أو في الأوقات التي يزول فيها الغسيل -إن شاء الله- وتبرأ. أما إن كان المرض يستمر، وأن القاعدة أن هذا المرض يستمر، وأنه يضرك الصوم؛ فلا مانع من الإطعام عن كل يوم نصف صاع، عن جميع الشهر خمسة عشر صاعًا. لكن الظاهر -والله أعلم- أن هذا يرجى زواله، وأن الأيام التي ما فيها غسيل يمكن أن تقضي فيها، فالحمد لله، تقضي في الأيام التي ما فيها غسيل إذا كنت تستطيع، أما إذا قرر الأطباء أن هذا يضرك، وأن الصوم يضرك، وأنه لا بد أن تستمر في عدم الصوم، فتطعم عن كل يوم مسكينًا، نصف صاع كيلو ونصف. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11840/ما-يلزم-من-لم-يصم-رمضان-بسبب-الفشل-الكلوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53114.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13546,"question":"تقول في آخر أسئلتها: إذًا هل يجوز الصلاة والصيام عن الميت؟","title":"حكم الصيام عن الميت","answer":"الجواب: يصام عنه إذا كان عليه دين، إذا كان عليه رمضان أو نذور يصام عنه، أو كفارات، يقول النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه يعني: قريبه، يعني: صوم واجب مثل رمضان، مرض ولا صام ثم عافاه الله وتساهل ولا صام ... مات؛ يصام عنه، أو الحائض كذلك أفطرت في رمضان، أو النفساء، ثم ظهر رمضان، وتساهلت، ثم ماتت قبل أن تقضي؛ يقضى عنها، وهكذا كفارة الظهار .. كفارة الجماع في رمضان .. كفارة القتل .. إذا مات وعليه صيام صام عنه وليه، هذا هو المشروع. أما رمضان نفسه إذا كان معذورًا فلا، مثل: أفطر في رمضان مريض، ولكن مات في مرضه، ما يقضى عنه شيء؛ لأنه معذور، مات في مرضه، والتطوع لا يتطوع عنه أحد، لا يصوم أحد عنه تطوعًا، إنما يصوم عنه إذا كان عليه واجب، عليه قضاؤه، فلم يقضه، تساهل؛ فيستحب لأوليائه من الورثة أن يقضوا عنه، ولو جماعة يتقاطعونه من رمضان، كل واحد يصوم بعض الأيام. أما الكفارة لا. لابد يصومها واحد؛ لأنها متتابعة، يصوم كفارة القتل شهرين متتابعين، أو كفارة الجماع في رمضان شهرين متتابعين لمن عجز عن الرقبة، أو كفارة القتل لمن عجز عن الرقبة شهران، هذه يصومها واحد؛ لأنها متتابعة، يستحب لأقربائه أن يصومها منهم واحد هذه الكفارة المتتابعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11868/حكم-الصيام-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51905.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13603,"question":"هذا السائل يقول في هذا  سماحة الشيخ! أنا رجل أبلغ من العمر الخامسة والسبعين، لم أبدأ الصيام في السن الشرعي، وإنما صمت أيامًا، وأفطرت أيامًا، وأنا لا أعرف عدد تلك الأيام، وقد كان ذلك في شبابي، أما الآن -وأحمد الله- فأنا مداوم على الصيام، وذلك من أكثر من ثلاثين عامًا، سماحة الشيخ! ماذا أفعل في الأيام التي فاتتني، وأنا لا أعلم عدد هذه الأيام، علمًا بأنني رجل عاجز، ولا أستطيع أن أقضي؟ جزاكم الله خيرًا.","title":"ما يلزم من ترك الصيام في شبابه وعجز عن القضاء لكبره؟","answer":"الجواب: عليك أن تقضيها بالظن، تجتهد في ظنك، في عددها، ثم تقضيها، وإذا كنت لا تستطيع قضاءها لكبر السن، والعجز؛ تطعم عن كل يوم مسكينًا، نصف صاع من قوت البلد، من تمر، أو أرز، أو حنطة عن كل يوم تجمعها، وتعطيها بعض الفقراء حسب الظن، ظننت عشرين يومًا، ثلاثين يومًا، أربعين يومًا، خمسين يومًا، حسب الظن تصومها، فإن عجزت لأنك كبير السن، ما تستطيع صيام رمضان، إذا كنت عاجزًا؛ فإنك تطعم عن كل يوم مسكينًا، وهكذا العاجز عن رمضان يطعم عن كل يوم مسكينًا، أما إذا كنت تستطيع أن تقضي؛ فعليك القضاء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11938/ما-يلزم-من-ترك-الصيام-في-شبابه-وعجز-عن-القضاء-لكبره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52722.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13767,"question":"يقول هذا السائل أبو معاذ من اليمن: في أحد أيام رمضان المبارك استيقظت بعد أذان الصبح بعشر دقائق تقريبًا، فشربت معتقدًا أن هذه المدة بعد الأذان لا تؤثر، فهل صيامي صحيح لذلك اليوم، أم لا؟","title":"حكم من شرب بعد طلوع الفجر في رمضان","answer":"الجواب: هذا الصيام فيه شبهة واحتمال، فالأحوط لك أن تقضيه؛ لقول النبي ﷺ: دع ما يريبك إلى ما لا يريبك وجوب الصيام فرض عليك، وهذا مشكوك فيه، فالأحوط لك أن تقضيه. نعم.","link":"https://binbaz.org.sa/fatwas/12151/حكم-من-شرب-بعد-طلوع-الفجر-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53606.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":13984,"question":"ما حكم من أخر قضاء أيام من رمضان أحد عشر عامًا وأراد أن يقضيها فقضاها، فهل يبقى عليه شيء؟","title":"حكم من أخر قضاء رمضان عدة سنوات","answer":"الجواب: عليه التوبة من التأخير، وعليه القضاء وعليه إطعام مسكين عن كل يوم أخره، إطعام مسكين عن كل يوم كما أفتى بذلك جماعة من الصحابة ، ثلاثة أمور:\nالأمر الأول: القضاء، يقضي.\nالأمر الثاني: التوبة من التأخير.\nالأمر الثالث: إطعام مسكين عن كل يوم نصف صاع من قوت البلد من تمر أو حنطة أو أرز. نعم.","link":"https://binbaz.org.sa/fatwas/12394/حكم-من-اخر-قضاء-رمضان-عدة-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53908.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":14087,"question":"أختنا تقول: قبل خمس وثلاثين سنة ولدت لي ابنة في رمضان، وبعدها بسنتين ولدت لي ابنة في رمضان، ولم أصم سوى عشرة أيام، أفيدوني جزاكم الله خيرًا، أنا امرأة كما وصفت من حالي كبيرة في السن ومريضة، كيف أتصرف الآن؟","title":"ما يلزم من أفطرت بسبب الولادة ولم تقض حتى كبرت؟","answer":"الجواب: إذا عافاك الله تصومين الأيام التي تركت، إذا عافاك الله عليك أن تصومي الأيام التي عليك من رمضان الأول ورمضان الثاني، وعليك مع ذلك إطعام مسكين عن كل يوم إذا كنت تساهلت في القضاء مع القدرة، عليك إطعام مسكين عن كل يوم نص صاع تمر أو رز، يعني: كيلو ونص تقريبًا عن كل يوم، يعطاه بعض الفقراء ولو واحد، تجمع ويعطاه بعض الفقراء فقير أو فقيرين، أو أهل بيت فقراء يكفي والحمد لله، أما إن كان التأخير من أجل المرض، وإلا ما تساهلت، لكن المرض منعك من الصوم؛ فعليك القضاء فقط، وليس عليك إطعام، بل تقضين الأيام التي تركت، وليس عليك إطعام؛ لأنك معذورة.\nفإن كان المرض ملازمًا، وقرر الأطباء أن هذا المرض ملازم، ولا يرجى برؤه ولا يرجى زواله؛ فليس عليك القضاء، ككبير السن الذي عجز عن القضاء، وعليك إطعام مسكين عن كل يوم والحمد لله، مثلما تقدم ..... نصف صاع تمر أو رز أو بر من قوت البلد، مقداره كيلو ونص تقريبًا يعطاه بعض الفقراء والحمد لله، يجمع كله ويعطاه بعض الفقراء. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12542/ما-يلزم-من-افطرت-بسبب-الولادة-ولم-تقض-حتى-كبرت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61010.mp3","categories":["قضايا المرأة","الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":14092,"question":"أختنا تقول: قبل خمس وثلاثين سنة ولدت لي ابنة في رمضان، وبعدها بسنتين ولدت لي ابنة في رمضان، ولم أصم سوى عشرة أيام، أفيدوني جزاكم الله خيرًا، أنا امرأة كما وصفت من حالي كبيرة في السن ومريضة، كيف أتصرف الآن؟","title":"ما يلزم من أفطرت بسبب الولادة ولم تقض حتى كبرت؟","answer":"الجواب: إذا عافاك الله تصومين الأيام التي تركت، إذا عافاك الله عليك أن تصومي الأيام التي عليك من رمضان الأول ورمضان الثاني، وعليك مع ذلك إطعام مسكين عن كل يوم إذا كنت تساهلت في القضاء مع القدرة، عليك إطعام مسكين عن كل يوم نص صاع تمر أو رز، يعني: كيلو ونص تقريبًا عن كل يوم، يعطاه بعض الفقراء ولو واحد، تجمع ويعطاه بعض الفقراء فقير أو فقيرين، أو أهل بيت فقراء يكفي والحمد لله، أما إن كان التأخير من أجل المرض، وإلا ما تساهلت، لكن المرض منعك من الصوم؛ فعليك القضاء فقط، وليس عليك إطعام، بل تقضين الأيام التي تركت، وليس عليك إطعام؛ لأنك معذورة.\nفإن كان المرض ملازمًا، وقرر الأطباء أن هذا المرض ملازم، ولا يرجى برؤه ولا يرجى زواله؛ فليس عليك القضاء، ككبير السن الذي عجز عن القضاء، وعليك إطعام مسكين عن كل يوم والحمد لله، مثلما تقدم ..... نصف صاع تمر أو رز أو بر من قوت البلد، مقداره كيلو ونص تقريبًا يعطاه بعض الفقراء والحمد لله، يجمع كله ويعطاه بعض الفقراء. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12542/ما-يلزم-من-افطرت-بسبب-الولادة-ولم-تقض-حتى-كبرت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61010.mp3","categories":["قضايا المرأة","الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":14098,"question":"تقول أختنا: إنني مريضة بالسكر والقرحة، فإذا لم أستطع الصوم ماذا يجب علي أن أفعل؟","title":"هل يجب الصيام على المصاب بالسكر والقرحة؟","answer":"الجواب: عليك مراجعة الطبيب المختص، فإذا قرر الطبيب المختص أن الصوم يضرك؛ فأفطري، واقضي بعد العافية، إذا عافاك الله تقضين بعد ذلك، وإن قرر الطبيب المختص أو الأطباء المختصون أن هذا المرض يضره الصوم دائمًا، وأنه فيما يعلمون مرض سوف يستمر ولا يرجى برؤه؛ فإنك تفطرين وتطعمين عن كل يوم مسكينًا والحمد لله، وليس عليك صيام، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].","link":"https://binbaz.org.sa/fatwas/12526/هل-يجب-الصيام-على-المصاب-بالسكر-والقرحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61004.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":14210,"question":"السائل يقول في ثالث أسئلته في عام ألف وأربعمائة واثنين وألف وأربعمائة وثلاثة وألف وأربعمائة وأربعة لم أصم رمضان في هذه الأعوام الثلاث عصيانًا مني أو هذا كان في أول شبابي ولم أقض حتى الآن، هل أقضي هذه الأيام وأخرج كفارة؟الشيخ: أعد. أعد.المقدم: يقول: في أعوام ثلاث سابقة ألف وأربعمائة واثنين وثلاثة وأربعة لم أصم رمضان في هذه الأعوام الثلاث عصيانًا مني، وهذا كان في أول شبابي ولم أقض حتى الآن، هل أقضي وأخرج كفارة أو التوبة تكفي؟ وجهوني سماحة الشيخ.","title":"ما يجب على من أفطر رمضان ثلاث سنوات بدون عذر؟","answer":"الجواب: عليك التوبة والقضاء والإطعام، كل الثلاث، عليك التوبة إلى الله من عدم الصوم، وعليك أن تقضي الصوم، وعليك أن تطعم عن كل يوم مسكينًا بسبب التأخير إذا كنت تستطيع الإطعام، هذا هو الواجب عليك؛ لأن هذه جريمة عظيمة نسأل الله العافية، إذا كنت قد بلغت الحلم حين تركتها، فالواجب عليك القضاء والتوبة إلى الله وإطعام مسكينًا عن كل يوم نصف صاع من قوت البلد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12659/ما-يجب-على-من-افطر-رمضان-ثلاث-سنوات-بدون-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54811.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":14444,"question":"امرأة كبيرة في السن فاتتها أو فاتها صيام رمضان في العام الماضي نظرًا لمرضها، وعدم استطاعتها، وهي تسأل ماذا تفعل في قضاء ذلك الصيام؟ علمًا بأنها الآن لا تستطيع القضاء نظرًا لحالتها الصحية.","title":"ما يجب على من أفطرت بسبب الكبر والمرض؟","answer":"الجواب: إن كانت لا تستطيع القضاء لمرضها فعليها القضاء بعد الشفاء وتمهل؛ لقول الله سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَر [البقرة:185] أما إن كانت لا تستطيع لكبر سنها، وضعف بدنها وعجزها عن الصبر عن الطعام والشراب إلى الليل، فإنها تطعم عن كل يوم مسكينًا، ولا شيء عليها، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/12910/ما-يجب-على-من-افطرت-بسبب-الكبر-والمرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55402.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام","قضايا المرأة"]},{"id":14634,"question":"أحل للمسافر الإفطار في رمضان، وكذلك قصر الصلاة، فكان في الماضي يتعب المسافر لأن السفر كان شاقًا ومتعبًا، ولم تتوفر سبل المواصلات، فكانت على الدواب، وبحمد الله الآن تطورت المواصلات وصارت أكثر من سهلة ومريحة بإمكان المسافر أن يصل مكانه بكل سهولة ويسر، ودون عناء، فهل يجوز له أن يفطر في هذه الحالة؟","title":"حكم الترخص برخص السفر مع عدم المشقة","answer":"الجواب: الرخصة في السفر رخصة عامة في الوقت الحاضر، وقبله وفيما يأتي أيضًا؛ لأن الذي شرعها، وهو علام الغيوب يعلم كل شيء ، ويعلم أحوال العباد في وقت التشريع، وهكذا في الأوقات المستقبلة مثل وقتنا الله يعلم كل شيء ، ولو كان التشريع يختلف لقال: إذا تيسرت الأسفار، أو جاءت مراكب مريحة، فلا تقصروا، ولا تجمعوا، ما قال هذا، لا قاله الرب سبحانه ولا قاله الرسول -عليه الصلاة والسلام-. قال العلماء: إنما قصرت الصلاة في السفر؛ لأنه مظنة للتعب والمشقة، والمظنة يستوي وجودها، وعدم وجودها ما دام أنها مظنة، فالسفر مظنة المشقة، ولكن ليس وجودها شرطًا، فإذا كان السفر مريحًا على إبل مريحة، وعلى أوقات مريحة، فالقصر مشروع، وهكذا الآن في السيارات والطائرات والقطارات والمركبات الفضائية كلهم طريق واحد، يشرع القصر، ويشرع الجمع للمسافر، ولو كان في غاية الراحة؛ لأن الرسول ﷺ حين شرع ذلك لم يقيد، والله في كتابه العظيم لم يقيد بالمشقة.  فعلم بذلك أن المسافر يقصر ويجمع ويفطر، وإن كان سفره مريحًا في السيارة، أو في الطائرة، أو في غير ذلك، والحمد لله على كل حال، نعم. المقدم: الحمد لله جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13133/حكم-الترخص-برخص-السفر-مع-عدم-المشقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_627/nour_62704.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":14883,"question":"يقول: أصابني مرض في عام مضى، وله أكثر من أربعة أعوام في شهر رمضان، ولم أصم ذلك الشهر، ولم أقضه حتى الآن، فماذا يجب علي أن أفعل؟جزاكم الله خيرًا.","title":"حكم من أفطر رمضان ولم يقضه","answer":"الجواب: عليك التوبة إذا كنت أخرته من غير عذر، عليك التوبة إلى الله سبحانه، والندم على ما مضى منك من التفريط، والعزم الصادق أن لا تعود في مثل هذا، وعليك أن تصوم، وتطعم عن كل يوم مسكينًا أيضًا إن كنت قادرًا لأنك مفرط. وقد أفتى جماعة من الصحابة من فرط أن يطعم مسكينًا مع القضاء، فعليك أن تقضي الأيام، وعليك أن تطعم مع كل يوم مسكينًا، نصف صاع من التمر، أو الأرز، أو الحنطة، كيلو ونصف كل واحد عن كل يوم، وعليك مع ذلك التوبة إلى الله عن تقصيرك وتأخيرك؛ لأن الواجب البدار بقضائه قبل رمضان الجديد، وأنت أخرت كثيرًا، فعليك التوبة إلى الله من ذلك، وعليك القضاء قضاء الأيام، سواء متتابعة، أو مفرقة لا بأس، وعليك مع ذلك إن كنت قادر أن تطعم عن كل يوم مسكيناً، تجمع الطعام، وتعطيه بعض الفقراء بعدد الأيام، كل يوم عنه نص صاع، يعني: كيلو ونصف عن كل يوم، تجمعها وتعطيها بعض الفقراء، ولو فقيرًا واحدًا.  أما إن كنت فقيراً ما تستطيع الطعام، فإنك تصوم فقط مع التوبة، ويكفي؛ لأن الله يقول سبحانه: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13379/حكم-من-افطر-رمضان-ولم-يقضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_491/49106.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":14908,"question":"رسالة وصلت إلى البرنامج من المستمع: إبراهيم موسى عبده، سوداني، أخونا يقول في رسالته:جاء رمضان وكنت عامل بناء، وكان معي عمال، وكنت أنا الوحيد بينهم الصائم، حيث كان العمل شاقًا، وفي اليوم الثاني لم أستطع الخروج إلى العمل، وكنت لا أملك طعام ذلك اليوم، وكنت أبًا لعائلةٍ كبيرة، وفي اليوم الثالث خرجت مفطرًا من البيت إلى العمل، ووجدت كل الجماعة كذلك، حيث أفطرت باقي رمضان كله، فماذا عليَّ يا سماحة الشيخ؟ علمًا بأن ذلك كان قبل عدة سنوات.","title":"ما يلزم من أفطر في رمضان بسبب مشقة العمل؟","answer":"الجواب: عليك أولاً القضاء، قضاء الأيام التي أفطرتها في الأوقات المناسبة، في الشتاء، أو في أوقاتٍ لا تحتاج فيها للعمل، تقضي الأيام التي عليك.\nوأما إفطارك، فهذا فيه تفصيل:\nإن كنت تستطيع عملًا يقوم بحالك، ليس فيه إفطار، أو يمكن أن تجد من مالك ما يغنيك عن الإفطار، وتكتفي به مدة رمضان؛ لم يجز لك الإفطار بأسباب العمل، بل عليك أن تصوم رمضان؛ لأن الله أوجب على المسلمين المستطيعين، المقيمين غير المسافرين، أوجب عليهم أن يصوموه في وقته، فعليك أن تصوم مع الناس، إذا استطعت ذلك. أما لو فرضنا أنك لم تستطع، ولم تجد عملًا في أوقاتٍ مناسبة، في الليل، أو في بعض النهار يقوم بحالك، واضطررت إلى الإفطار من أجل العمل، وأنك لا تستطيع الصوم مع العمل؛ جاز لك الإفطار للضرورة، كما يجوز للمريض الذي يشق عليه الصوم، فأنت ضررك أعظم من ضرر المريض، إذا كنت لم تجد شيئًا لنفسك وعائلتك، ولم تستطع أسبابًا أخرى تغنيك عن الإفطار، ولم تجد عملًا في الليل، أو في بعض النهار يغنيك عن هذا العمل، والله يعلم السر وأخفى، ولا تخفى عليه خافية ، فإذا كنت صادقًا ولم تجد عملًا، فأنت معذور، وعليك القضاء. وأما إن كنت قد فرطت وتساهلت فعليك التوبة مع القضاء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13411/ما-يلزم-من-افطر-في-رمضان-بسبب-مشقة-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64003.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":14942,"question":"أيضًا يسأل ويقول: لدي أخ أصيبت يده بكسرٍ في عام ألف وأربعمائة وسبعة، في شهر رمضان المبارك، وكان عمره ذلك الوقت ثنتي عشرة سنة، وقد صام في هذا الشهر خمسة عشر يومًا، وأفطر باقي الأيام، فهل عليه أن يقضيها؟","title":"من أفطر وعمره اثتي عشرة سنة هل عليه قضاء؟","answer":"الجواب: إذا كان لم يبلغ ليس عليه القضاء، ولكن إن قضاه فحسن، وأما إذا كان قد بلغ بإنبات الشعر الخشن حول الفرج، أو بالاحتلام؛ فإنه يقضي هذه الأيام؛ لأنه صار رجلًا، صار مكلفًا، ولو ما بلغ خمسة عشر سنة، نعم، والمرأة مثل ذلك، لكنها تزيد أمرًا رابعًا وهو الحيض، إذا حاضت بلغت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13431/من-افطر-وعمره-اثتي-عشرة-سنة-هل-عليه-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64011.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":15041,"question":"مستمع من الرياض، بعث يسأل ويقول: ما حكم من فرط في شهر رمضان من شدة العمل في الحر، ولقد مضى عليه ستة أعوام، فهل يجزئ عنه الإطعام وما مقداره، أم لا بد من الصيام؟جزاكم الله خيرًا.","title":"حكم من أفطر أيامًا من رمضان للعمل وشدة الحر","answer":"الجواب: أولًا: عليه التوبة إلى الله ، والندم على ما مضى منه، والعزم الصادق ألا يعود في ذلك، ثم عليه القضاء، قضاء ذلك الشهر مع إطعام مسكين عن كل يوم إذا كان يقدر، وأما كان فقيرًا ما يستطيع فإنه يكفيه الصيام، والحمد لله مع التوبة، وهذه جريمة عظيمة، نعوذ بالله، فعليه التوبة إلى الله، والندم والإقلاع، والعزم الصادق ألا يعود، وعليه القضاء والبدار بالقضاء، وعليه مع ذلك إطعام مسكين عن كل يوم، نصف صاع يعني: كيلو ونصف عن كل يوم من طعام بيته، من أرز أو حنطة أو تمر أو غيرها من قوت البلد، فإن كان فقيرًا عاجزًا لا يستطيع ذلك سقط عنه الإطعام، وبقي عليه الصيام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13541/حكم-من-افطر-اياما-من-رمضان-للعمل-وشدة-الحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49311.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":15093,"question":"المستمع: (م. م) من عسيف، بعث يسأل ويقول: ما الحكم في شخص أفطر في رمضان بغير عذر شرعي، وهو في السنة السابعة عشرة تقريبًا، ولا يوجد له أي عذر كما قلت، فماذا يعمل؟ وهل يجب عليه القضاء؟","title":"حكم من أفطر متعمدًا في رمضان","answer":"الجواب: نعم يجب عليه القضاء، وعليه التوبة، عليه التوبة إلى الله  عن تفريطه وإفطاره وعليه القضاء، وأما ما روي عنه ﷺ أنه قال: من أفطر يومًا من رمضان بغير عذر لم يقض عنه صيام الدهر وإن صامه فهو حديث ضعيف مضطرب عند أهل العلم لا يصح. والصواب: أنه عليه القضاء ويكفيه ذلك مع التوبة، إذا قضاه قبل رمضان الآتي، أما إذا تأخر حتى فات رمضان آخر، فعليه مع القضاء إطعام مسكين عن كل يوم، وعليه التوبة إلى الله، التوبة النصوح الصادقة والندم، والعزم الصادق ألا يعود في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13590/حكم-من-افطر-متعمدا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49404.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":15116,"question":"يقول: رأيت بعض الناس في شهر رمضان غير صائمين، ويقولون: إنهم مصابون بمرض ما، ولكن مظهرهم أنهم في تمام العافية، فما هو توجيهكم؟","title":"حكم من أفطر بحجة المرض وظاهرة العافية","answer":"الجواب: هم أعلم بأنفسهم، إذا كان المرض شديدًا، يشق عليهم فلهم عذر؛ لأن الله سبحانه يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] ولو كان مظهره حسنًا؛ لأنه قد يكون المرض داخليًا، ما يظهر للناس، فإذا كان المرض الذي يحس به يؤلمه، ويشق معه الصوم، فالله قد عذره ، ولو كان مع الناس ظاهره الصحة، وهذا شيء بينه وبين الله، عليه أن يراقب الله -جل وعلا-، فإن شق عليه المرض فهو معذور، وله الفطر، ثم يقضي، وإن كان لا يشق عليه وجب عليه الصيام، وأن يتقي الله في ذلك ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13616/حكم-من-افطر-بحجة-المرض-وظاهرة-العافية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49413.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":15120,"question":"الأخت المستمعة: هدى زريد، بعثت تسأل وتقول: أنا مريضة، ولا أستطيع الصيام، وإذا صمت يضرني هل علي كفارة أم ماذا أفعل؟جزاكم الله خيرًا.","title":"ما الواجب على من كانت مريضة ولا تستطيع الصوم؟","answer":"الجواب: هذا فيه تفصيل: إن كان المرض يرجى برؤه، والأطباء يقولون: يرجى، يعالج، ويرجى برؤه، يبقى الدين، يبقى الصوم في الذمة، حتى يشفى المريض، ثم يقضي. أما إذا قرر الأطباء أن هذا لا يرجى برؤه، مرض دائم، فهو مثل كبير السن الذي ما يستطيع يصوم، يطعم عن كل يوم مسكينًا، المريض الذي لا يرجى برؤه، سواء رجل أو امرأة، يطعم عن كل يوم مسكينًا، نصف صاع تمر، أو رز ويجمعها في أول الشهر، أو في آخر الشهر، ويعطيها فقير أو فقيرين أو أكثر، ما هو بلازم كل يوم لفقير، يجمعها جميعًا ويعطيها بعض الفقراء.\nهذا إذا كان ما يرجى برؤه، مرض ذكر الطبيب المختص أنه لا يرجى برؤه، أو طبيبان أحوط مختصان، يقولان: إن هذا لا يرجى برؤه، مرض يستمر، فهذا المريض الذي مرضه يستمر يفطر ويطعم عن كل يوم مسكينًا، يجمعها خمسة عشر صاعًا، إذا كان الشهر تام، أو أربعة عشر ونصف إذا كان ناقصًا، ويعطيها بعض الفقراء، يعطيها بيت فقير، أو شخص فقير، والحمد لله. أما إذا كان يرجى برؤه، يمكن يطيب -إن شاء الله-، هذا يتأجل عليه الصوم، فإذا عافاه الله يقضي؛ لقول الله سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] تبقى في ذمته، حتى يشفيه الله، ثم يقضي، ولو بعد سنتين أو ثلاث، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13620/ما-الواجب-على-من-كانت-مريضة-ولا-تستطيع-الصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49504.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":15200,"question":"هذا سؤال بعث به الأخ إدريس حاج محمد، يقول: إني وقعت في الجماع في نهار رمضان، وما كان لي علم بأن الجماع في الصوم يجب عنه الكفارة والقضاء، وبعد أن علمت بما يلحقني من القضاء والكفارة اشتريت كيسًا من الأرز، وفرقته على المساكين، وكذلك بدأت في الصيام، وكنت أصوم حتى أكملت صيام سبعة وخمسين يومًا، وبعدها مرضت مرضًا شديدًا، لا أستطيع معه الصوم، فقطعت الصيام يومين، وبعدها استأنفته إلى أن أكملت ستين يومًا، فهل تكفي هذه عن الكفارة أم لا؟أفيدونا، جزاكم الله خيرًا.","title":"حكم الإفطار في كفارة الجماع لعذر المرض","answer":"الجواب: قد أحسنت فيما فعلت، والحمد لله، والقطع بالمرض لا يضر؛ لأن المرض عذر شرعي، فالقطع به لا يضر، فلما أكملت الثلاثة الأيام بعد ذلك فقد صح الصوم، وتم، وأديت الكفارة، والحمد لله، وليس مع الصيام زيادة إطعام، الإطعام بدل إذا كان الصيام تيسر، فالصيام هو المقدم، وهو مجزئ، وهو الكفارة اللازمة بعد العتق لمن عجز عن العتق. وأما الإطعام فإنما يطلب عند العجز عن الصيام، فمادمت صمت، فالحمد لله، فليس عليك إطعام، والكيس الذي تصدقت به يكون نافلة، ويكون تطوعًا، لك أجره عند الله، نعم.","link":"https://binbaz.org.sa/fatwas/13699/حكم-الافطار-في-كفارة-الجماع-لعذر-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_671/nour_67104.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":15238,"question":"السائل من تشاد، يقول في هذا السؤال سماحة الشيخ: جدتي كانت لا تصوم مع الناس، وكانت تقول: لا أصوم إلا إذا رأيت الهلال بعيني، وماتت على هذه الحالة، ولم تصم، وأنا الآن أقوم بالتصدق على الفقراء، وأقول: اللهم ألحق أجر هذه الصدقة لجدتي، وأطلب من الله -عز وجل- أن يغفر لها ذنوبها، هل دعائي هذا يصلها، وهذا الأجر يصلها سماحة الشيخ؟","title":"حكم من مات وهو تارك للصوم","answer":"الجواب:  هي غلطانة بهذا العمل، غلطانة وجاهلة، وأنت مأجور على الصدقة عنها، وإذا صمت عنها الأيام التي تركتها، فأنت مأجور، أو غيره من أقاربها، يقول النبي ﷺ: من مات وعليه صيام صام عنه وليه -يعني: قريبه- فإذا صام عنها بعض أولادها أو بعض إخوتها أو بعض أقاربها كان ذلك حسنًا وطيبًا، مع الاستغفار لها، والدعاء لها بالمغفرة والرحمة؛ لأنها جاهلة، نعم.","link":"https://binbaz.org.sa/fatwas/13738/حكم-من-مات-وهو-تارك-للصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56505.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":15467,"question":"هذه سائلة للبرنامج تقول: بأنه في رمضان في عام مضى كانت ترضع طفلها في حالة الصيام، هل عليها القضاء؟","title":"حكم من أرضعت طفلها في رمضان","answer":"الجواب: إذا كانت أفطرت، نعم عليها القضاء، أما إن كانت ما أفطرت كونها ترضع ما يضر، إذا كانت صائمة، أما إذا أفطرت من أجل الرضاع عليها القضاء، وإذا تأخر عن رمضان الثاني تقضي مع إطعام مسكين عن كل يوم، أما إذا قضت قبل رمضان فليس عليها إلا القضاء، وليس عليها إطعام، تقضي الأيام التي عليها، والحمد لله، أما إن تأخرت في القضاء من دون عذر، حتى جاء رمضان آخر، عليها مع القضاء إطعام مسكين عن كل يوم نصف صاع، عن كل يوم مع القضاء. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13990/حكم-من-ارضعت-طفلها-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56815.mp3","categories":["قضايا المرأة","الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":15652,"question":"هذا سؤال من المستمع عبد فاضل الجميلي من العراق - الموصل، يقول: بينما كان راكبًا إحدى السيارات العسكرية؛ إذ تعرض لحادث انقلاب نتج عنه إصابته بكسر في العمود الفقري، مما جعله طريح الفراش، وأفقده بعض الإحساس بأجزاء من جسده، وبما قد يخرج منه من نواقض الوضوء، وقد يحصل عنده أحيانًا انسداد في المجاري البولية، مما جعل الأطباء ينصحونه بالإكثار من الشرب باستمرار، فهو يسأل عن صيام رمضان، ماذا يعمل فيه؟ وماذا يجب عليه فعله إن أفطر وهو بهذه الحالة لا أمل في شفائه من هذا المرض، فهل عليه كفارة وما هي؟ أيضًا يسأل بالنسبة للصلاة، كيف يصلي؟ وكيف يتوضأ؟ وماذا يعمل لو انتقض وضوؤه دون شعور أو إحساس منه بذلك أثناء الصلاة؟ كيف يتصرف في كل هذه الحالات؟","title":"صفة الطهارة وصلاة المريض","answer":"الجواب: أما الصوم فعليه أن يصوم إذا كان يستطيع الصوم، عليه أن يصوم إذا كان يستطيع الصوم، أما إن كان الأطباء قرروا أنه يضره الصوم بسبب المرض الحاضر، فإنه لا يصوم، وإذا قرروا أنه لا يرجى صومه في المستقبل، يعني: لا يرجى برؤه برءًا يعني: يمكنه من الصوم، فإنه لا يصوم أيضًا، وعليه إطعام مسكين عن كل يوم كالشيخ الكبير والعجوز الكبيرة اللذين لا يستطيعان الصوم، فإنهما يكفران بإطعام مسكين عن كل يوم، فهكذا المريض الذي لا يرجى برؤه، قد قرر الأطباء أنه لا يرجى برؤه حكمه حكم الشيخ الكبير والعجوز الكبيرة، يطعم عن كل يوم مسكينًا نصف صاع من التمر، أو غيره من قوت البلد، وهو كيلو ونصف تقريبًا، أما إن كان يرجى برؤه، ويرجى شفاؤه، ولكنه يضره الصوم فإنه لا يصوم حينئذٍ، ولكن متى برئ ومتى عافاه الله يصوم. المقدم: ولا يطعم؟ الشيخ: ولا يطعم. أما الصلاة فإنه يصلي على حسب حاله، عليك -أيها الأخ- أن تصلي على حسب حالك، توضأ إن قدرت على الوضوء بالماء، إن قرب لك الماء وتوضأ إن قدرت، فإن لم تقدر تيمم بعد أن تمسح على الخارج بالمناديل، الخارج من الدبر والقبل إذا دخل الوقت إذا دخل الوقت تمسح أنت ومن يقوم عليك من يخدمك تمسح الخارج بالمناديل ثلاث مرات أو أكثر؛ لأن الرسول ﷺ: نهى أن يستنجى بأقل من ثلاثة أحجار فلا بد من ثلاث مسحات أو أكثر للقبل والدبر، حتى يزال الأثر، وحتى لا يبقى أثر في الدبر والقبل، وبعد هذا توضأ وضوء الصلاة إن قدرت وإلا فالتيمم يكفي، تضرب التراب بيديك، يحضر لك التراب في إناء، أو في كيس أو في خرقة وتضرب التراب بيديك وتمسح وجهك وكفيك مرة واحدة، وتصلي في الوقت، تجمع بين الظهر والعصر وبين المغرب والعشاء، وتصلي الفجر في وقتها حسب طاقتك، وأنت في فراشك على جنبك أو مستلقيًا أو قاعدًا حسب طاقتك: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16] والنبي ﷺ قال: صل قائمًا -للمريض- قال: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا هكذا قال النبي ﷺ للمريض، وأنت مريض، هذا هو الذي يجب عليك أن تصلي قائمًا إن قدرت، فإن عجزت صليت قاعدًا، فإن عجزت صليت على جنبك، فإن عجزت صليت مستلقيًا إلى القبلة، تجعل رجليك إلى القبلة، وتشير بيديك تكبر الإحرام رافعًا يديك للركوع، كذلك تقرأ وتنوي الركوع وتكبر، تنوي الرفع وترفع، تقول: سمع الله لمن حمده، تنوي الركوع، السجود تكبر ناويًا السجود، وهكذا بالنية والكلام.\nأولاً: تنوي الصلاة وتكبر، تأتي بالمشروع من الاستفتاح والقراءة، ثم تنوي الركوع وتكبر، وتقول: سبحان ربي العظيم، سبحان ربي العظيم، سبحان ربي العظيم، وأذكار الركوع، ثم تنوي الرفع، وتقول: سمع الله لمن حمده -بنية الرفع من الركوع- ربنا ولك الحمد، إلى آخره.  ثم تنوي السجود تقول: الله أكبر، ناويًا السجود تقول: سبحان ربي الأعلى، سبحان ربي الأعلى، إلى آخره، ثم تنوي الرفع تقول: الله أكبر، ناويًا للرفع من السجدة الأولى، تقول: رب اغفر لي، رب اغفر لي، رب اغفر لي، ثم تكبر ناويًا السجدة الثانية، وهكذا، بالنية والكلام المشروع، والله يقول سبحانه: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا[البقرة:286] ويقول : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16] ويقول النبي ﷺ: إذا أمرتكم بأمر فأتوا منه ما استطعتم والحمد لله، نعم، شفاك الله. المقدم: بارك الله فيكم. لو كان قرر أنه لا يرجى برؤه من هذا المرض، وكان الحكم كما تفضلتم بأن يطعم عن كل يوم مسكينًا، لكن حصل أن برئ بعد ذلك، فالله قادر على كل شيء، فهل يقضي؟ الشيخ: يجزئه -إن شاء الله-. المقدم: أو يكفي الإطعام؟ الشيخ: إن قضاه فهو أحوط، وإلا يجزئه على الصحيح؛ لأنه فعله على اعتقاد أنه معذور، فإن شافاه الله اختلف العلماء، منهم من قال: يقضي، ومنهم من قال: لا يقضي. فإن قضى فهو أحوط؛ لأنه ظهر أنه غير مأيوس منه، لما برئ ظهر أن الواقع أنه غير مأيوس منه، فيقضي، وقال قوم: فعل ما شرعه الله على اعتقاد أنه غير مرجو البرء فيجزئه ذلك، نعم. المقدم: جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/14194/صفة-الطهارة-وصلاة-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_698/nour_69804.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":15735,"question":"تقول السائلة: عندما كنت في الصف الثاني الثانوي في شهر رمضان، وكان ذلك في فترة الامتحانات، عندما رجعت إلى المنزل كنت أشعر بعطش شديد، فشربت ماءً، فهل أصوم ذلك اليوم، أم أطعم مساكينًا وأصوم يومًا آخرًا عنه؟","title":"حكم من أفطر في رمضان للعطش الشديد","answer":"الجواب: عليك الإمساك مع قضاء يوم، عليك أن تمسكي بعد الشرب، عليك أن تمسكي، وعليك القضاء بعد ذلك من دون إطعام، بل المبادرة بالقضاء، والحمد لله.\nلكن ليس لك الشرب إلا عند العطش الشديد تخشين معه الموت أو المرض، أما العطش الذي يمكن الصبر عليه، فليس لك الشرب، حتى تغيب الشمس في رمضان، وفي صوم الفريضة، أما إذا اشتد العطش وخفت على نفسك من المرض أو الموت فلا بأس، لكن بعد الشرب تمسكين حتى تغيب الشمس، ثم تقضين هذا اليوم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14314/حكم-من-افطر-في-رمضان-للعطش-الشديد","audio":"","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":15828,"question":"هذه السائلة (م. هـ. هـ) تقول: امرأة شكت في أن عليها صيام يوم من رمضان في العام الماضي، وصامت هذا اليوم في اليوم الأخير من شهر شعبان، فهل عليها شيء في فعلها هذا؟","title":"حكم صيام آخر يوم من شعبان قضاء","answer":"الجواب: ليس عليها شيء ما دام قضاء، هذا الواجب عليها، نعم. المقدم: أحسن الله إليكم","link":"https://binbaz.org.sa/fatwas/14417/حكم-صيام-اخر-يوم-من-شعبان-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57520.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":15886,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد، أبا عبدالله، سوداني الجنسية، مقيم في المملكة، أخونا له سؤال يقول فيه: كنت في رمضان ماش في الصحراء واضطررت للإفطار، وبعد رمضان أتممت القضاء في رابع أيام العيد، وقد صادف ذلك اليوم يوم جمعة، ولم أكن أعرف ذلك؛ لأني كنت في الصحراء، هل صيامي صحيح؟ وهل يترتب علي شيء؟جزاكم الله خيرًا.","title":"حكم قضاء الصوم في يوم الجمعة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفصيامك صحيح؛ لأنك لم ترد تخصيص الجمعة، وإنما أردت قضاء ما عليك، فالصوم صحيح، والحمد لله، وإنما النهي فيمن يخصها بالتطوع، فقد ثبت عنه ﷺ أنه نهى عن إفراد الجمعة بالصوم، وقال: لا يصومن أحدكم يوم الجمعة، إلا أن يصوم يومًا قبله، أو يومًا بعده وأنت إنما أردت قضاء ما عليك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14474/حكم-قضاء-الصوم-في-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74501.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16037,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول المرسلة أم أحمد من الأردن عمان، تسأل عدة أسئلة في أحد أسئلتها تقول: لقد جاء علينا شهر رمضان في سنة من السنوات في شهر تموز، وهو شهر حار جدًا، وقد ذهبت لسوء حظي في حفلة زفاف أخي، وكنت صائمة، فكانت النتيجة أنني لم أتحمل الحر الشديد، فأفطرت، هذا الكلام مضى عليه عشر سنوات، وما زلت حتى الآن أتعذب بسبب هذا اليوم، بالرغم من أنني قمت بإعادته، فماذا أفعل حتى أرضي الله تعالى؟ جزاكم الله خيرًا.","title":"حكم الإفطار لشدة الحر","answer":"الجواب: ليس عليك -بحمد الله- إلا التوبة، وقد قضيت اليوم وندمت على ما فعلت، فهذا كافي والحمد لله، يقول النبي ﷺ: التوبة تجب ما قبلها والحمد لله الذي جعل في قلبك خوف الله، ومراقبته، وخشيته سبحانه، احمدي الله على هذا، فإذا كنت ندمت على ما فعلت، وعزمت ألا تعودي لمثله، وقضيت اليوم؛ فهذا كافي، والحمد لله. وإذا كان الفطر من خطر شديد، خشيت معه الموت؛ فلا شيء عليك، والحمد لله، وأما إن كان حصل فيه تساهل؛ فالتوبة كافية والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14663/حكم-الافطار-لشدة-الحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74802.mp3","categories":["قضايا المرأة","الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16056,"question":"رسالة وصلت إلى البرنامج من أحد المستمعين يقول: أنا أصوم رمضان في بلدي، والحمد لله، ولكن لكثرة العمل، وصعوبته أواجه بالإرهاق، فهل علي من شيء؟ أم أترك العمل، وأبدأ بالصيام، جزاكم الله خيرًا.","title":"حكم ترك الصيام بسبب متاعب العمل","answer":"الجواب: عليك أن تصوم كما أمر الله، وأن تدع العمل الذي يضرك، تعمل ما تستطيع، وتكمل صومك، فإذا كان العمل عشر ساعات، ويشق عليك؛ اجعله ست ساعات.. سبع ساعات.. خمس ساعات حتى تستطيع الصيام، ولا تعمل عملًا يضرك، أو يسبب فطرك؛ لأن الله أوجب عليك الصيام، وأنت صحيح سليم، لست مريضًا، ولست مسافرًا، فالواجب عليك أن تصوم، وأن تدع العمل الذي يرهقك، ويتعبك، ويضرك، أو تخففه، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14682/حكم-ترك-الصيام-بسبب-متاعب-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74811.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":16243,"question":"لها سؤال تقول: هل الكحل، وقص الأظافر جائز في نهار رمضان، أم لا؟","title":"ما حكم الكحل وقص الأظافر في نهار رمضان؟","answer":"الجواب: قص الأظافر جائز، لا شك به في رمضان، وفي غيره، وكذلك نتف الإبط، وحلق العانة، كله مشروع في رمضان، وفي غيره. أما الكحل فبعض أهل العلم كره ذلك في النهار؛ لأنه قد ينساب إلى الحلق، والصحيح أنه لا يضر الصيام، الكحل في النهار، لكن تركه، وفعله بالليل يكون أحسن، وأبعد عن الشبهة، وإلا فالصواب أن الكحل في رمضان لا يبطل الصوم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14931/ما-حكم-الكحل-وقص-الاظافر-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80704.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":16261,"question":"أيضًا يسأل سماحتكم لو تكرمتم: عن حكم الصيام بالنسبة له؟ والحال كما علمت؟","title":"حكم من لا يستطيع الصوم لمرض ألَمَّ به","answer":"الجواب: كذلك الباب واحد، إذا كنت تستطيع الصيام؛ فعليك أن تصوم كبقية المكلفين، وإن كان مرضك يمنعك من الصوم لا تستطيع معه الإمساك عن الطعام، والشراب طيلة اليوم، لهذا المرض الذي معك، والشلل الذي معك، فإنك تعتبر مريضًا، والله يقول سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]. فالشلل الذي معك، والمصيبة التي معك إذا كانت تؤثر على معدتك، وعلى نفسك، حتى لا تستطيع الصبر عن الطعام، والشراب كسائر المرضى، فأنت معذور، تطعم عن كل يوم مسكينًا، تجمع الطعام، وتعطيه بعض الفقراء، خمسة عشر صاعًا عن الشهر إذا كان ثلاثين يومًا، وإذا كان الشهر تسعة وعشرين يومًا؛ أربعة عشر صاعًا ونص، تعطيها بعض الفقراء، ولو فقيرًا واحدًا، في أول الشهر، أو في وسطه، أو في آخره. إذا كنت لا تستطيع أن تصوم لهذا المرض الذي لزمك، كالمرضى الآخرين الذين لا يرجى برؤهم، وكالشيخ الهرم العاجز الذي لا يستطيع الصوم، يطعم عن كل يوم مسكينًا، والعجوز الكبيرة التي لا تستطيع الصوم لكبر سنها؛ فإنها تطعم عن كل يوم مسكينًا، نصف صاع، كيلو ونص عن كل يوم، يجمع الطعام، ويعطاه بعض الفقراء، فقيرًا، أو فقيرين، أو أكثر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14947/حكم-من-لا-يستطيع-الصوم-لمرض-الم-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_808/nour_80802.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":16356,"question":"أخيرًا يسأل سماحتكم ما حكم من أفطر في رمضان بدون عذر؟","title":"حكم من أفطر في رمضان بدون عذر","answer":"الجواب: حكمه أنه عاص لله، وعليه التوبة، وقضاء اليوم، إذا أفطر في رمضان من دون عذر؛ فهو قد عصى ربه، وتعرض لغضبه، ولا حول ولا قوة إلا بالله، وعليه التوبة، والقضاء، عليه التوبة حالًا والقضاء بعد رمضان، قضاء اليوم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15050/حكم-من-افطر-في-رمضان-بدون-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71419.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16457,"question":"يقول: والدتي مريضة، ولا تستطيع الصيام، هل تكفيها الكفارة؟ أفيدونا أفادكم الله؟","title":"هل تكفي الكفارة لمن عجز عن الصيام؟","answer":"الجواب: إذا كان مرضها يرجى برؤه؛ فإنها تنتظر حتى تشفى -إن شاء الله- وتصوم، لقول الله سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185].  أما إذا كان مرضها لا يرجى برؤه، أو كانت كبيرة السن، تعجز عن الصيام؛ فإنها تطعم عن كل يوم مسكينًا، ويكفيها ذلك، والحمد لله، تجمع الجميع، ويدفع لبعض الفقراء عن جميع الشهر، ولو فقيرًا واحدًا، في أول الشهر، أو في وسطه، أو في آخره، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15173/هل-تكفي-الكفارة-لمن-عجز-عن-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75519.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":16459,"question":"الرسالة التالية بتوقيع أحد الإخوة المستمعين وقع في نهايتها بقوله: أخوكم في الله: عبدالله، له جمع من الأسئلة في أحدها يقول: عندما يتوب الإنسان، ويمن الله عليه بالهداية، هل يقضي أشهر رمضان التي لم يصمها، وإذا كان الإنسان عامدًا متعمدًا في الإفطار بما هو من شهوات النفس، هل يلزمه ذلك، أم أنه يكفي أن يطعم عن كل يوم مسكينًا؟ جزاكم الله خيرًا.","title":"ما الواجب على من أفطر عدة رمضانات متعمدًا؟","answer":"الجواب: عليه أن يصوم ما أفطر مع التوبة إلى الله  ولا يجزئه الإطعام ما دام يستطيع الصيام، عليه أن يتوب إلى الله  مما فعل، وعليه أن يبادر بالصوم مع إطعام مسكين عن كل يوم إذا كان أخر الصوم إلى رمضان آخر، وهذه جريمة عظيمة، ومنكر عظيم. لكن إن كان لا يصلي؛ صار كافرًا، والكافر لا يقضي، إذا كان لا يصلي؛ كان كافرًا، والكافر لا يقضي في أصح قولي العلماء، فأما إن كان يصلي، ولكنه ترك الصيام؛ فإنه لابد من القضاء مع إطعام مسكين عن كل يوم إذا كان القضاء تأخر إلى رمضان آخر، نسأل الله أن يمن علينا، وعلى كل مسلم بالتوبة النصوح، نعم. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15182/ما-الواجب-على-من-افطر-عدة-رمضانات-متعمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81302.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16478,"question":"تقول: أفطرت من رمضان يومًا واحدًا قبل عدة سنوات ولم أصمه، وفيما أرى أنني لا أستطيع القضاء، فبم توجهونني؟ جزاكم الله خيرًا.","title":"توجيه لمن أفطر في رمضان ولا يستطيع القضاء","answer":"الجواب: إذا كنت لا تستطيعين القضاء لمرض ملازم، أو كبر سن؛ فعليك أن تصدقي بنص صاع عن هذا اليوم، كيلو ونص من التمر، أو نحوه من قوت البلد: تمر، أو حنطة، أو أرز لبعض الفقراء، مع التوبة والاستغفار عما حصل من التأخير والندم. أما إن استطعت القضاء؛ يجب عليها القضاء، تصومين هذا اليوم مع إطعام مسكين عن التأخير، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15190/توجيه-لمن-افطر-في-رمضان-ولا-يستطيع-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75604.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16589,"question":"المستمع (م. ع. م) سوداني بعث يسأل، ويقول: ما حكم من فرط في شهر رمضان نسبة لانشغاله بعمل شاق، وكيف يكون القضاء؟ وإذا كان لم يستطع القضاء هل تكفي الكفارة؟ وإذا أخر القضاء إلى أن يرجع إلى بلده هل له ذلك؟ جزاكم الله خيرًا.","title":"حكم من أفطر في رمضان لأجل العمل","answer":"الجواب: أولًا عليه التوبة من ترك الصيام، عليه التوبة إلى الله -جل وعلا- والندم، والإقلاع، والعزم ألا يعود في ذلك؛ لأن تركه الصيام مع القدرة جريمة، ومنكر، وكبيرة من كبائر الذنوب؛ فعليه التوبة إلى الله بالندم على ما مضى منه، والعزم الصادق ألا يعود فيه، وعليه قضاء رمضان، وإذا قضاه قبل رمضان آخر؛ فليس عليه إلا التوبة، والقضاء، أما إن تأخر القضاء إلى رمضان آخر؛ فعليه مع التوبة والقضاء إطعام مسكين عن كل يوم زيادة يكون عليه ثلاثة أمور: التوبة، والقضاء، وإطعام مسكين عن كل يوم إذا تأخر القضاء إلى رمضان آخر. أما إن قضى قبل رمضان؛ فالتوبة تكفي مع القضاء، يقضي والتوبة، والندم مع ذلك، نسأل الله الهداية للجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15328/حكم-من-افطر-في-رمضان-لاجل-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81710.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16600,"question":"المستمع (م. ع. م) سوداني بعث يسأل، ويقول: ما حكم من فرط في شهر رمضان نسبة لانشغاله بعمل شاق، وكيف يكون القضاء؟ وإذا كان لم يستطع القضاء هل تكفي الكفارة؟ وإذا أخر القضاء إلى أن يرجع إلى بلده هل له ذلك؟ جزاكم الله خيرًا.","title":"حكم من أفطر في رمضان لأجل العمل","answer":"الجواب: أولًا عليه التوبة من ترك الصيام، عليه التوبة إلى الله -جل وعلا- والندم، والإقلاع، والعزم ألا يعود في ذلك؛ لأن تركه الصيام مع القدرة جريمة، ومنكر، وكبيرة من كبائر الذنوب؛ فعليه التوبة إلى الله بالندم على ما مضى منه، والعزم الصادق ألا يعود فيه، وعليه قضاء رمضان، وإذا قضاه قبل رمضان آخر؛ فليس عليه إلا التوبة، والقضاء، أما إن تأخر القضاء إلى رمضان آخر؛ فعليه مع التوبة والقضاء إطعام مسكين عن كل يوم زيادة يكون عليه ثلاثة أمور: التوبة، والقضاء، وإطعام مسكين عن كل يوم إذا تأخر القضاء إلى رمضان آخر. أما إن قضى قبل رمضان؛ فالتوبة تكفي مع القضاء، يقضي والتوبة، والندم مع ذلك، نسأل الله الهداية للجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15328/حكم-من-افطر-في-رمضان-لاجل-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81710.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16618,"question":"رسالة وصلت إلى البرنامج من الدمام، وباعثها المستمع (ف. ح. ش) يقول: ما حكم صيام يوم الجمعة فقط قضاء لا تطوعًا؟ وهل يجب صيام يوم قبله، أو يوم بعده؟","title":"حكم صيام يوم الجمعة قضاء","answer":"الجواب: أما في التطوع فلا بد من صوم يوم قبله، أو يوم بعده؛ لأن الرسول ﷺ نهى أن يصام الجمعة، قال: إلا أن تصوموا يومًا قبله، أو يومًا بعده ولما صامت إحدى زوجاته ﷺ يوم الجمعة، قال: هل صمت أمس؟ قالت: لا، قال: هل تصومين غدًا؟ قالت: لا، قال: أفطري. أما إذا كان عن فريضة؛ فلا حرج -إن شاء الله- لأنه ما خص الجمعة، ولكن وافقت الجمعة أنها وقت راحته، وعدم العمل، أو لأسباب أخرى؛ فصام الجمعة عن قضاء ما عليه من رمضان، أو نذر، أو غير ذلك، فهذا لم يخصها لأنها لفضلها، وإنما صامها من أجل أنها أيسر له في قضاء ما عليه بسبب الأعمال، وإن صام يومًا قبلها، أو يومًا بعدها على سبيل الاحتياط؛ فهو أحسن، من قضائه، يصوم يومين جميعًا، أو ثلاثة: الخميس والجمعة والسبت؛ يكون هذا أبعد عن الشبهة: دع ما يريبك إلى ما لا يريبك. أما النهي فهو جاء في النهي عن التطوع بها، لا يطوع بها وحدها، بل يكون قبلها يوم، أو بعدها يوم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15353/حكم-صيام-يوم-الجمعة-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75823.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":16752,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: سوداني مقيم في الرياض لم يذكر اسمه، إنما ذكر في رسالته قضية ربما تشمله، وتشمل كثيرًا من الرعاة، يقول: كنت راعيًا مع إبل في الصحراء، ومقبلًا على شهر رمضان، ونويت في الأول أن أصوم هذا الشهر، صمت اليوم الأول، وقابلتني فيه مشقة كبيرة، وأنا واقف في الشمس -كما تعلمون- طول اليوم، وليس عندي ظلال، والذي أعمل عنده قال لي: أفطر، وأنا رفضت ذلك، وقلت له: إلا لا بد أن أقضي هذا اليوم كله، وفي اليوم الثاني نويت أن أفطر بقية الأيام كلها، هل علي أن أصوم شهرين متتابعين؟ أو أطعم ستين مسكينًا؟ أو أن أصوم الشهر، وأطعم كل يوم مسكينًا؟ وإذا لم أكن قادرًا على الصيام، وعلى صيام الشهرين المتتابعين أعمل شنو؟ لقد صمت عامين قبل ذلك، وأريد أن أؤدي هذه الفريضة، لكن ظروفي كما تعلمون، جزاكم الله خيرًا.","title":"حكم الفطر في رمضان للرعاة في الصحراء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.   الله -جل وعلا- في كتابه الكريم يقول سبحانه: وَلا تَقْتُلُوا أَنفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا [النساء:29]، ويقول : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] فإذا كنت مضطرًا لهذا العمل، وليس لك قدرة على تركه، وليس هناك وجود عمل آخر تستطيع معه الصوم، وأنت مضطر إلى.. فلك أن تفطر وتقضي، إذا كنت تخشى على نفسك الهلاك، أو المرض، أما إن استطعت أن تجد عملًا آخر، أو تستريح؛ لأن عندك ما يقوتك؛ فاسترح، وصم، والحمد لله، أو تجد عملًا آخر فيه ظل؛ فاترك هذا العمل. وعليك القضاء في ذاك الشهر الذي أفطرته، عليك أن تقضي فقط، عليك القضاء فقط، وإن كنت لم تقض حتى جاء رمضان آخر؛ فعليك مع القضاء إطعام مسكين عن كل يوم، إذا كنت أجلت القضاء بغير عذر شرعي من مرض وسفر، فعليك القضاء مع إطعام مسكين عن كل يوم، وهو نصف صاع من قوت البلد، من تمر، أو أرز، أو غيرهما، كيلو ونصف تقريبًا، ولا حرج عليك، والحمد لله، لكن عليك أن تتقي الله، وأن تحذر الإفطار إلا بعذر شرعي: كالمرض، والسفر، أو الضرورة التي لا تستطيع سواها، كأن تكون راعيًا في الشمس، وليس لك ما يغنيك عن ذلك من مال، ولا عمل آخر، ولا تستطيع البقاء في الشمس، نعم. المقدم: جزاكم الله خيرًا، هذا الحكم سماحة الشيخ. الشيخ: هنا علاج آخر.. وهو يمكن أن يكون معك خيمة بين الغنم، أو الإبل، خيمة، أو شراع إذا استطعت ذلك توجد ذلك بين الغنم، وتجلس فيه؛ حتى تسلم من الشمس، وتستطيع الصوم، نعم. المقدم: جزاكم الله خيرًا، كأن يشدها على إحدى الإبل مثلًا؟ الشيخ: ممكن، يعمل ما يستطيع فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]. المقدم: الله المستعان، جزاكم الله خيرًا، وهذا الحكم له، ولأمثاله من إخواننا الرعاة؟ الشيخ: نعم له، ولأمثاله الحكم واحد. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15494/حكم-الفطر-في-رمضان-للرعاة-في-الصحراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_762/nour_76201.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":16785,"question":"من ضمن أسئلة هذا السائل يقول: هل يجوز لراعي هذه الأغنام الإبل، والأغنام أن يفطر إذا كان قد تعب تعبًا شديدًا، وخصوصًا إذا كان يرعى هذه الأغنام؟ هل يجد رخصة أن يفطر؟","title":"حكم إفطار الراعي لشدة التعب","answer":"الجواب: هذا فيه تفصيل: الواجب عليه أن يصوم إذا كان ليس بمسافر في البلد، وما حول البلد، عليه أن يصوم، أما إذا كان مسافرًا؛ فهذا له فطر السفر، أما إذا كان لا مقيم، ولكنه اشتد عليه الأمر بسبب الرعي، والشمس، والحر؛ فهذا ليس له الفطر، بل يجب عليه الصوم إلا إذا خاف على نفسه، إذا كان ضرورة، ويخشى على نفسه؛ فله أن يفطر؛ لدفع الضرر، ثم يمسك، مثل إذا اشتد به الظمأ، خاف على نفسه؛ يشرب، ثم يمسك، ويقضي هذا اليوم إذا كان ضرورة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15527/حكم-افطار-الراعي-لشدة-التعب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_585/58506.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":16788,"question":"من المستمع مقحم بركة المطيري رسالة ضمنها سؤالًا يقول فيه: أبي كان يصلي، ويصوم -والحمد لله- والآن كبر في السن، وفقد الذاكرة؛ وأصبح لا يعرف الصلاة، ولا الصوم، هل تجب علي زيارته؟ وجهوني جزاكم الله خيرًا.","title":"ما حكم زيارة الوالد الخرف؟","answer":"الجواب: ما دام بهذه الحال لا شيء عليه لاختلال العقل، لا شيء عليه، لا صوم، ولا صلاة .. أما الزيارة فالبر أن تزوره، وأن تلاحظه، وتكرمه، وتجتهد فيما ينفعه، ويصلحه، أو توكل خادمًا يلاحظه مع مراعاتك له أيضًا وزيارته؛ لأن الوالد له حق عظيم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15539/ما-حكم-زيارة-الوالد-الخرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_762/nour_76217.mp3","categories":["الأعذار المبيحة للفطر","من يجب عليه الصوم"]},{"id":16789,"question":"من المستمع مقحم بركة المطيري رسالة ضمنها سؤالًا يقول فيه: أبي كان يصلي، ويصوم -والحمد لله- والآن كبر في السن، وفقد الذاكرة؛ وأصبح لا يعرف الصلاة، ولا الصوم، هل تجب علي زيارته؟ وجهوني جزاكم الله خيرًا.","title":"ما حكم زيارة الوالد الخرف؟","answer":"الجواب: ما دام بهذه الحال لا شيء عليه لاختلال العقل، لا شيء عليه، لا صوم، ولا صلاة .. أما الزيارة فالبر أن تزوره، وأن تلاحظه، وتكرمه، وتجتهد فيما ينفعه، ويصلحه، أو توكل خادمًا يلاحظه مع مراعاتك له أيضًا وزيارته؛ لأن الوالد له حق عظيم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15539/ما-حكم-زيارة-الوالد-الخرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_762/nour_76217.mp3","categories":["الأعذار المبيحة للفطر","من يجب عليه الصوم"]},{"id":17061,"question":"بعد هذا رسالة من المستمع: الفاضل محمد الفاضل من السودان مقيم في المملكة، يسأل عددًا من الأسئلة يقول في أحدها: أفطرت يومًا في رمضان، وكنت قادمًا من سفر، وأتممت في اليوم الثاني، ثم إني أفطرت فهل علي قضاء؟ وجهوني جزاكم الله خيرًا؟","title":"ما حكم المسافر في رمضان إذا وصل بلده مفطرًا؟","answer":"الجواب: الصائم في رمضان، إذا قدم بلده، في أثناء النهار يلزمه الإمساك على الصحيح؛ لأنه زال السفر، فيلزمه أن يمسك إلى غروب الشمس، ولا يعتد بهذا اليوم يقضيه لكن يمسك، وهكذا الحائض والنفساء إذا طهرت في أثناء النهار تمسك.. تغتسل، وتمسك، وتقضي ذلك اليوم؛ لأن الصوم فريضة، فليس له أن يفطر إلا بعذر شرعي، كالمرض والسفر، ما دام موجودًا في البلد الذي.. أو بلده، فإنه يلزمه الإمساك إذا قدم. وهكذا في جميع الأيام حتى يكمل رمضان، يصوم كما يصوم المسلمون، وليس له أن يفطر إلا بعذر شرعي، كالمرض والسفر، وعليه القضاء لما أفطره في السفر، أو في المرض، كما قال الله : وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] واليوم الذي قدم فيه إلى بلده يعتبر حينئذ مقيمًا، فعليه أن يمسك، إذا قدم الضحى، أو الظهر يمسك إلى بقية النهار ... غروب الشمس، وهذا اليوم الذي أفطر بعضه لا يعتد به، بل يقضيه، وهكذا الحائض، والنفساء -كما تقدم- إذا طهرت تمسك، وهكذا المريض إذا عافاه الله في أول النهار، أو في أثناء النهار يمسك حتى يكمل، ولا يعتد بهذا اليوم يقضيه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15853/ما-حكم-المسافر-في-رمضان-اذا-وصل-بلده-مفطرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_721/nour_72107.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":17308,"question":"يقول: أعاني من مرض أسأل الله أن يشفيني منه، ويأتيني هذا المرض في الشهر مرة، أو مرتين، أو في الشهرين مرة، فهل يجوز لي أن أفطر إذا كنت صائمًا عندما يأتيني هذا المرض؟ جزاكم الله خيرًا.","title":"ما حكم الإفطار للمريض؟","answer":"الجواب: نعم إذا شق عليك المرض وأنت صائم تفطر؛ لأن الله سبحانه يقول: فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:184] فالمريض الذي يشق عليه الصوم يفطر، سنة.. رخصة له لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، وهكذا المسافر يفطر. أما المرض الخفيف الذي لا يضرك، ولا يشق عليك فلا تفطر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16168/ما-حكم-الافطار-للمريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83308.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":17321,"question":"يقول: أعاني من مرض أسأل الله أن يشفيني منه، ويأتيني هذا المرض في الشهر مرة، أو مرتين، أو في الشهرين مرة، فهل يجوز لي أن أفطر إذا كنت صائمًا عندما يأتيني هذا المرض؟ جزاكم الله خيرًا.","title":"ما حكم الإفطار للمريض؟","answer":"الجواب: نعم إذا شق عليك المرض وأنت صائم تفطر؛ لأن الله سبحانه يقول: فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:184] فالمريض الذي يشق عليه الصوم يفطر، سنة.. رخصة له لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، وهكذا المسافر يفطر. أما المرض الخفيف الذي لا يضرك، ولا يشق عليك فلا تفطر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16168/ما-حكم-الافطار-للمريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83308.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":17354,"question":"من الخرج المستمعة أمل الصالح تقول: أنا فتاة أبلغ من العمر السابعة عشرة، وقد تذكرت أن علي بعض الأيام من شهر رمضان لم أصمها، وكانت في ذلك الوقت أول سنة من بلوغي، حيث كان عمري إحدى عشرة سنة، وأنا لا أدري عن عدد الأيام التي أفطرتها، وجهوني كيف يكون القضاء؟ جزاكم الله خيرًا.","title":"كيفية قضاء صيام الأيام التي لا يعلم عددها","answer":"الجواب: عليك أن تصومي حسب ظنك واجتهادك، اعملي بالظن في الأيام التي أفطرتيها، ويكفي، والحمد لله، تجتهدين، فإذا كنت تظنيها سبعًا صومي سبعًا، تظنينها ثمانًا ثمانًا، عشرًا عشرًا حسب الاجتهاد، والتحري لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16215/كيفية-قضاء-صيام-الايام-التي-لا-يعلم-عددها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_834/nour_83408.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":17612,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ف. ض. ع) من جمهورية مصر العربية، أخونا قضيته مطولة بعض الشيء، ملخصها: أنه اضطر إلى الإفطار في رمضان، وهناك من قال: إنه يجب عليه القضاء والفدية، ومنهم من قال: بل يجب عليه القضاء فقط، ويسأل سماحتكم عن الحكم جزاكم الله خيرًا.","title":"حكم من أفطر في رمضان للضرورة","answer":"الجواب: إذا كان الإفطار بغير الجماع بل بالماء أو بالأكل ونحو ذلك فلا بأس، ليس عليه كفارة بل عليه القضاء، إذا كان مضطرًا كالمريض أو ما أشبه ذلك بأن اضطر خوف الموت من ظمأ أصابه شدة أصابته أو ما أشبه ذلك إذا كان ضرورة حقيقة، وهو صادق يخشى الموت أو يخشى مرضًا شديدًا .... يفطر وعليه القضاء، أما إن كان عن تساهل فعليه التوبة إلى الله مع القضاء، عليه التوبة مع القضاء والكفارة لا، الكفارة إنما تجب على من جامع زوجته في رمضان.\nوأما الإفطار بغير الجماع فليس فيه كفارة، لكن الواجب على المؤمن أن يحذر الإفطار بغير عذر شرعي كالمرض والسفر كونه يتساهل لأنه عامل لا، يعمل قدر طاقته ولا يفطر، ما يجوز له الإفطار، يعمل قدر الطاقة بعض النهار.. نصف النهار.. ربع النهار، في كل يوم يعمل بقدر طاقته ولا يفطر من أجل العمل.\nالمقصود أنه إذا كان ضرورة شيء اضطره خوفًا من الموت أو من مرض شديد فله الإفطار ولاسيما إذا سأل الأطباء عن مرضه إن كان هناك شيء يخشى منه، أو عرف أن مرضه يضره الصوم معه فإنه يفطر، الله يقول: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، إذا كان مرض بين عرف أنه يضره الصوم أو ضرورة مثل لينقذ إنسانًا سقط في بئر أو في بحر ولا يمكنه ينقذه إلا بالإفطار، ما يستطيع أن ينقذه وهو صائم فأفطر لأجل ضرورة إنقاذ إنسان من بحر أو نهر أو بئر فهو يفطر ومشكور على إنقاذه أخاه ولكن عليه قضاء اليوم فقط وليس عليه كفارة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16546/حكم-من-افطر-في-رمضان-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_842/nour_84209.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":17627,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول أم عبد الرحمن، أم عبد الرحمن لها جمع من الأسئلة تقول في أحدها: إنها امرأة في الخامسة والعشرين من عمرها كانت في سابق حياتها لا تقضي الأيام التي أفطرتها في رمضان ولا تذكر المدة بالتحديد، ولا تعلم إذا كانت في تلك المدة التي لم تصم فيها كانت تصلي أو لا، وتستمر على هذا الحال وتصف نفسها بالجهل وترجو من سماحة الشيخ التوجيه؟","title":"حكم من أفطر في رمضان أيامًا لا يعلم عددها","answer":"الجواب: عليك التوبة إلى الله وقضاء الأيام بالظن، الأيام التي أفطرتها تقضينها بالظن ولو مفرقة من غير تتابع تصومين وتفطرين وتصومين حتى تكملي حسب ظنك؛ شهر.. شهرين.. ثلاثة.. حسب ما ظننت الأيام التي أفطرتيها في السنوات الماضية تقضينها مع التوبة والاستغفار ومع إطعام مسكين عن كل يوم إن كنت قادرة وإن كنت فقيرة لا تستطيعين فالصوم كافي ولا حاجة إلى الإطعام، أما إن قدرتي فأطعمي عن كل مسكين يوم عن عشرة أيام خمسة أصواع عن عشرين يوم عشرة أصواع.. وهكذا كل يوم نص صاع تجمع ويعطاها بعض الفقراء أو بيت فقير والحمد لله، والتوبة تجب ما قبلها والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16556/حكم-من-افطر-في-رمضان-اياما-لا-يعلم-عددها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_844/nour_84402.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":17804,"question":"السائل يقول في هذا السؤال سماحة الشيخ: أنا رجل أبلغ حوالي السبعين وعلي أشهر لا أعرف عددها من رمضان لم أصمها حتى اليوم وأنا بصحة جيدة والحمد لله وأعيش في البادية وأفكر بأن أكفر عن ذلك، ما الحكم وهل يجب علي الصوم؟","title":"حكم التساهل في قضاء أيام رمضان","answer":"الجواب: يجب عليك أن تصوم ما فرطت فيه، عليك أن تصوم وتطعم عن كل يوم مسكينًا نصف صاع عن كل يوم كيلو ونصف؛ لأنك مفرط أخرت الصيام بغير عذر فعليك التوبة إلى الله وقضاء الشهور الماضية من رمضان وإطعام مسكينًا عن كل يوم إن كنت تقدر عندك مال تستطيع الإطعام مع التوبة والاستغفار، وهذا خطأ عظيم، وتفريط كبير، نسأل الله لنا ولك الهداية.\nالمقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16793/حكم-التساهل-في-قضاء-ايام-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77816.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":17893,"question":"السؤال الأخير الذي تعرضه أختنا تقول فيه: البعض من النساء تصوم في فترة حيضها خاصة في رمضان لجهل أو لغيره، فأرجو من سماحتكم التكرم ببيان ما يحرم على الحائض وما يجب عليها عند انتهاء مدة حيضتها؟ جزاكم الله خيرًا.","title":"حكم الصيام وقراءة القرآن للحائض","answer":"الجواب: الحائض لا تصوم ولا يصح منها الصوم، صومها باطل، ولا يجوز لها نية الصوم، وإذا فعلت ذلك فعليها التوبة إلى الله من ذلك، والندم والعزم أن لا تعود في ذلك، وعليها قضاء الأيام اللي وقع فيها الحيض من رمضان، عليها أن تقضيها؛ لأن صومها غير صحيح، والحائض عليها إذا رأت الدم أن تدع الصلاة وتدع الصيام، وأن لا يقربها زوجها بالجماع، وأن لا تمس المصحف، وأن لا تطوف إن كانت في مكة لحج أو عمرة حتى تطهر، ومتى طهرت تغتسل غسل الجنابة، تغتسل بالماء في بدنها كله ثم بعد الغسل تباح لزوجها وتصلي مع الناس وتصوم مع الناس؛ لأن الحيض انتهى، كل هذا مما يتعلق بالحائض. وإذا كانت في حج أو عمرة لا تطوف حتى تطهر ولا بأس أن تلبي وتذكر الله وتسبح وتهلل وتقف مع الناس في عرفات، ترمي الجمار.. تقف معهم في مزدلفة ولو كانت حائضًا لكن لا تطوف حتى تطهر.\nواختلف العلماء هل تقرأ أو ما تقرأ؟\nالصواب: أنها لها أن تقرأ عن ظهر قلب، لا تمس المصحف ولكن تقرأ المحفوظ لها عن ظهر قلبها؛ لأن مدتها تطول فعليها مشقة في ترك القراءة وقد تنسى ما حفظت، بخلاف الجنب فإنه لا يقرأ حتى يغتسل، الجنب لا يقرأ حتى يغتسل. أما الحائض والنفساء فالصواب أنهما تقرأان، لا بأس لكن مما في صدرهما، يعني: عن ظهر قلب لا تقرأان من المصحف، ولو احتاجتا إلى المصحف جاز لها مسه من دون حائل عند مراجعة بعض الآيات يكون في يديها قفازان أو شبه القفازين حتى لا تباشر المصحف وقت طلب الآية أو الآيات التي تحتاج إلى مراجعتها أو تستعين بمن تشاء من أخواتها حتى يراجعن لها المصحف فيما أشكل عليها أو غلطت فيه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16942/حكم-الصيام-وقراءة-القران-للحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84614.mp3","categories":["الأعذار المبيحة للفطر","الحيض والنفاس","قضايا المرأة"]},{"id":17903,"question":"إذا سافرت في شهر رمضان إلى منطقة يباح لي الإفطار فيها وأمضيت مدة عشرين يومًا في ذالكم السفر كيف تنصحونني إذا أردت القضاء؟ جزاكم الله خيرًا.","title":"كيفية قضاء الصيام لمن كان مسافرًا","answer":"الجواب: تقضي إن شئت متتابعًا وإن شئت مفرقًا، والحمد لله، تقضي ما أفطرت سواءً كان ذلك متتابعًا أو مفرقًا، الأمر في هذا واسع والحمد لله، إن تابعت فهو أفضل وإن فرقت فلا حرج.\nالمقدم: جزاكم الله خيرًا. ماذا لو أخر إذا جاء رمضان آخر سماحة الشيخ؟\nالشيخ: لا يؤخر إلى رمضان، الواجب أن يقضي قبل رمضان، فلو أخر بغير عذر عليه القضاء والتوبة وعليه إطعام مسكينًا عن كل يوم زيادة، نصف الصاع عن كل يوم، مع التوبة، ومع القضاء.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16932/كيفية-قضاء-الصيام-لمن-كان-مسافرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84609.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":17952,"question":"هذا سائل يقول سماحة الشيخ: والدي رجل كبير في السن ومريض، ولا يستطيع الصيام، فهل نصوم عنه نحن الأبناء؟ أم ماذا؟ أفتونا مأجورين.","title":"حكم الصيام عن الكبير والمريض","answer":"الجواب: إذا كان مريض مرضًا لا يرجى برؤه ليس عليه صيام، والحمد لله، أما إن كان يرجى برؤه؛ فإنه يصوم بعد ما يشفيه الله، يقضي؛ لأن الله قال: ومَنْ كَانَ مَرِيَضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة: 185]، إذا شفاه الله يقضي ولا تصومون عنه، أما إذا كان عاجزًا -كبيرًا في السن- أو مريضًا لا يرجى برؤه، هذا يطعم عن كل يوم مسكينًا، وليس عليه صيام. \nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16962/حكم-الصيام-عن-الكبير-والمريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59831.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":18111,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول: السائلة نفيسة باشا من السودان أختنا لها ثلاثة أسئلة، في سؤالها الأول تقول: لا أستطيع الصيام بسبب المرض الذي طال معي، ولم أصم أيامًا من رمضان الماضي، وأريد أن أعرف مقدار الكفارة عن كل يوم، وهل إخراج النقود جائز شرعًا أم لا؟","title":"حكم من عجز عن الصيام لمرض","answer":"الجواب: إذا كان المرض لا يرجى برؤه بتقدير الأطباء العارفين، فإنه يجزيك عن كل يوم إطعام مسكين نصف صاع، من التمر أو الأرز أو الحنطة أو غيرها من قوت البلد؛ وذلك مقدار كيلو ونص تقريبًا، ولا تجزئ النقود، بل الواجب إخراج الطعام قبل الصيام أو بعد الصيام، ويكفي أن يدفع ذلك إلى مسكين واحد أو أكثر سواء كان ذلك قبل الصيام أو بعد الصيام. أما إذا كان المرض يرجى برؤه: فإن الواجب عليك القضاء، ولا حرج في تأخير القضاء حتى يتم الشفاء، كما قال الله سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، الله سبحانه أوجب العدة يعني: صيام عدة من أيام أخر، ولم يأمر بالإطعام، وإنما أوجب العدة يعني: عدد الأيام التي أفطرها المريض والمسافر، فما دمت ترجين العافية ولم يقرر من جهة الأطباء أن هذا المرض لا يرجى برؤه فإن عليك أن تقضي بعد الشفاء ولو طال الأمد، ولو بعد سنة أو سنتين أو ثلاث حتى يشفيك الله، ثم تقضي ما عليك من الأيام، أما إن قرر الأطباء المختصون العارفون بهذا المرض أنه لا يزول وأنه مستمر، فإنه يكفيك الإطعام والحمد لله ولا قضاء عليك.","link":"https://binbaz.org.sa/fatwas/17157/حكم-من-عجز-عن-الصيام-لمرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_851/nour_85104.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":18190,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية، وباعثها أحد الإخوة من هناك يقول الاسم الشافعي، أخونا يقول في سؤال له: والدتي تبلغ من العمر سبعين عامًا تقريبًا والحمد لله على كل حال ابتلاها الله بمرض مزمن اضطرت معه إلى الإفطار في رمضان من كل عام، ولا ندري بالضبط تاريخ الإصابة بالمرض، وللأسف لم تفد بإطعام مسكين عن الأيام التي أفطرتها لسببين:الأول: ليس عندها الوعي الديني الكافي بهذا الخصوص.والسبب الثاني: لا يوجد في القرية مساكين يستحقون الفدية.والآن وقد هداني الله وأرشدني إلى الصواب أريد أن أخرج فدية للمساكين عن الشهور التي أفطرتها في السنوات الماضية، لكن لا أعلم عددها بالتحديد، وهي كذلك لا تعلم، وكذلك لا أعلم مقدار الفدية الواجب إخراجها عن هذه الشهور التي مضت، فما رأي سماحتكم في هذا الأمر؟وإذا كانت لي أخت متزوجة وعندها أولاد صغار وهي فقيرة، فهل يفضل أن أعطيها قيمة هذه الفدية، علمًا بأن زوجها على قيد الحياة؟ أفيدوني في هذه القضايا جزاكم الله خيرًا.","title":"حكم من أفطر عدة رمضانات ولا يعلم مقدار ما أفطر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن كانت الوالدة التي سألت عنها حين إفطارها عاجزة فقيرة لا تملك إخراج الفدية فليس عليها شيء؛ لقول الله : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] أما إن كانت قادرة ولكن تركت ذلك من أجل الجهل؛ فإنك تخرج عنها أو تخرج هي بنفسها عن كل يوم نصف صاع من قوت البلد أرز أو حنطة أو غيرهما من قوت البلد، ومقدار ذلك كيلو ونص تقريبًا عن كل يوم تجمع ويعطاها بعض الفقراء ولو في قرية أخرى في غير قريتها، ليس من اللازم أن يكونوا في قريتها، بل ولو في قرية أخرى تنقل إليهم هذه الكفارة، ولا يجوز إخراج نقود بل يعطون طعامًا. وإذا كانت أختك فقيرة وزوجها فقير فلا مانع من دفع هذه الكفارة إلى زوجها يعطاها الزوج؛ لأنه المنفق والمسئول عن الزوجة والأولاد فإذا كان فقيرًا فإنها تدفع إليه، أما إن كان غنيًا فإنه هو الذي يقوم بنفقة الزوجة والأولاد، ولا يعطى النفقة الكفارة المذكورة، بل يلتمس فقراء غير زوج أختك مطلقًا سواءً كانوا في البلد أو في غير البلد. وإذا كنتم لا تعرفون عدد الأشهر فإنكم تكتفون بالظن تجتهد الوالدة وأنت تجتهدان جميعًا في تحري الأيام التي أفطرتها الوالدة في سنتين أو ثلاث أو أربع على حسب الظن الغالب، ثم تخرجون هذه الكفارة بناءً على الظن الغالب الذي منك أو منها أو منكما جميعًا لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]. نعم.","link":"https://binbaz.org.sa/fatwas/17227/حكم-من-افطر-عدة-رمضانات-ولا-يعلم-مقدار-ما-افطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_855/nour_85501.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":18385,"question":"منذ فترة طويلة، أفطر شخص في نهار رمضان متعمدًا، ولم يقض حتى الآن، مع العلم بأنه مستمر في الغربة هنا في المملكة، ماذا يجب على هذا الشخص؟ وماذا يفعل؟","title":"حكم مغترب أفطر متعمدًا في رمضان","answer":"الجواب: يجب عليه أن يقضي الأيام التي أفطرها مع التوبة إلى الله، ويجب عليه أن يصوم كل ما دخل رمضان مع الناس، يجب عليه الصوم، ويجب عليه قضاء ما أفطر فيه، وعليه التوبة إلى الله مما حصل من الفطر والتأخير، عليه التوبة إلى الله  وعليه قضاء الأيام التي أفطرها، وعليه الصوم كلما دخل رمضان أن يصوم مع الناس، حكمه حكم المقيمين ما دام عزم على الإقامة في البلد للعمل، أو لأسباب أخرى يلزمه أن يصوم مع الناس. أما لو كانت الإقامة محدودة، وهو مسافر، الإقامة محدودة أربعة أيام فأقل؛ فإنه له الفطر ثم يسافر، أما إذا كان لا، الإقامة غير محدودة، الإقامة طويلة، أو عزم على الإقامة الطويلة؛ فهذا يلزمه الصوم، وليس له الفطر إلا إذا كانت الإقامة أربعة أيام فأقل، أو لا يدري متى يسافر، يقول: اليوم أسافر ، غدًا أسافر، ما عنده إقامة معينة، هذا له أن يفطر حتى يعزم على الإقامة، أو يرجع إلى بلده مثل بعض الناس يقدم من بلده لحاجة يدور غريم، يدور سلعة يريد يشتريها، يقول: اليوم أرتحل .. باكر أرتحل، هذا له الفطر حتى يعين إقامة معينة أكثر من أربعة أيام، فإذا عزم على الإقامة أكثر من أربعة أيام وجب عليه الصيام عند جمهور أهل العلم. وأما إذا قدم بنية السفر لكنه يطلب حاجة، إما غريمًا يطلبه، أو سلعة يطلبها، أو ما أشبه ذلك لا يدري هل يقيم يوم أو يومين أو ثلاث هذا له الفطر، وله القصر حتى يعزم على الإقامة، أو يرجع إلى بلده، فإذا عزم على الإقامة أكثر من أربعة أيام وجب عليه الصوم، ووجب عليه القضاء؛ قضاء ما أفطره قبل رمضان القادم .نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17470/حكم-مغترب-افطر-متعمدا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78410.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":18479,"question":"السائل من الدمام مصري ومقيم هناك (م. ع. م) يقول في هذا السؤال الذي فهمت منه يقول: بأن زوجته مريضة بالصرع منذ صغرها، مما يُلزمها باتباع برنامج علاجي صعب يصعب معه الصيام لشهر رمضان المبارك، ولكنها في السنوات القليلة الماضية كانت تصر على الصيام، وبفضل الله كانت تتمكن من صيام معظم أيام الشهر الكريم رغم ما كانت تتعرض له من تعب ونوبات قلبية نتيجة عدم تناولها للعلاج في نهار شهر رمضان المبارك، مع العلم بأنه بعد الانتهاء من الشهر الكريم لا تستطيع صيام ما عليها من أيام أفطرتها خلال شهر رمضان الكريم، أفيدونا مأجورين:هل لها أن تصوم شهر رمضان وهي على هذه الحالة؟ وماذا يجب عليها إزاء عدم صيامها سنوات كثيرة سابقة، وكذلك إزاء الأيام التي عليها من شهر رمضان في السنوات الثلاث الأخيرة؟ جزاكم الله خيرا، سماحة الشيخ.","title":"حكم العاجز عن صيام رمضان بسبب المرض المستمر","answer":"الجواب: عليها أن تصوم إذا استطاعت، هي أعلم بنفسها، إن استطاعت عليها أن تصوم وتقضي ما فاتها من أيام الحيض، وإن لم تستطع للمرض الذي أصابها تطعم عن كل يوم مسكينًا، إذا كان مرضها مستمرًا معها ما فيه حيلة يعني: عرض على الأطباء ولا وجدوا حيلة، فهذا تطعم عن كل يوم مسكينًا، أما إذا استطاعت أن تصوم، ولو بعض الصيام ثم تقضي فإنها تصوم وتقضي ما فاتها، هذا هو الواجب عليها؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]، ويقول سبحانه: فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ[البقرة:184]. والله جل وعلا كتب علينا الصيام قال سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ[البقرة:183]، والنبي ﷺ أخبر أن صيام رمضان من أركان الإسلام الخمسة، فإذا استطاعت فعليها أن تصوم، وإذا أفطرت بعض الأيام تقضيها، وإن كان اشتد معها المرض، ولم تستطع الصوم أفطرت فهي على كل حال تراعي حالها، تصوم إذا استطاعت، وتفطر إذا شق عليها، ثم تقضي. فإن كانت لا تستطيع أبدًا، ويشق عليها مشقة بينة تطعم عن كل يوم مسكينًا إذا كان لا يرجى برؤها، تعرض نفسها على الأطباء الخاصين؛ فإذا كان لا يرجى برؤها من هذا المرض فالحمد لله تطعم عن كل يوم مسكينًا، تجمع الطعام خمسة عشر صاعًا عن الشهر، وتعطيه بعض الفقراء، خمسة عشر صاعًا يعني: خمسة وأربعين كيلو، كل يوم عنه: كيلو ونصف، تعطيه بعض الفقراء، هذا هو الواجب عليها إذا كانت لا تستطيع الصوم بشهادة الأطباء المختصين من أجل مرضها، نسأل الله لنا ولها العافية. المقدم: اللهم آمين، أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17577/حكم-العاجز-عن-صيام-رمضان-بسبب-المرض-المستمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78520.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":18567,"question":"كنت في يوم من أيام رمضان مريضة، فخفت على نفسي أن أصوم ذلك اليوم؛ ليزداد حالي سوءًا أو أجوع كثيراً، وأكلف نفسي ما لا تطيق، فسألت والدي ومن معي في البيت هل أفطر أم لا؟ فقالوا لي: بأنهم لا يعلمون شيئًا عن ذلك هل أفطر أم لا؟ ولكني أفطرت يا سماحة الشيخ، ثم ذهبت إلى الطبيب، ولم يلزمني بالإفطار، ثم قالوا لي بعد ذلك بعض الناس: إن عليّ كفارة وإني آثمة، فما الحكم؟جزاكم الله خيرًا.","title":"حكم الفطر في رمضان لمن خشي على نفسه الضرر","answer":"الجواب: ليس عليكِ بأس، والحمد لله، ما دام أنك شعرت بمرض يشق عليكِ معه الصيام، فالله يقول سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ[البقرة:185]، فإذا كنت غلب على ظنكِ خوف الأذى خوف المضرة من هذا المرض، فأنت معذورة، والحمد لله، ولا شيء عليك إلا القضاء، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17681/حكم-الفطر-في-رمضان-لمن-خشي-على-نفسه-الضرر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_734/nour_73403.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":18597,"question":"هذه السائلة أم مصعب من الأردن تقول: بأنها امرأة مريضة منذ سنتين، ولم تصم شهر رمضان للسنتين السابقتين؛ لعدم استطاعتها؛ وذلك لكونها تتناول علاجًا في اليوم ثلاث مرات أو أربع مرات، وقد أقبلت هذه السنة.وتقول: أستفسر من سماحتكم وأنا على نفس المرض السابق، أفيدوني أفادكم الله ماذا يترتب علي عند الصيام؟","title":"ما يجب على من أفطر في رمضان بسبب المرض؟","answer":"الجواب: لا يلزمك الصوم إذا كان يشق عليك لا يلزمك؛ لأن الله يقول سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] وإذا عافاك الله تقضين العامين الأولين وهذا الثالث إذا عافاك الله ، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/17702/ما-يجب-على-من-افطر-في-رمضان-بسبب-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91814.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":18759,"question":"هذه سائلة تقول: أنجبت ولدين من ضمن أبنائي خلال شهر رمضان المبارك، فأفطرت كوني -تقول-: امرأة نفساء ومرضعة، وبعد مرور اثنين وعشرين عامًا تريد أن تقضي ذلك الدين في هذين الشهرين، فما حكم القضاء؟ وهل يترتب على ذلك كفارة إلى جانب الصيام؟ تذكر بأنها امرأة فقيرة الحال.","title":"حكم القضاء والكفارة على من أخرت الصيام لمدة طويلة","answer":"الجواب: عليها التوبة إلى الله، على المرأة المذكورة التوبة إلى الله سبحانه من هذا التأخير الكثير، وعليها أن تقضي رمضان الذي أفطرت فيه، جميع الأيام التي أفطرتها عليها أن تقضيها، إن كان الولدين في سنة واحدة توأمين عليها أن تقضي الشهر، وإن كان كل واحد في رمضان فعليها أن تقضي الشهرين، إذا كان كل واحد في رمضان في سنة فعليها أن تقضي الشهرين، وإن كانا توأمين خلال شهر واحد فعليها أن تقضي رمضان. وعليها أن تطعم مسكين عن كل يوم إذا كانت تستطيع، وإن كان ما تستطيع فقيرة يكفي الصيام، والحمد لله، مع التوبة إلى الله ، أما إن كانت تستطيع فعليها إطعام مسكين عن كل يوم مع الصيام نصف صاع مع الصيام يجمع خمسة عشر صاع عن رمضان يعطاها بعض الفقراء، وإن كان رمضانين ثلاثين صاع يعطاها بعض الفقراء مع الصيام؛ لأن سؤالها محتمل أنها.......، ويحتمل أنها في سنتين، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17887/حكم-القضاء-والكفارة-على-من-اخرت-الصيام-لمدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79013.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":18772,"question":"رجل توفي وعليه صيام من رمضان، وله أبناء رجال ونساء، فهل يجب عليهم القضاء عن أبيهم؟ وهل يكون القضاء عليهم جميعًا، أم على الرجال فقط؟ وهل كلهم يصومون في يوم واحد، أم كل واحد يصوم يومًا واحدًا عنه؟","title":"كيفية قضاء الصوم عمن مات وعليه صوم","answer":"الجواب: يقول النبي ﷺ: من مات وعليه صيام صام عنه وليه إذا مات وعليه قضاء من رمضان، أو صوم نذر شرع لأقربائه أن يصوموا عنه، فإن صام عنه واحد أو جماعة فقد أحسنوا، جزاهم الله خيرًا، إذا صام عنه واحد جميع الأيام، أو صام جماعة: هذا صام ثلاثة وهذا صام أربعة، وهذا صام يومين، فقد أحسنوا، جزاهم الله خيرًا؛ لأنه ﷺ قال: من مات وعليه صيام صام عنه وليه. فالسنة لأقربائه أن يصوموا عنه، فإن كان قضاء رمضان صاموا عنه، وإن كان كفارة متتابعة صاموها متتابعة كشهرين متتابعين يصومها واحد متتابعة منهم يستحب له ذلك، فإن كان يوم واحد صامه عنه بعض أقاربه من رمضان أو نذر. المقصود: أن السنة لأقاربه أن يصوموا عنه ما وجب عليه من الصيام إذا مات ولم يصم، سواءً كان من رمضان، أو من الكفارات، لكن إذا كانت الكفارة متتابعة ككفارة القتل كفارة الظهار صاموها متتابعة يصومها واحد؛ لأن التتابع يكون من واحد يوم بعد يوم متتابعة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17904/كيفية-قضاء-الصوم-عمن-مات-وعليه-صوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79110.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":18888,"question":"رسالة وصلت إلى البرنامج من لواء تعز بالجمهورية العربية اليمنية، وباعث الرسالة أحد الإخوة من هناك يقول: ابن العمدة، أخونا له مجموعة من الأسئلة يسأل في سؤاله الأول ويقول: هل المفطر في رمضان لعذر شرعي ككبر السن مثلًا، ويقوم بالإطعام، هل له مثل أجر الصائم؟","title":"أجر من أفطر في رمضان لعذر شرعي","answer":"الجواب: يرجى له ذلك؛ لأنه معذور شرعًا، والمعذور له حكم الصائم، يقول النبي ﷺ: من مرض أو سافر كتب الله له ما كان يعمل وهو صحيح مقيم فالكبير في السن الذي عجز عن الصيام له حكم الصائمين؛ لأنه معذور لولا العجز لصام، فهو معذور وعليه إطعام مسكين عن كل يوم إذا كان يستطيع ذلك. أما إن كان عاجزًا لا يستطيع فإنه لا شيء عليه لا صوم عليه ولا إطعام عليه؛ لقول الله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18030/اجر-من-افطر-في-رمضان-لعذر-شرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_923/nour_92302.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":18966,"question":"تقول سماحة الشيخ الأخت السائلة: من عليه القضاء وإطعام المساكين أو الفقراء بالنسبة للمفطر في رمضان، فإن أطعم مسبقًا لكل الأيام، ثم بعد الفراغ من الإطعام يصوم عدد الأيام التي عليه، هل هذا صحيح أم لا؟","title":"حكم تقديم الإطعام على الصيام في كفارة قضاء رمضان","answer":"الجواب: لا بأس، قدم الإطعام أو أخره، سواء قدمه أو أخره، إذا كان عليه أيام من رمضان أخرها إلى رمضان آخر تأخرت، يقضي ويطعم عن كل يوم مسكين، سواء قدم الإطعام أو أخره عن كل يوم نصف صاع، يعني: كيلو ونصف عن كل يوم، إذا أخرها إلى بعد رمضان آخر، نعم.","link":"https://binbaz.org.sa/fatwas/18101/حكم-تقديم-الاطعام-على-الصيام-في-كفارة-قضاء-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88224.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":19018,"question":"الأخت المستمعة (ش. ع. ح) من جدة بعثت تقول: إلى سماحة الوالد الشيخ عبد العزيز بن عبد الله بن باز حفظه الله ذخرًا للإسلام والمسلمين، أما بعد:السلام عليكم ورحمة الله وبركاته. إنني -يا سماحة الشيخ- حائرة في أمري! والمشكلة هي أن والدتي أخبرتني قريبًا أنها في الماضي لم تقض أيام الحيض والنفاس، وهو عن جهل منها في ذلك، وهي الآن كبيرة في السن، لا تقدر أن تقضي هذه المدة الطويلة، وأيضًا مصابة بالسكر والضغط، وهي الآن في حيرة أيضًا من أمرها، هل الصدقة تجزئ عن ذلك؟ وما هو مقدارها؟ أفتونا جزاكم الله خيرًا.","title":"حكم من أفطرت لعذر ثم كبر سنها ولا تستطيع القضاء","answer":"الجواب: أولًا: عليها التوبة إلى الله  عما فعلت من الترك، والتوبة حقيقتها أمور ثلاثة: هذه التوبة ندم على الماضي، وإقلاع من الذنب، وترك له خوفًا من الله  وتعظيمًا له، وأمر ثالث وهو العزم الصادق ألا يعود في الذنب. فالوالدة التي سألت عنها أيها السائلة جزاك الله خيرًا، عليها أن تتوب إلى الله بالندم على ما مضى، الندم الصادق، وعليها مع ذلك أن تطعم عن كل يوم مسكينًا، ما دامت لا تستطيع القضاء عليها أن تطعم عن كل يوم مسكينًا، إذا كانت تستطيع، إذا كانت عندها قدرة مالية تطعم عن كل يوم مسكينًا نصف صاع، بصاع النبي عليه الصلاة والسلام، ومقداره كيلو ونصف تقريبًا، من قوت البلد: رز، أو تمر، أو حنطة، أو شعير.. ونحو ذلك. هذا هو الواجب عليها مع التوبة والاستغفار عما مضى، والله  يتوب على التائبين، وأنت جزاك الله خيرًا أعينيها على هذا الخير إذا كانت تعجز عن بعض الكفارة، وأنت تقدرين فأعينيها والله في عون العبد ما كان العبد في عون أخيه فكيف بالوالدة. نعم الله المستعان. المقدم: نعم نعم، جزاكم الله خيرًا. تقدم الرز صافي دون أن يكون معه شيء شيخ عبد العزيز . الشيخ: وأيضًا عليها أن تعتني بعدد الأيام ولو بالظن إذا شق العلم ولو بالظن، يكتفى بالظن عند العجز عن العلم في مقدار الأيام، وإذا كان مع الرز أو الحنطة إدام هذا أفضل وأفضل منه لحم أو سمن هذا كله طيب وإلا فهو يكفي وحده، التمر وحده والرز وحده والحنطة وحدها تكفي، لكن إذا كان مع الرز ونحوه إدام صار أفضل. نعم. المقدم: نعم نعم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18187/حكم-من-افطرت-لعذر-ثم-كبر-سنها-ولا-تستطيع-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_927/nour_92705.mp3","categories":["قضايا المرأة","الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":19147,"question":"الطبيب -أيضًا- نصحني بألا أصوم لحاجتي الشديدة لشرب الماء مع جفاف الحلق، نتيجة لتناول العقاقير المهدئة، فهل الصوم ساقط عني؟ أم تجب الفدية؟","title":"حكم من نصحه الطبيب بعدم الصوم","answer":"الجواب: هذا يختلف إن كنت تستطيعين الصوم فعليك الصوم، وليس لك أن تدعي الصوم وتفدين، أما إذا قرر الطبيب الثقة، أو الطبيبان الثقتان، أن المرض الذي معك يمنع الصوم وأنه يضرك الصوم ضررًا بينًا، دائمًا دائمًا، فهذا يكفيك الإطعام، كفارة عن كل يوم إطعام مسكين، كالشيخ الكبير العاجز الذي يعقل، ولكنه لا يستطيع الصوم لكبر سنه، فإنه يطعم عن كل يوم مسكينًا، كالمريض الذي لا يرجى برؤه، ويشق عليه الصوم من جنس الكبير، يعني: من جنس الشيخ الكبير العاجز يسقط عنه الصوم ويؤدي عن كل يوم نصف صاع من التمر أو غيره من قوت البلد للفقراء، وإذا جمع الجميع عن الشهر كله وأعطاه فقيرًا واحدًا أو فقيرين أو أكثر فلا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18333/حكم-من-نصحه-الطبيب-بعدم-الصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_886/nour_88605.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":19159,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من ليبيا، وباعثها مستمع من هناك رمز إلى اسمه بالحروف (ع. ع. أ) أخونا رسالته مطولة بعض الشيء يقول فيها: إنني مرضت مرضًا شديدًا مما اضطرني إلى السفر إلى الخارج خارج العالم الإسلامي للعلاج، وقد جاء رمضان الكريم، وأنا في الخارج فأمرني الطبيب المسيحي بالإفطار بحجة أن الأدوية قد تضرني إذا لم أتناول الطعام وخاصة الماء، الأمر الذي اضطرني إلى الإفطار وطلب مني الطبيب الاستمرار في العلاج مدة طويلة، وعند عودتي استشرت طبيبًا مسلمًا فطلب مني الإفطار هذا العام كذلك، ولقد جربت الصوم ولكنني شعرت بتدهور صحتي، ماذا علي من العمل تجاه هذا الوضع؟ وهل علي إطعام بدلاً من الصوم؟ مع العلم أنني موظف محدود الدخل، أرجو منكم الرد وإعادة السكينة والطمأنينة إلى نفسي، والسلام عليكم ورحمة الله؟","title":"حكم من أفطر رمضان لمرض","answer":"الجواب: لا حرج عليك يا أخي! في الإفطار ما دمت تحس بالمرض، وتتعب من الصوم، وقد أرشدك الأطباء إلى ذلك فلا حرج عليك، وهكذا إذا كانت الأدوية منظمة، تحتاج إليها في النهار فأنت مباح لك الإفطار، يقول الله سبحانه: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] حتى لو ما كان عندك طبيب إذا أحسست بالمرض الذي يشق معه الصوم وتتعب معه في الصيام فإنك تفطر لوجود المرض بنص القرآن الكريم، ولو ما كان هناك طبيب يقول لك كذا وكذا. فالمرض عذر شرعي متى وجد وشق عليك معه الصوم، فلك الإفطار، وإن كنت لم تستشر طبيبًا في ذلك. أما الآن فعليك القضاء والحمد لله متى شفيت من المرض تقضي ولو بعد مدة؛ لأن الله قال: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] المعنى: فعليه عدة من أيام أخر، يعني: يقضيها. فأنت يا أخي! إذا شفاك الله وتمت صحتك تقضي والحمد لله، ولا حرج عليك في ذلك وأبشر بالخير، شفاك الله وعافاك. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18252/حكم-من-افطر-رمضان-لمرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_930/nour_93003.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":19181,"question":"الأخ إبراهيم أيضًا يسأل ويقول: أفتونا لو تكرمتم عن الرجل الشيبة الهرم الذي لا يستطيع الصوم وهو فقير لا يجد شيئًا في حوزته، ماذا عليه؟ نرجو الإجابة جزاكم الله خيرًا.","title":"حكم من عجز عن الصيام لكبر سنه ولا يستطيع الإطعام لفقره","answer":"الجواب: ليس عليه شيء إذا كان عاجزًا عن الصوم، وفقيرًا عن الإطعام؛ ليس عليه شيء فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16] فليس عليه صوم، ولا إطعام؛ لعجزه عنهما عن الصوم، والإطعام، هذا إذا كان عقله معه، أما إذا كان الهرم قد غير عقله فليس عليه شيء حتى ولو كان عنده مال؛ لأنه زال عنه التكليف بزوال العقل، إذا خرف تغير عقله فلا صوم عليه، ولا إطعام. أما إذا كان عقله معه لكنه عاجز عن الصوم عاجز عن الإطعام فلا صوم عليه ولا إطعام؛ لأن الله سبحانه يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]، لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا[البقرة:286]. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18380/حكم-من-عجز-عن-الصيام-لكبر-سنه-ولا-يستطيع-الاطعام-لفقره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79813.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":19190,"question":"أخونا يقول: مرضت ولم أتمكن من صيام رمضان، فأخرته إلى رمضان من السنة القادمة، هل يجزئ الصوم فقط، أم هناك كفارة وما هي؟","title":"حكم من أفطر في رمضان وأخر القضاء حتى رمضان آخر","answer":"الجواب: إذا كنت أخرته من أجل المرض كفاك القضاء فقط، إذا كان المرض استمر معك إلى رمضان الآخر، فإنه يكفيك القضاء والحمد لله ولا شيء عليك. أما إذا كنت تساهلت وأنت طيب فلم تقض إلا بعد رمضان، فإنك تجمع بين الأمرين، تقضي الأيام التي أفطرتها وتطعم عن كل يوم مسكينًا، نصف صاع بصاع النبي عليه الصلاة والسلام، ومقداره كيلو ونص تقريبًا، من قوت البلد، من تمر، أو أرز، أو حنطة، ونحو ذلك، يعطاها بعض الفقراء، تجمع ويعطاها بعض الفقراء. نعم.","link":"https://binbaz.org.sa/fatwas/18364/حكم-من-افطر-في-رمضان-واخر-القضاء-حتى-رمضان-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93212.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":19212,"question":"الرسالة التالية من إحدى الأخوات المستمعات تقول المرسلة (ش. س. ف) أختنا لها سؤالان، في سؤالها الأول تقول: منذ خمس سنوات، وفي شهر رمضان المبارك أفطرت أربعة أيام، وليس لي عذر غير التعب، وسؤالي هو: هل يجب علي القضاء؟ وهل علي كفارة؟ وما هي؟ جزاكم الله خيرًا.","title":"حكم من أفطر في رمضان عمدًا بغير عذر شرعي","answer":"الجواب: نعم عليك ثلاثة أمور: الأمر الأول: التوبة إلى الله سبحانه، والندم على ما فعلت من التقصير والإفطار بغير حق؛ فإن كنت أفطرت من أجل الحيض فلا حرج، لكن عليك التوبة إلى الله من أجل التأخير؛ لأنك أخرت القضاء، والواجب أن تقضي قبل رمضان الذي بعد رمضانك الذي أفطرت فيه. فعليك التوبة إلى الله سبحانه من هذا التأخير، أو من الإفطار بغير عذر إن كنت أفطرت بغير عذر، والتوبة لازمة من كل ذنب، وهي الندم على الماضي من الذنب، والإقلاع منه والعزم الصادق أن لا يعود العبد إليه، هذه التوبة. وعليك مع ذلك قضاء الأيام الأربعة؛ لأن الله قال: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] وإذا أفطر غير المريض وغير المسافر فمن باب أولى أن يقضي وعليه التوبة إلى الله. وأمر ثالث: وهو إطعام مسكين عن كل يوم نصف صاع، يعني: كيلو ونصف تقريبًا من التمر أو من الحنطة أو من الرز أو غيرها من قوت البلد، عن كل يوم نصف صاع يعني: صاعين بصاع النبي ﷺ، يعطاها بعض الفقراء ولو فقيرًا واحدًا يكفي، والله جل وعلا المسؤول أن يغفر لنا ولك، وأن يهدينا وإياك وسائر المسلمين. المقدم: جزاكم الله خيرًا ونفع بكم.","link":"https://binbaz.org.sa/fatwas/18387/حكم-من-افطر-في-رمضان-عمدا-بغير-عذر-شرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_933/nour_93307.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":19214,"question":"المستمع محمد أحمد علي حسان، يمني مقيم في الرياض يقول: امرأة أفطرت في رمضان لمدة ثلاث سنوات، وذلك أنها كانت تحمل ويصادف ذلك رمضان، وللجهل بحكم الصيام ولم يكن هناك مرشدين لها، وقد أفتاها بعض المجتهدين بأن عليها الإطعام دون القضاء، نرجو التوجيه في هذه المسألة، جزاكم الله خيرًا.","title":"حكم الحامل والمرضع إذا أفطرتا في رمضان","answer":"الجواب: الصواب الذي دلت عليه الأدلة الشرعية أن عليها القضاء دون الإطعام، والقول بأن عليها الإطعام قول غلط في أصح قولي العلماء، وإنما عليها القضاء دون الإطعام إذا كانت معذورة من أجل الحمل أو الرضاع أو مرض فعليها القضاء فقط. أما إن كانت تساهلت وحصل لها وقت تقضي فيه لكنها تساهلت فعليها مع القضاء إطعام مسكين عن كل يوم نصف صاع بصاع النبي ﷺ وهو يقارب كيلو ونص تقريبًا من قوت البلد من تمر أو أرز أو غير ذلك عن تأخيرها الصيام. وعلى المرأة أن تتقي الله دائمًا في صومها وصلاتها وغير ذلك كالرجل، كل منهما عليه أن يتقي الله وأن يهتم بأمر دينه وأن يجتهد في أداء الحق الذي عليه، فالصوم ركن من أركان الإسلام الخمسة، وهو صوم رمضان. فالواجب على الرجل والمرأة المكلفين العناية بهذا الأمر وعدم التفريط فيه، فإذا أفطر الإنسان لمرض أو سفر أو أفطرت المرأة لحيض أو حمل أو رضاع يشق معه الصيام فإنها تقضي، وتبادر بالقضاء من حين تستطيع، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا. كونها تركت الصيام للجهل ولقلة التوعية الإسلامية في وطنهم كما يذكر. الشيخ: ما يمنع القضاء؛ لأن هذا أمر معروف بين المسلمين، ومن الأمور المشهورة المعروفة التي لا تخفى على أحد، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18389/حكم-الحامل-والمرضع-اذا-افطرتا-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_933/nour_93309.mp3","categories":["قضاء الصيام","الأعذار المبيحة للفطر"]},{"id":19486,"question":"أريد أن أصوم الأيام التي فاتتني عندما بلغت، ولكن لا أعرف كم عدد أيامها لأنني بلغت وأنا في الثانية عشرة من العمر، وكنت أصوم وأفطر لما ألقاه من تعب، وعندما بلغت الرابعة عشرة من العمر أتممت الصيام، كما قلت: لا أعرف عدد تلك الأيام التي أفطرتها وجهوني، جزاكم الله خيرًا.","title":"حكم من أفطر في رمضان ولا يعرف عدد الأيام التي أفطره","answer":"الجواب: عليك أن تحسبي الأيام بالظن، والاجتهاد والتحري، فإذا غلب على ظنك أنها عشرة أيام، خمسة عشر يومًا صمتيها، تصومين ما تيسر من ذلك حسب الطاقة، حسب الظن الغالب لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا[البقرة:286] عليك أن تجتهدي وتتحري الأيام التي أفطرتيها بعد البلوغ، وعليك أن تصوميها سواء كانت متتابعة أو مفرقة، وعليك مع ذلك إطعام مسكين عن كل يوم لتأخر صيامك لها، وهو نصف صاع من التمر أو الأرز ونحوهما إذا كنت قادرة على ذلك. أما إذا كنت فقيرة لا تستطيعين فإنه يكفي الصوم، ولا حاجة إلى الإطعام لقوله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18737/حكم-من-افطر-في-رمضان-ولا-يعرف-عدد-الايام-التي-افطره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_945/nour_94507.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":19499,"question":"هذا السائل ضيف الله القصيم الرس، يقول: سماحة الشيخ لدي أخ أصيب بمرض وهو فشل كلوي، وقد أفطر يومين من العام الماضي، وشد عليه المرض في رمضان الحالي، وبقي في المستشفى خمسة عشر يومًا من رمضان، ونصحه الأطباء بعدم الصوم حفاظًا على صحته، ولم يصم الشهر كله، و هل عليه قضاء أم صدقة؟ وما هو معيار الصدقة هل هو صاع أم نصف صاع لليوم الواحد نرجو توضيح ذلك مأجورين؟","title":"حكم من أفطر في رمضان لمرض","answer":"الجواب: ما دام يرجو العافية فعليه الصوم عليه القضاء، قضاء الفائت من رمضان السابق، وقضاء رمضان الحالي، فإذا قرر الأطباء المختصون أنه مأيوس من شفائه وعود الصحة إليه فإنه يطعم عن كل يوم مسكين نصف صاع، عن كل يوم مسكين نصف صاع، كيلو ونص من قوت البلد من تمر، أو شعير، أو حنطة، أو أرز لكل واحد يعني: خمسة عشر صاعاً للشهر كله عن كل يوم نصف الصاع، ولو لمسكين واحد، أو مسكينين، أو ثلاثة، نعم. المقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18753/حكم-من-افطر-في-رمضان-لمرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94604.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":19518,"question":"في آخر أسئلة هذه السائلة أم عايض من الخرج تقول: عندما كانت صغيرة فاتها أعوام لم تصم فيها، تقول: بأن أهلي لم يوجهوني على الصيام والصلاة، ولم أعرف أمور ديني، والآن أنا عمري ثمانية وعشرين سنة، وماذا يلزمني من كفارة وصيام؟","title":"حكم قضاء الصوم لمن تركت جاهلة","answer":"الجواب: إذا كانت لا تصلي عليها التوبة، التوبة مما تركت من الصلاة والصوم ويكفي.\nأما إن كانت تصلي ولكن تركت الصيام فعليها القضاء عما مضى.\nأما إذا كانت لا تصلي جاهلة تركت الصوم والصلاة لعدم التعليم فعليها التوبة ويكفي، والحمد لله. المقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18767/حكم-قضاء-الصوم-لمن-تركت-جاهلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93933.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]},{"id":19605,"question":"يا سماحة الشيخ، هذه السائلة (ف. ط. ح) المنطقة الشرقية تقول: أرجو أن تجيبوني على هذا  ماذا يجب على المرأة التي أحست بعطش شديد في نهار رمضان، وكانت حامل في الشهر التاسع، فخافت على نفسها وشربت الكثير من الماء، وبعد انقضاء رمضان قضت ذلك اليوم ولم تطعم، أفيدوني هل يلزمها شيء غير ذلك؟","title":"حكم الفطر في رمضان للحامل والمرضع","answer":"الجواب: الحامل إذا شق عليها الصوم شرع لها الإفطار وتقضي، فالحامل والمرضع إذا شق عليهما الصيام أفطرتا وقضتا وليس عليهما إطعام، تقضيان بعد العيد بعد الولادة، وكذلك إذا كبر الطفل ولم يشق عليها الصوم تقضي، وإذا شق الصوم وهي ترضع أو وهي حامل أفطرت والحمد لله، رخص النبي ﷺ للحامل والمرضع في الفطر، حذرًا من المشقة عليها وعلى الطفل. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18870/حكم-الفطر-في-رمضان-للحامل-والمرضع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94916.mp3","categories":["الأعذار المبيحة للفطر","صلاة المسافر"]},{"id":19624,"question":"هذه رسالة -سماحة الشيخ- وصلت من مستمع للبرنامج لم يذكر أختكم في الله السائلة، أختكم في الله (هـ. ع. ش) فلسطين تقول: سماحة الشيخ أمي أفطرت عدة رمضانات من حوالي ثمانية وعشرين سنة لعذر شرعي، ولم تصم لجهلها، وهي الآن كبيرة في السن، ولا تستطيع أن تصوم، فماذا عليها؟","title":"حكم من أفطر ولم يقض حتى كبر ولا يستطيع الصوم","answer":"الجواب: عليها الإطعام عن كل يوم مسكينًا، نصف صاع من قوت البلد من الرز، أو تمر، أو بر عن كل يوم، كل شهر خمسة عشر صاع، كل شهر رمضان من السنوات الماضية التي ما صامتها خمسة عشر صاع، لكل مسكين نصف صاع ولو مسكينًا واحدًا، لو جمعتها، وأعطتها مسكينًا واحدًا أجزأ؛ والحمد لله، مع التوبة والاستغفار. نعم.","link":"https://binbaz.org.sa/fatwas/18891/حكم-من-افطر-ولم-يقض-حتى-كبر-ولا-يستطيع-الصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94822.mp3","categories":["الأعذار المبيحة للفطر","قضاء الصيام"]}]
